# -*- coding: utf-8 -*-
"""
build_national_assembly.py  (v2: photo-referenced, photoreal showcase)

Korean National Assembly Proceeding Hall (Yeouido, Seoul) with its grounds,
modelled from Wikimedia Commons reference photos, PBR materials from Poly
Haven (CC0), baked ambient occlusion and Poly Haven tree models, exported as
GLB for a three.js scene.

Target: Blender 5.2 LTS. Run from the Text Editor or with
    exec(compile(open(path, encoding="utf-8").read(), path, "exec"), {"NA_STAGES": {...}})
Stages (default: all): build, vegetation, bake, colliders, thumbnail, export, verify, blend.
"build" deletes and rebuilds everything this script owns (idempotent).

Conventions: metres, Blender Z up, ground at z = 0, building footprint centred on
the origin, FRONT (grand stairs) toward -Y. glTF converts to Y up, so in
three.js the front faces +Z.

---------------------------------------------------------------------------
EXPECTED INPUT FILES (all Poly Haven CC0 unless noted; see ASSETS.md)
---------------------------------------------------------------------------
OUTPUT_DIR/textures/
    granite_tile_03_{diff,nor_gl,rough,ao}_4k.jpg      facade granite (recoloured pale)
    corrugated_iron_02_{diff,nor_gl,rough,ao}_4k.jpg   dome copper (recoloured verdigris)
    granite_tile_04_{diff,nor_gl,rough,ao}_2k.jpg      podium, stairs, granite paving, kerbs
    granite_wall_{diff,nor_gl,rough,ao}_2k.jpg         podium retaining walls (rough ashlar)
    concrete_tiles_02_{diff,nor_gl,rough,ao}_2k.jpg    sidewalks and paths
    asphalt_01_{diff,nor_gl,rough,ao}_2k.jpg           drives
    leafy_grass_{diff,nor_gl,rough,ao}_2k.jpg          lawn
    yellow_flower_mulch_{diff,nor_gl,rough,ao}_2k.jpg  planting beds
OUTPUT_DIR/models_src/<id>/<id>_2k.blend (+ textures/)  Poly Haven tree models:
    pine_tree_01, tree_small_02, jacaranda_tree
OUTPUT_DIR/sky_2k.hdr       kloofendal_43d_clear_puresky (2k HDR)
OUTPUT_DIR/sky_bg_8k.jpg    the same sky, Poly Haven tonemapped JPG at 8192x4096

Generated by this script (into textures/): derived_* recoloured maps, the
hedge/flower foliage maps, the Taegukgi flag texture and the baked building AO.

OUTPUTS (OUTPUT_DIR): national-assembly.glb, vegetation.glb, colliders.json,
thumbnail.jpg, national-assembly.blend, ASSETS.md
"""

