def _cli():
    """Arguments after '--':  --stage build[,vegetation...]  [--ao 2048]  [--log path]"""
    import sys
    out = {}
    if "--" in sys.argv:
        args = sys.argv[sys.argv.index("--") + 1:]
        for k in ("--stage", "--ao", "--log", "--views", "--species", "--samples", "--only"):
            if k in args and args.index(k) + 1 < len(args):
                out[k] = args[args.index(k) + 1]
    return out


