def _ensure_gltf_addon():
    """The bundled glTF add-on, enabled for this session only (preferences are never saved)."""
    try:
        import addon_utils
        if not addon_utils.check("io_scene_gltf2")[1]:
            addon_utils.enable("io_scene_gltf2", default_set=False, persistent=False)
    except Exception as e:          # report, the export stages will fail loudly if it is missing
        print("[NA] glTF add-on check:", e)


