DEBUG_LOG = CLI.get("--log", globals().get("NA_DEBUG_LOG"))


def log(*a):
    print("[NA]", *a)
    dbg(" ".join(str(x) for x in a))


def dbg(msg):
    if DEBUG_LOG:
        with open(DEBUG_LOG, "a", encoding="utf-8") as f:
            f.write("%.1f %s\n" % (time.time(), msg))
            f.flush()
            os.fsync(f.fileno())


def srgb_to_linear(c):
    return c / 12.92 if c <= 0.04045 else ((c + 0.055) / 1.055) ** 2.4


def hex_srgb(h):
    h = h.lstrip("#")
    return tuple(int(h[i:i + 2], 16) / 255.0 for i in (0, 2, 4))


def hex_linear(h):
    return tuple(srgb_to_linear(c) for c in hex_srgb(h))


def r2(v):
    v = round(float(v), 2)
    return 0.0 if v == 0 else v


def sock(node, ident, out=False):
    socks = node.outputs if out else node.inputs
    return next(s for s in socks if s.identifier == ident)


def bbox_pts(pts):
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    zs = [p[2] for p in pts]
    return (min(xs), max(xs), min(ys), max(ys), min(zs), max(zs))


def world_bbox(objs):
    pts = []
    for ob in objs:
        if ob.type == "MESH":
            pts.extend(ob.matrix_world @ Vector(c) for c in ob.bound_box)
    return bbox_pts(pts)


def tag(idb):
    idb[OWN_TAG] = 1
    return idb


# ---------------------------------------------------------------------------
# Cleanup
# ---------------------------------------------------------------------------
def remove_collection(c):
    for ch in list(c.children):
        remove_collection(ch)
    for ob in list(c.objects):
        data = ob.data
        bpy.data.objects.remove(ob, do_unlink=True)
        if data is not None and data.users == 0 and isinstance(data, bpy.types.Mesh):
            bpy.data.meshes.remove(data)
    bpy.data.collections.remove(c)


def cleanup(keep_vegetation=False):
    for sc in list(bpy.data.scenes):
        if sc.name.startswith(TMP_SCENE_PREFIX):
            bpy.data.scenes.remove(sc)
    for name in OWN_COLLS:
        if keep_vegetation and name == COLL_VEG:
            continue
        c = bpy.data.collections.get(name)
        if c:
            remove_collection(c)
    for _ in range(2):
        for datas in (bpy.data.meshes, bpy.data.materials, bpy.data.images, bpy.data.node_groups,
                      bpy.data.cameras, bpy.data.lights, bpy.data.worlds, bpy.data.objects,
                      bpy.data.curves, bpy.data.collections):
            for d in list(datas):
                if d.users == 0 and (d.get(OWN_TAG) or d.name.startswith(("NA_", "AV_", "TMP_"))):
                    datas.remove(d)


