def tex(asset, mapname, res):
    return os.path.join(TEXTURE_DIR, "%s_%s_%s.jpg" % (asset, mapname, res))


def check_inputs():
    missing = []
    for asset, res in PH.values():
        for m in ("diff", "nor_gl", "rough", "ao"):
            if not os.path.isfile(tex(asset, m, res)):
                missing.append(tex(asset, m, res))
    for p in (SKY_HDR,):
        if not os.path.isfile(p):
            missing.append(p)
    if missing:
        raise FileNotFoundError("Missing inputs (see script header):\n  " + "\n  ".join(missing))


def load_image(path, non_color):
    img = bpy.data.images.load(path, check_existing=True)
    if img.get(OWN_TAG) is None:
        tag(img)
    img.colorspace_settings.name = "Non-Color" if non_color else "sRGB"
    return img


def image_array(path):
    import numpy as np
    img = bpy.data.images.load(path, check_existing=False)
    w, h = img.size
    px = np.empty(w * h * 4, dtype=np.float32)
    img.pixels.foreach_get(px)
    bpy.data.images.remove(img)
    return px.reshape(h, w, 4), w, h


def save_array(arr, path, quality=93, fmt="JPEG"):
    import numpy as np
    h, w = arr.shape[:2]
    img = bpy.data.images.new("TMP_save", w, h, alpha=(arr.shape[2] == 4 and fmt == "PNG"))
    out = np.ones((h, w, 4), dtype=np.float32)
    out[..., :arr.shape[2]] = np.clip(arr, 0.0, 1.0)
    img.pixels.foreach_set(out.ravel())
    img.file_format = fmt
    img.save(filepath=path, quality=quality)
    bpy.data.images.remove(img)


def recolour_stone(src, ao, dst, base_hex, contrast, keep_chroma, ao_amt=0.6):
    """Re-tone a Poly Haven stone diffuse map to a target colour, keep its grain."""
    import numpy as np
    d, w, h = image_array(src)
    a, _, _ = image_array(ao)
    rgb = d[..., :3]
    lum = rgb @ np.array([0.2126, 0.7152, 0.0722], dtype=np.float32)
    z = (lum - lum.mean()) / max(float(lum.std()), 1e-4)
    base = np.array(hex_srgb(base_hex), dtype=np.float32)
    chroma = rgb - lum[..., None]
    out = base[None, None, :] * (1.0 + contrast * z[..., None]) + keep_chroma * chroma
    out *= (1.0 - ao_amt) + ao_amt * a[..., :1]
    save_array(out, dst)


def derive_textures():
    import numpy as np
    a, r = PH["facade"]
    recolour_stone(tex(a, "diff", r), tex(a, "ao", r), os.path.join(TEXTURE_DIR, "derived_granite_facade_diff_4k.jpg"),
                   "#D6D3CC", 0.10, 0.25)
    rr, w, h = image_array(tex(a, "rough", r))
    half = rr[..., :3].reshape(h // 2, 2, w // 2, 2, 3).mean(axis=(1, 3))
    save_array(half, os.path.join(TEXTURE_DIR, "derived_granite_facade_rough_2k.jpg"))
    a, r = PH["podium"]
    recolour_stone(tex(a, "diff", r), tex(a, "ao", r), os.path.join(TEXTURE_DIR, "derived_granite_podium_diff_2k.jpg"),
                   "#BDB9B0", 0.16, 0.35)
    recolour_stone(tex(a, "diff", r), tex(a, "ao", r), os.path.join(TEXTURE_DIR, "derived_granite_paving_diff_2k.jpg"),
                   "#A29D93", 0.22, 0.4, ao_amt=0.8)
    # second stone for kerbs, edging, border courses and bands: dark grey granite
    recolour_stone(tex(a, "diff", r), tex(a, "ao", r), os.path.join(TEXTURE_DIR, "derived_granite_dark_diff_2k.jpg"),
                   "#5C5955", 0.26, 0.3, ao_amt=0.7)
    a, r = PH["ashlar"]
    recolour_stone(tex(a, "diff", r), tex(a, "ao", r), os.path.join(TEXTURE_DIR, "derived_granite_ashlar_diff_2k.jpg"),
                   "#C2BDB3", 0.22, 0.35, ao_amt=0.75)
    # Copper patina from corrugated iron: rank-equalised luminance on a verdigris
    # ramp centred on sRGB #86B8A8, streaks along the corrugation (texture columns).
    a, r = PH["copper"]
    d, w, h = image_array(tex(a, "diff", r))
    ao, _, _ = image_array(tex(a, "ao", r))
    lum = (d[..., :3] @ np.array([0.2126, 0.7152, 0.0722], dtype=np.float32)).ravel()
    ranks = np.empty(lum.size, dtype=np.float32)
    ranks[np.argsort(lum, kind="stable")] = np.linspace(0.0, 1.0, lum.size, dtype=np.float32)
    t = ranks.reshape(h, w)[..., None]
    dark = np.array(hex_srgb("#5E8E80"), dtype=np.float32)
    mid = np.array(hex_srgb("#86B8A8"), dtype=np.float32)
    light = np.array(hex_srgb("#AAD2C4"), dtype=np.float32)
    col = np.where(t < 0.5, dark + (mid - dark) * (t * 2.0), mid + (light - mid) * ((t - 0.5) * 2.0))
    rng = np.random.default_rng(7)
    noise = rng.normal(0.0, 1.0, w).astype(np.float32)
    k = np.ones(31, dtype=np.float32) / 31.0
    noise = np.convolve(np.concatenate([noise[-15:], noise, noise[:15]]), k, mode="valid")[:w]
    noise /= max(float(np.abs(noise).max()), 1e-4)
    col *= (1.0 + 0.07 * noise)[None, :, None]
    col *= 0.55 + 0.45 * ao[..., :1]
    save_array(col, os.path.join(TEXTURE_DIR, "derived_copper_patina_diff_4k.jpg"))
    save_array(col.reshape(h // 2, 2, w // 2, 2, 3).mean(axis=(1, 3)),
               os.path.join(TEXTURE_DIR, "derived_copper_patina_diff_2k.jpg"))
    rr, _, _ = image_array(tex(a, "rough", r))
    rv = rr[..., 0]
    rv = np.clip(0.55 + (rv - float(rv.mean())) * 0.8, 0.3, 0.9)
    rv = rv.reshape(h // 2, 2, w // 2, 2).mean(axis=(1, 3))
    save_array(np.repeat(rv[..., None], 3, axis=2), os.path.join(TEXTURE_DIR, "derived_copper_patina_rough_2k.jpg"))
    # Lawn: tone the brown leaf litter of leafy_grass toward a healthy, muted green.
    a, r = PH["grass"]
    d, w, h = image_array(tex(a, "diff", r))
    rgb = d[..., :3].copy()
    lum = rgb @ np.array([0.2126, 0.7152, 0.0722], dtype=np.float32)
    brown = np.clip((rgb[..., 0] - rgb[..., 1]) * 6.0 + 0.3, 0.0, 1.0)[..., None]
    green = np.stack([lum * 0.80, lum * 1.12, lum * 0.55], axis=-1)
    rgb = rgb * (1.0 - 0.75 * brown) + green * (0.75 * brown)
    target = np.array(hex_srgb("#5C7040"), dtype=np.float32)
    rgb = rgb * (target / np.maximum(rgb.reshape(-1, 3).mean(axis=0), 1e-4))
    save_array(rgb, os.path.join(TEXTURE_DIR, "derived_lawn_diff_2k.jpg"))
    make_taegukgi(os.path.join(TEXTURE_DIR, "derived_flag_taegukgi.png"))
    # woodland floor: the forest-ground scan toned darker and browner (reads as shaded leaf litter)
    a, r = PH["woodland"]
    d, w, h = image_array(tex(a, "diff", r))
    rgb = d[..., :3] * np.array([0.52, 0.5, 0.42], dtype=np.float32)
    save_array(rgb, os.path.join(TEXTURE_DIR, "derived_woodland_diff_1k.jpg"))
    # 1k normal maps for the tiled ground materials (size budget; they repeat every few metres)
    # 2K normal maps for the facade granite and the dome (file-size budget)
    for key in ("facade", "copper"):
        a, r = PH[key]
        n, w, h = image_array(tex(a, "nor_gl", r))
        v = n[..., :3].reshape(h // 2, 2, w // 2, 2, 3).mean(axis=(1, 3)) * 2.0 - 1.0
        v /= np.maximum(np.linalg.norm(v, axis=-1, keepdims=True), 1e-4)
        save_array(v * 0.5 + 0.5, os.path.join(TEXTURE_DIR, "derived_%s_nor_gl_2k.jpg" % a))
    for key in ("concrete", "grass", "mulch", "ashlar"):
        a, r = PH[key]
        n, w, h = image_array(tex(a, "nor_gl", r))
        v = n[..., :3].reshape(h // 2, 2, w // 2, 2, 3).mean(axis=(1, 3)) * 2.0 - 1.0
        v /= np.maximum(np.linalg.norm(v, axis=-1, keepdims=True), 1e-4)
        save_array(v * 0.5 + 0.5, os.path.join(TEXTURE_DIR, "derived_%s_nor_gl_1k.jpg" % a))


def make_taegukgi(path, H=1366):
    """Korean national flag drawn from the official construction rules:
    3:2 field, taegeuk diameter = H/2 on the diagonal from upper-left to lower-right,
    red above / blue below with an S-curve of two circles of diameter D/2,
    trigrams (geon upper-left, gam upper-right, ri lower-left, gon lower-right)
    of length D/2, bar width D/12, gaps D/24, D/4 away from the circle."""
    import numpy as np
    W = int(round(H * 1.5))
    ss = 3
    ys, xs = np.mgrid[0:H * ss, 0:W * ss].astype(np.float32)
    u = (xs + 0.5) / ss
    v = H - (ys + 0.5) / ss          # v up
    cu, cv = W / 2.0, H / 2.0
    D = H / 2.0
    R = D / 2.0
    dvec = np.array([3.0, -2.0]) / math.sqrt(13.0)     # upper-left -> lower-right
    nvec = np.array([2.0, 3.0]) / math.sqrt(13.0)      # toward upper-right
    evec = np.array([3.0, 2.0]) / math.sqrt(13.0)      # lower-left -> upper-right
    px, py = u - cu, v - cv
    along = px * dvec[0] + py * dvec[1]
    perp = px * nvec[0] + py * nvec[1]
    inside = px * px + py * py <= R * R
    dl = (along + R / 2) ** 2 + perp ** 2
    dr = (along - R / 2) ** 2 + perp ** 2
    red = inside & (((along < 0) & ((perp > 0) | (dl < (R / 2) ** 2))) |
                    ((along >= 0) & (perp > 0) & (dr >= (R / 2) ** 2)))
    blue = inside & ~red
    black = np.zeros_like(inside)
    bw, gap, blen = D / 12.0, D / 24.0, D / 2.0
    centre_dist = D / 2.0 + D / 4.0 + (3 * bw + 2 * gap) / 2.0

    def trigram(axis, sign, pattern):
        # pattern: three bars from the inside out, True = solid, False = broken
        cx, cy = axis * centre_dist * sign
        a_ = (px - cx) * axis[0] + (py - cy) * axis[1]           # along the diagonal
        b_ = -(px - cx) * axis[1] + (py - cy) * axis[0]          # across it
        m = np.zeros_like(inside)
        for i, solid in enumerate(pattern):
            off = (i - 1) * (bw + gap) * sign
            bar = (np.abs(a_ - off) <= bw / 2) & (np.abs(b_) <= blen / 2)
            if not solid:
                bar &= np.abs(b_) >= gap / 2
            m |= bar
        return m

    black |= trigram(-dvec, 1.0, (True, True, True))      # geon, upper-left
    black |= trigram(dvec, 1.0, (False, False, False))    # gon, lower-right
    black |= trigram(evec, 1.0, (False, True, False))     # gam, upper-right
    black |= trigram(-evec, 1.0, (True, False, True))     # ri, lower-left
    img = np.ones((H * ss, W * ss, 3), dtype=np.float32)
    img[red] = hex_srgb("#CD2E3A")
    img[blue] = hex_srgb("#0047A0")
    img[black] = (0.0, 0.0, 0.0)
    img = img.reshape(H, ss, W, ss, 3).mean(axis=(1, 3))
    img = img[::-1]                                       # Blender pixel rows start at the bottom
    save_array(img, path, fmt="PNG")


# ---------------------------------------------------------------------------
# Materials
# ---------------------------------------------------------------------------
def new_material(name):
    m = bpy.data.materials.get(name)
    if m is not None and m.users == 0:
        bpy.data.materials.remove(m)
    m = tag(bpy.data.materials.new(name))
    m.use_backface_culling = True
    return m


def bsdf_of(m):
    return next(n for n in m.node_tree.nodes if n.type == "BSDF_PRINCIPLED")


def pbr_material(name, diff, rough, nor, ao=None, metallic=0.0, normal_strength=1.0,
                 vertex_colour=False, double_sided=False, rough_scale=None):
    m = new_material(name)
    nt = m.node_tree
    b = bsdf_of(m)
    td = nt.nodes.new("ShaderNodeTexImage")
    td.image = load_image(diff, False)
    td.location = (-900, 300)
    base_out = sock(td, "Color", True)
    if vertex_colour:
        ca = nt.nodes.new("ShaderNodeVertexColor")
        ca.layer_name = "Col"
        mix = nt.nodes.new("ShaderNodeMix")
        mix.data_type = "RGBA"
        mix.blend_type = "MULTIPLY"
        sock(mix, "Factor_Float").default_value = 1.0
        nt.links.new(base_out, sock(mix, "A_Color"))
        nt.links.new(sock(ca, "Color", True), sock(mix, "B_Color"))
        base_out = sock(mix, "Result_Color", True)
    nt.links.new(base_out, sock(b, "Base Color"))
    tr = nt.nodes.new("ShaderNodeTexImage")
    tr.image = load_image(rough, True)
    tr.location = (-900, 0)
    nt.links.new(sock(tr, "Color", True), sock(b, "Roughness"))
    tn = nt.nodes.new("ShaderNodeTexImage")
    tn.image = load_image(nor, True)
    tn.location = (-900, -300)
    nm = nt.nodes.new("ShaderNodeNormalMap")
    sock(nm, "Strength").default_value = normal_strength
    nt.links.new(sock(tn, "Color", True), sock(nm, "Color"))
    nt.links.new(sock(nm, "Normal", True), sock(b, "Normal"))
    sock(b, "Metallic").default_value = metallic
    if ao:
        set_occlusion(m, load_image(ao, True), uv_map=None)
    m.use_backface_culling = not double_sided
    return m


def gltf_output_group():
    g = bpy.data.node_groups.get("glTF Material Output")
    if g is None:
        # the glTF add-on's own settings group (the importer expects all of its sockets)
        try:
            from io_scene_gltf2.blender.com.material_helpers import create_settings_group
            g = tag(create_settings_group("glTF Material Output"))
        except Exception:
            g = tag(bpy.data.node_groups.new("glTF Material Output", "ShaderNodeTree"))
            g.interface.new_socket("Occlusion", in_out="INPUT", socket_type="NodeSocketFloat")
            g.interface.new_socket("Thickness", in_out="INPUT", socket_type="NodeSocketFloat")
    return g


def set_occlusion(m, img, uv_map=None):
    nt = m.node_tree
    for n in list(nt.nodes):
        if n.get("na_ao"):
            nt.nodes.remove(n)
    grp = nt.nodes.new("ShaderNodeGroup")
    grp.node_tree = gltf_output_group()
    grp["na_ao"] = 1
    grp.location = (300, -400)
    ti = nt.nodes.new("ShaderNodeTexImage")
    ti.image = img
    ti["na_ao"] = 1
    ti.location = (-300, -600)
    if uv_map:
        uvn = nt.nodes.new("ShaderNodeUVMap")
        uvn.uv_map = uv_map
        uvn["na_ao"] = 1
        uvn.location = (-500, -600)
        nt.links.new(sock(uvn, "UV", True), sock(ti, "Vector"))
    nt.links.new(sock(ti, "Color", True), grp.inputs["Occlusion"])
    return ti


def flat_material(name, hex_color, roughness=0.8, metallic=0.0, emission=None, double_sided=False):
    m = new_material(name)
    b = bsdf_of(m)
    rgb = hex_linear(hex_color)
    sock(b, "Base Color").default_value = (rgb[0], rgb[1], rgb[2], 1.0)
    sock(b, "Roughness").default_value = roughness
    sock(b, "Metallic").default_value = metallic
    if emission:
        e = hex_linear(emission[0])
        sock(b, "Emission Color").default_value = (e[0], e[1], e[2], 1.0)
        sock(b, "Emission Strength").default_value = emission[1]
    m.diffuse_color = (rgb[0], rgb[1], rgb[2], 1.0)
    m.use_backface_culling = not double_sided
    return m


def texture_material(name, img_path, roughness=0.6, double_sided=True):
    m = new_material(name)
    nt = m.node_tree
    b = bsdf_of(m)
    t = nt.nodes.new("ShaderNodeTexImage")
    t.image = load_image(img_path, False)
    nt.links.new(sock(t, "Color", True), sock(b, "Base Color"))
    sock(b, "Roughness").default_value = roughness
    m.use_backface_culling = not double_sided
    return m


def build_materials():
    MATS.clear()
    T = TEXTURE_DIR
    a, r = PH["facade"]
    fac = (os.path.join(T, "derived_granite_facade_diff_4k.jpg"), os.path.join(T, "derived_granite_facade_rough_2k.jpg"),
           os.path.join(T, "derived_%s_nor_gl_2k.jpg" % a))
    MATS["Granite_Facade"] = pbr_material("Granite_Facade", *fac)
    # the central axis is paved in the facade granite (large light slabs); same images, so no
    # extra texture weight; per-field tone variation comes from vertex colours
    MATS["Paving_Axis"] = pbr_material("Paving_Axis", *fac, normal_strength=1.3, vertex_colour=True)
    a, r = PH["podium"]
    pod = (os.path.join(T, "derived_granite_podium_diff_2k.jpg"), tex(a, "rough", r), tex(a, "nor_gl", r))
    MATS["Granite_Podium"] = pbr_material("Granite_Podium", *pod)
    MATS["Stone_Dressed"] = pbr_material("Stone_Dressed", *pod)          # fountain, plinths (not AO-baked)
    MATS["Paving_Granite"] = pbr_material("Paving_Granite", os.path.join(T, "derived_granite_paving_diff_2k.jpg"),
                                          pod[1], pod[2], normal_strength=1.3, vertex_colour=True)
    dark = (os.path.join(T, "derived_granite_dark_diff_2k.jpg"), pod[1], pod[2])
    MATS["Kerb_Granite"] = pbr_material("Kerb_Granite", *dark, normal_strength=1.2)
    MATS["Paving_Band"] = pbr_material("Paving_Band", *dark, normal_strength=1.2)
    a, r = PH["ashlar"]
    MATS["Granite_Ashlar"] = pbr_material("Granite_Ashlar", os.path.join(T, "derived_granite_ashlar_diff_2k.jpg"),
                                          tex(a, "rough", r), os.path.join(T, "derived_%s_nor_gl_1k.jpg" % a))
    a, r = PH["copper"]
    MATS["Copper_Patina"] = pbr_material("Copper_Patina", os.path.join(T, "derived_copper_patina_diff_2k.jpg"),
                                         os.path.join(T, "derived_copper_patina_rough_2k.jpg"),
                                         os.path.join(T, "derived_%s_nor_gl_2k.jpg" % a),
                                         metallic=0.15, normal_strength=1.4)
    for key, pk in (("Paving_Concrete", "concrete"), ("Bed_Mulch", "mulch")):
        a, r = PH[pk]
        MATS[key] = pbr_material(key, tex(a, "diff", r), tex(a, "rough", r),
                                 os.path.join(T, "derived_%s_nor_gl_1k.jpg" % a), ao=tex(a, "ao", r))
    a, r = PH["gravel"]
    MATS["Gravel_Court"] = pbr_material("Gravel_Court", tex(a, "diff", r), tex(a, "rough", r), tex(a, "nor_gl", r),
                                        ao=tex(a, "ao", r), normal_strength=1.2)
    a, r = PH["ashlar"]
    MATS["Wall_Ashlar"] = pbr_material("Wall_Ashlar", os.path.join(T, "derived_granite_ashlar_diff_2k.jpg"),
                                       tex(a, "rough", r), os.path.join(T, "derived_%s_nor_gl_1k.jpg" % a))
    MATS["Pool_Lining"] = pbr_material("Pool_Lining", *dark)
    MATS["Hedge_Core"] = flat_material("Hedge_Core", "#18200F", 0.95, 0.0)
    MATS["Cast_Iron"] = flat_material("Cast_Iron", "#2B2A28", 0.55, 0.85)
    a, r = PH["woodland"]
    MATS["Bed_Woodland"] = pbr_material("Bed_Woodland", os.path.join(T, "derived_woodland_diff_1k.jpg"), tex(a, "rough", r),
                                        tex(a, "nor_gl", r),
                                        ao=tex(a, "ao", r))
    a, r = PH["grass"]
    MATS["Lawn_Grass"] = pbr_material("Lawn_Grass", os.path.join(T, "derived_lawn_diff_2k.jpg"), tex(a, "rough", r),
                                      os.path.join(T, "derived_%s_nor_gl_1k.jpg" % a), ao=tex(a, "ao", r),
                                      vertex_colour=True)
    MATS["Glass_Dark"] = flat_material("Glass_Dark", "#6A7F92", 0.03, 0.45)
    MATS["Metal_WindowFrame"] = flat_material("Metal_WindowFrame", "#B9BDC0", 0.35, 0.7)
    MATS["Metal_DoorFrame"] = flat_material("Metal_DoorFrame", "#3A3632", 0.4, 0.8)
    MATS["Interior_Floor"] = flat_material("Interior_Floor", "#2E2A26", 0.45)
    MATS["Interior_Wall"] = flat_material("Interior_Wall", "#202328", 0.85)
    MATS["Interior_Ceiling"] = flat_material("Interior_Ceiling", "#3A3937", 0.9)
    MATS["Bronze_Lattice"] = flat_material("Bronze_Lattice", "#B48F5A", 0.5, 0.3)
    MATS["Water"] = flat_material("Water", "#1A3335", 0.03, 0.0)
    MATS["Steel_Flagpole"] = flat_material("Steel_Flagpole", "#C9CCCF", 0.25, 1.0)
    MATS["Steel_Brushed"] = flat_material("Steel_Brushed", "#B4B8BB", 0.32, 1.0)      # slot drains, handrails
    MATS["Drain_Slot"] = flat_material("Drain_Slot", "#151515", 0.9, 0.0)
    MATS["Gold_Finial"] = flat_material("Gold_Finial", "#C9A245", 0.3, 1.0)
    MATS["Bronze_Nozzle"] = flat_material("Bronze_Nozzle", "#6E5B3C", 0.35, 0.85)
    MATS["Flag_Taegukgi"] = texture_material("Flag_Taegukgi", os.path.join(T, "derived_flag_taegukgi.png"), 0.75)
    MATS["Flag_Assembly"] = flat_material("Flag_Assembly", "#1D4E9E", 0.75, 0.0, double_sided=True)


# ---------------------------------------------------------------------------
# Mesh builder
# ---------------------------------------------------------------------------
class MB:
    """bmesh-based builder. Faces get world-scale planar UVs at finish() unless a
    helper already wrote custom UVs (flagged in the 'uvdone' face layer)."""

    def __init__(self, name):
        self.name = name
        self.bm = bmesh.new()
        self.uvl = self.bm.loops.layers.uv.new("UVMap")
        self.done = self.bm.faces.layers.int.new("uvdone")
        self.mats = []

    def mi(self, key):
        mat = MATS[key]
        if mat not in self.mats:
            self.mats.append(mat)
        return self.mats.index(mat)

    def face(self, pts, key, want=None, verts=None):
        vs = verts if verts is not None else [self.bm.verts.new(p) for p in pts]
        f = self.bm.faces.new(vs)
        f.material_index = self.mi(key)
        if want is not None:
            f.normal_update()
            if f.normal.dot(Vector(want)) < 0:
                f.normal_flip()
        return f

    def hexa(self, P, key, skip=(), bevel=0.0):
        """Six-sided solid from 8 corners P[i][j][k] (i,j,k in 0/1), faces oriented outward.
        skip: subset of 'i0','i1','j0','j1','k0','k1'. Optional chamfer on solid edges."""
        V = [[[self.bm.verts.new(P[i][j][k]) for k in (0, 1)] for j in (0, 1)] for i in (0, 1)]
        centre = sum((Vector(P[i][j][k]) for i in (0, 1) for j in (0, 1) for k in (0, 1)), Vector()) / 8.0
        quads = {
            "i0": (V[0][0][0], V[0][1][0], V[0][1][1], V[0][0][1]),
            "i1": (V[1][0][0], V[1][0][1], V[1][1][1], V[1][1][0]),
            "j0": (V[0][0][0], V[0][0][1], V[1][0][1], V[1][0][0]),
            "j1": (V[0][1][0], V[1][1][0], V[1][1][1], V[0][1][1]),
            "k0": (V[0][0][0], V[1][0][0], V[1][1][0], V[0][1][0]),
            "k1": (V[0][0][1], V[0][1][1], V[1][1][1], V[1][0][1]),
        }
        faces = []
        mat = self.mi(key)
        for kname, q in quads.items():
            if kname in skip:
                continue
            f = self.bm.faces.new(q)
            f.material_index = mat
            f.normal_update()
            if f.normal.dot(f.calc_center_median() - centre) < 0:
                f.normal_flip()
            faces.append(f)
        for row in V:
            for col in row:
                for v in col:
                    if not v.link_faces:
                        self.bm.verts.remove(v)
        if bevel > 0 and faces:
            edges = {e for f in faces for e in f.edges if len(e.link_faces) == 2}
            if edges:
                bmesh.ops.bevel(self.bm, geom=list(edges), offset=bevel, offset_type="OFFSET",
                                segments=1, profile=0.5, affect="EDGES", clamp_overlap=True)
        return faces

    def box(self, key, x0, x1, y0, y1, z0, z1, skip=(), bevel=0.0):
        sm = {"-x": "i0", "+x": "i1", "-y": "j0", "+y": "j1", "-z": "k0", "+z": "k1"}
        P = [[[(x, y, z) for z in (z0, z1)] for y in (y0, y1)] for x in (x0, x1)]
        self.hexa(P, key, skip=tuple(sm.get(s, s) for s in skip), bevel=bevel)
        return (min(x0, x1), max(x0, x1), min(y0, y1), max(y0, y1), min(z0, z1), max(z0, z1))

    def fbox(self, F, key, u0, u1, v0, v1, d0, d1, skip=(), bevel=0.0):
        """Box in a facade frame F=(origin, U, V, N): point = o + U*u + V*v - N*d."""
        o, U, Vv, N = F
        P = [[[tuple(o + U * u + Vv * v - N * d) for d in (d0, d1)] for v in (v0, v1)] for u in (u0, u1)]
        return self.hexa(P, key, skip=skip, bevel=bevel)

    def loft(self, rings, segments, keys, phase=0.0, uv=None, closed_seg=True):
        """Surface through rings (cx, cy, z, rx, ry); rx == 0 means an apex point.
        Order rings bottom/outside -> top so normals face outward.
        uv: None (planar later), ("cyl", tile, wrap_int) or ("gore", tile, seg_per_gore)."""
        verts = []
        for (cx, cy, z, rx, ry) in rings:
            if rx < 1e-9:
                verts.append([self.bm.verts.new((cx, cy, z))])
            else:
                verts.append([self.bm.verts.new((cx + rx * math.cos(phase + 2 * math.pi * k / segments),
                                                 cy + ry * math.sin(phase + 2 * math.pi * k / segments), z))
                              for k in range(segments)])
        s = [0.0]
        for i in range(1, len(rings)):
            s.append(s[-1] + math.hypot(rings[i][3] - rings[i - 1][3], rings[i][2] - rings[i - 1][2]))
        gore_off = []
        if uv and uv[0] == "gore":
            go = random.Random(RNG_SEED + 1)
            gore_off = [(go.random(), go.random()) for _ in range(segments // uv[2] + 1)]
        faces = []
        for i in range(len(rings) - 1):
            A, B = verts[i], verts[i + 1]
            if len(A) == 1 and len(B) == 1:
                continue
            for k in range(segments):
                k2 = (k + 1) % segments
                if len(A) == 1:
                    vs, keysk = (A[0], B[k2], B[k]), ((i, k + 0.5), (i + 1, k + 1), (i + 1, k))
                elif len(B) == 1:
                    vs, keysk = (A[k], A[k2], B[0]), ((i, k), (i, k + 1), (i + 1, k + 0.5))
                else:
                    vs, keysk = (A[k], A[k2], B[k2], B[k]), ((i, k), (i, k + 1), (i + 1, k + 1), (i + 1, k))
                f = self.bm.faces.new(vs)
                f.material_index = self.mi(keys[i] if isinstance(keys, (list, tuple)) else keys)
                faces.append(f)
                if uv and uv[0] in ("cyl", "gore"):
                    f[self.done] = 1
                    tile = uv[1]
                    for loop, (ri, kk) in zip(f.loops, keysk):
                        rr = rings[ri][3]
                        chord = 2.0 * rr * math.sin(math.pi / segments)
                        ov = 0.0
                        if uv[0] == "gore":
                            g = k // uv[2]
                            kc = g * uv[2] + uv[2] / 2.0
                            u_ = (kk - kc) * chord / tile + gore_off[g][0]
                            ov = gore_off[g][1]
                        elif uv[2] and rr > 0:
                            u_ = kk * max(1, round(segments * chord / tile)) / segments
                        else:
                            u_ = kk * chord / tile
                        loop[self.uvl].uv = (u_, s[ri] / tile + ov)
        return faces, verts

    def lathe(self, profile, segments, keys, centre=(0.0, 0.0), phase=0.0, uv=None):
        return self.loft([(centre[0], centre[1], z, r, r) for (r, z) in profile], segments, keys, phase, uv)

    def sphere(self, c, r, key, segs=16, rings=10, sz=1.0, sx=1.0, sy=1.0):
        prof = []
        for j in range(rings + 1):
            th = math.pi * j / rings
            rr = 0.0 if j in (0, rings) else math.sin(th)
            prof.append((c[0], c[1], c[2] - sz * r * math.cos(th), rr * r * sx, rr * r * sy))
        return self.loft(prof, segs, key)[0]

    def ring_loft(self, rings, key, closed=True):
        """rings: list of lists of 3D points (same count, CCW seen from +Z), bottom->top."""
        vr = [[self.bm.verts.new(p) for p in ring] for ring in rings]
        faces = []
        n = len(rings[0])
        for i in range(len(vr) - 1):
            for k in range(n if closed else n - 1):
                k2 = (k + 1) % n
                f = self.bm.faces.new((vr[i][k], vr[i][k2], vr[i + 1][k2], vr[i + 1][k]))
                f.material_index = self.mi(key)
                faces.append(f)
        return faces, vr

    def finish(self, coll, smooth_angle=None, name=None):
        bm = self.bm
        for f in bm.faces:
            if f[self.done]:
                continue
            f.normal_update()
            n = f.normal
            tile = TILE.get(self.mats[f.material_index].name if f.material_index < len(self.mats) else "", 4.0)
            if abs(n.z) >= 0.7:
                for lp in f.loops:
                    co = lp.vert.co
                    lp[self.uvl].uv = (co.x / tile, (co.y if n.z >= 0 else -co.y) / tile)
            else:
                t = Vector((-n.y, n.x, 0.0))
                if t.length < 1e-6:
                    t = Vector((1.0, 0.0, 0.0))
                t.normalize()
                for lp in f.loops:
                    co = lp.vert.co
                    lp[self.uvl].uv = (co.dot(t) / tile, co.z / tile)
        if smooth_angle is not None:
            apply_smooth(bm, smooth_angle)
        bm.normal_update()
        nm = name or self.name
        me = tag(bpy.data.meshes.new(nm))
        bm.to_mesh(me)
        bm.free()
        for m in self.mats:
            me.materials.append(m)
        if "uvdone" in me.attributes:
            me.attributes.remove(me.attributes["uvdone"])
        me.validate(clean_customdata=False)
        ob = bpy.data.objects.new(nm, me)
        coll.objects.link(ob)
        if ob.name != nm:
            log("WARNING: name collision", ob.name, nm)
        return ob


def apply_smooth(bm, angle_deg):
    thr = math.radians(angle_deg)
    for f in bm.faces:
        f.smooth = True
    for e in bm.edges:
        lf = e.link_faces
        if len(lf) != 2:
            continue
        if lf[0].material_index != lf[1].material_index:
            e.smooth = False
            continue
        try:
            e.smooth = e.calc_face_angle() <= thr
        except ValueError:
            e.smooth = True


# ---------------------------------------------------------------------------
# Building
# ---------------------------------------------------------------------------
def col_centres():
    xs = [-COL_LINE_X + i * (2 * COL_LINE_X / 7) for i in range(8)]
    ys = [-COL_LINE_Y + i * (2 * COL_LINE_Y / 5) for i in range(1, 5)]
    return ([(x, -COL_LINE_Y) for x in xs] + [(COL_LINE_X, y) for y in ys]
            + [(x, COL_LINE_Y) for x in reversed(xs)] + [(-COL_LINE_X, y) for y in reversed(ys)])


def octagon(cx, cy, half, ch, z):
    a, b = half, half - ch
    pts = [(a, -b), (a, b), (b, a), (-b, a), (-a, b), (-a, -b), (-b, -a), (b, -a)]
    return [(cx + x, cy + y, z) for (x, y) in pts]


def build_columns(coll):
    """Regular octagonal columns (as on the reference photos) with a moulded octagonal base on a
    square plinth, a straight shaft, an astragal, a flared capital and a square abacus."""
    mb = MB("Columns_Granite")
    K = "Granite_Facade"
    h = COL_FLAT / 2.0
    for i, (cx, cy) in enumerate(col_centres()):
        mb.box(K, cx - h - 0.55, cx + h + 0.55, cy - h - 0.55, cy + h + 0.55, POD_TOP + 0.02, POD_TOP + 0.5,
               skip=("-z",), bevel=0.03)
        z0 = POD_TOP + 0.5
        prof = [(z0, h + 0.38), (z0 + 0.16, h + 0.38), (z0 + 0.2, h + 0.33), (z0 + 0.3, h + 0.22), (z0 + 0.36, h + 0.22),
                (z0 + 0.4, h + 0.15), (z0 + 0.52, h + 0.06), (z0 + 0.6, h),
                (COL_TOP - 1.55, h), (COL_TOP - 1.5, h + 0.1), (COL_TOP - 1.36, h + 0.1),
                (COL_TOP - 1.3, h + 0.02), (COL_TOP - 1.1, h + 0.04), (COL_TOP - 0.62, h + 0.42),
                (COL_TOP - 0.62, h + 0.5)]
        rings = [octagon(cx, cy, hh, 0.586 * hh, z) for (z, hh) in prof]
        faces, vr = mb.ring_loft(rings, K)
        f = mb.bm.faces.new(vr[-1])
        f.material_index = mb.mi(K)
        f.normal_update()
        if f.normal.z < 0:
            f.normal_flip()
        mb.box(K, cx - h - 0.68, cx + h + 0.68, cy - h - 0.68, cy + h + 0.68, COL_TOP - 0.62, COL_TOP,
               skip=("+z",), bevel=0.035)
        CIRCLES.append(("column-%02d" % (i + 1), cx, cy, round(h + 0.6, 2)))
    return mb.finish(coll, smooth_angle=20.0)


def facade_frame(side):
    """(origin, U, V, N, width) for the four body walls; origin at bottom-left seen from outside."""
    e = 0.05
    if side == "front":
        return (Vector((-BODY_HX + e, -BODY_HY, POD_TOP)), Vector((1, 0, 0)), Vector((0, 0, 1)), Vector((0, -1, 0)), 2 * (BODY_HX - e))
    if side == "back":
        return (Vector((BODY_HX - e, BODY_HY, POD_TOP)), Vector((-1, 0, 0)), Vector((0, 0, 1)), Vector((0, 1, 0)), 2 * (BODY_HX - e))
    if side == "right":
        return (Vector((BODY_HX, -BODY_HY + e, POD_TOP)), Vector((0, 1, 0)), Vector((0, 0, 1)), Vector((1, 0, 0)), 2 * (BODY_HY - e))
    return (Vector((-BODY_HX, BODY_HY - e, POD_TOP)), Vector((0, -1, 0)), Vector((0, 0, 1)), Vector((-1, 0, 0)), 2 * (BODY_HY - e))


def floor_levels():
    lv = [0.0, GROUND_FLOOR_H]
    for k in range(1, N_UPPER):
        lv.append(GROUND_FLOOR_H + k * FLOOR_H)
    return lv                       # relative to the podium top


def build_body(coll):
    """Punched-window facades with recessed, framed windows, central bronze lattice
    bays above glazed entrances on all four sides, plinth course and corner chamfers."""
    wall = MB("Body_Granite")
    glass = MB("Glass")
    frames = MB("Window_Frames")
    lattice = MB("Lattice_Bronze")
    H = COL_TOP - POD_TOP
    levels = floor_levels()
    ch = 0.03
    for side in ("front", "back", "right", "left"):
        o, U, Vv, N, W = facade_frame(side)
        F = (o, U, Vv, N)
        mid = W / 2.0
        half_c = LATTICE_HALF
        openings = []
        # central entrance and lattice bay
        ent = (mid - half_c, mid + half_c, 0.0, 5.0)
        lat = (mid - half_c, mid + half_c, GROUND_FLOOR_H + 0.3, H - 1.1)
        openings.append((ent[0] - ch, ent[1] + ch, 0.0, ent[3] + ch))
        openings.append((lat[0] - ch, lat[1] + ch, lat[2] - ch, lat[3] + ch))
        wins = []
        n_side = int((mid - WIN_W) // WIN_PITCH) + 1
        for k in range(n_side):
            off = WIN_PITCH / 2 + k * WIN_PITCH
            for uc in (mid - off, mid + off):
                if abs(uc - mid) - WIN_W / 2 < half_c + 0.5 or uc - WIN_W / 2 < 0.7 or uc + WIN_W / 2 > W - 0.7:
                    continue
                for li, lvl in enumerate(levels):
                    if li == 0:
                        v0, v1 = 1.3, 4.9
                    else:
                        v0, v1 = lvl + 1.0, lvl + 3.6
                    wins.append((uc - WIN_W / 2, uc + WIN_W / 2, v0, v1))
                    openings.append((uc - WIN_W / 2 - ch, uc + WIN_W / 2 + ch, v0 - ch, v1 + ch))
        facade_wall(wall, F, W, H, openings)
        for (u0, u1, v0, v1) in wins:
            window(wall, glass, frames, F, u0, u1, v0, v1)
        lattice_bay(wall, glass, lattice, F, *lat)
        entrance_bay(wall, glass, frames, F, *ent)
        # plinth course (granite base band), split at the entrance
        for (a, b) in ((0.0, ent[0] - 0.02), (ent[1] + 0.02, W)):
            wall.fbox(F, "Granite_Facade", a, b, 0.0, 0.6, -0.06, 0.05, skip=("k1", "j0"), bevel=0.02)
    # corner chamfers
    e = 0.05
    for sx in (-1, 1):
        for sy in (-1, 1):
            p0 = (sx * (BODY_HX - e), sy * BODY_HY)
            p1 = (sx * BODY_HX, sy * (BODY_HY - e))
            wall.face([(p0[0], p0[1], POD_TOP), (p1[0], p1[1], POD_TOP), (p1[0], p1[1], COL_TOP), (p0[0], p0[1], COL_TOP)],
                      "Granite_Facade", want=(sx, sy, 0))
    objs = [wall.finish(coll), glass.finish(coll), frames.finish(coll), lattice.finish(coll)]
    BOUNDS["main-body"] = (-BODY_HX - 0.06, BODY_HX + 0.06, -BODY_HY - 0.06, BODY_HY + 0.06, POD_TOP, COL_TOP)
    return objs


def facade_wall(mb, F, W, H, openings):
    o, U, Vv, N = F
    us = sorted(set([0.0, W] + [x for op in openings for x in (op[0], op[1])]))
    vs = sorted(set([0.0, H] + [x for op in openings for x in (op[2], op[3])]))
    cache = {}

    def vert(i, j):
        key = (i, j)
        if key not in cache:
            cache[key] = mb.bm.verts.new(o + U * us[i] + Vv * vs[j])
        return cache[key]

    # bucket openings by column for a fast inside test
    for i in range(len(us) - 1):
        cu = (us[i] + us[i + 1]) / 2
        col_ops = [op for op in openings if op[0] < cu < op[1]]
        for j in range(len(vs) - 1):
            cv = (vs[j] + vs[j + 1]) / 2
            if any(op[2] < cv < op[3] for op in col_ops):
                continue
            mb.face(None, "Granite_Facade", want=N, verts=[vert(i, j), vert(i + 1, j), vert(i + 1, j + 1), vert(i, j + 1)])


def fp(F, u, v, d):
    o, U, Vv, N = F
    return tuple(o + U * u + Vv * v - N * d)


def tube(mb, F, rect, d0, d1, key, rect1=None, skip_edges=()):
    """Inward-facing reveal faces connecting rect at depth d0 to rect1 (default rect) at d1.
    Edge order: 0 bottom, 1 right, 2 top, 3 left."""
    o, U, Vv, N = F
    r1 = rect1 or rect
    A = [fp(F, rect[0], rect[2], d0), fp(F, rect[1], rect[2], d0), fp(F, rect[1], rect[3], d0), fp(F, rect[0], rect[3], d0)]
    B = [fp(F, r1[0], r1[2], d1), fp(F, r1[1], r1[2], d1), fp(F, r1[1], r1[3], d1), fp(F, r1[0], r1[3], d1)]
    cu = (rect[0] + rect[1]) / 2
    cv = (rect[2] + rect[3]) / 2
    centre = Vector(fp(F, cu, cv, (d0 + d1) / 2))
    for k in range(4):
        if k in skip_edges:
            continue
        k2 = (k + 1) % 4
        f = mb.face([A[k], A[k2], B[k2], B[k]], key)
        f.normal_update()
        if f.normal.dot(centre - f.calc_center_median()) < 0:
            f.normal_flip()


def window(wall, glass, frames, F, u0, u1, v0, v1, depth=0.48, ch=0.03):
    o, U, Vv, N = F
    tube(wall, F, (u0 - ch, u1 + ch, v0 - ch, v1 + ch), 0.0, ch, "Granite_Facade", rect1=(u0, u1, v0, v1))
    tube(wall, F, (u0, u1, v0, v1), ch, depth, "Granite_Facade")
    glass.face([fp(F, u0, v0, depth - 0.05), fp(F, u1, v0, depth - 0.05), fp(F, u1, v1, depth - 0.05), fp(F, u0, v1, depth - 0.05)],
               "Glass_Dark", want=N)
    fw, d0, d1 = 0.09, depth - 0.14, depth - 0.02
    K = "Metal_WindowFrame"
    sk = ("k1",)
    frames.fbox(F, K, u0, u0 + fw, v0, v1, d0, d1, skip=sk)
    frames.fbox(F, K, u1 - fw, u1, v0, v1, d0, d1, skip=sk)
    frames.fbox(F, K, u0 + fw, u1 - fw, v0, v0 + fw, d0, d1, skip=sk)
    frames.fbox(F, K, u0 + fw, u1 - fw, v1 - fw, v1, d0, d1, skip=sk)
    uc = (u0 + u1) / 2
    vt = v0 + (v1 - v0) * 0.74
    frames.fbox(F, K, uc - 0.025, uc + 0.025, v0 + fw, vt - 0.025, d0 + 0.01, d1, skip=sk)
    frames.fbox(F, K, u0 + fw, u1 - fw, vt - 0.025, vt + 0.025, d0 + 0.01, d1, skip=sk)
    # inner sub-frame step (a thin shadow line inside the frame)
    frames.fbox(F, K, u0 + fw, u0 + fw + 0.025, v0 + fw, v1 - fw, d0 + 0.04, d1, skip=sk)
    frames.fbox(F, K, u1 - fw - 0.025, u1 - fw, v0 + fw, v1 - fw, d0 + 0.04, d1, skip=sk)
    # stone sill and head mould, proud of the wall
    wall.fbox(F, "Granite_Facade", u0 - 0.1, u1 + 0.1, v0 - 0.1, v0 + 0.015, -0.07, depth - 0.15,
              skip=("k1",), bevel=0.012)
    wall.fbox(F, "Granite_Facade", u0 - 0.12, u1 + 0.12, v1 + ch, v1 + ch + 0.12, -0.06, 0.0, skip=("k1",))


def lattice_bay(wall, glass, lat, F, u0, u1, v0, v1, depth=1.1, ch=0.04):
    tube(wall, F, (u0 - ch, u1 + ch, v0 - ch, v1 + ch), 0.0, ch, "Granite_Facade", rect1=(u0, u1, v0, v1))
    tube(wall, F, (u0, u1, v0, v1), ch, depth, "Granite_Facade")
    o, U, Vv, N = F
    glass.face([fp(F, u0, v0, depth - 0.02), fp(F, u1, v0, depth - 0.02), fp(F, u1, v1, depth - 0.02), fp(F, u0, v1, depth - 0.02)],
               "Glass_Dark", want=N)
    K = "Bronze_Lattice"
    W, Hh = u1 - u0, v1 - v0
    nu = max(1, round(W / 0.86))
    nv = max(1, round(Hh / 0.86))
    cw, chh = W / nu, Hh / nv
    bw, d0, d1 = 0.18, 0.3, 0.64
    for i in range(nu + 1):
        u = u0 + i * cw
        lat.fbox(F, K, max(u0, u - bw / 2), min(u1, u + bw / 2), v0, v1, d0, d1, skip=("k1",))
    for j in range(nv + 1):
        v = v0 + j * chh
        lat.fbox(F, K, u0, u1, max(v0, v - bw / 2), min(v1, v + bw / 2), d0 + 0.01, d1, skip=("k1",))
    # inner motif: a diamond frame in every cell
    for i in range(nu):
        for j in range(nv):
            cu, cv = u0 + (i + 0.5) * cw, v0 + (j + 0.5) * chh
            a_out, a_in = 0.36 * cw, 0.36 * cw - 0.09
            lat.fbox(F, K, cu - 0.09, cu + 0.09, cv - 0.09, cv + 0.09, d0 - 0.08, d1, skip=("k1",))
            outer = [(cu + a_out, cv), (cu, cv + a_out), (cu - a_out, cv), (cu, cv - a_out)]
            inner = [(cu + a_in, cv), (cu, cv + a_in), (cu - a_in, cv), (cu, cv - a_in)]
            df, db = d0 + 0.03, d1 - 0.03
            Of = [lat.bm.verts.new(fp(F, p[0], p[1], df)) for p in outer]
            If = [lat.bm.verts.new(fp(F, p[0], p[1], df)) for p in inner]
            Ob = [lat.bm.verts.new(fp(F, p[0], p[1], db)) for p in outer]
            for k in range(4):
                k2 = (k + 1) % 4
                lat.face(None, K, want=N, verts=[Of[k], Of[k2], If[k2], If[k]])
                f = lat.face(None, K, verts=[Of[k], Ob[k], Ob[k2], Of[k2]])
                f.normal_update()
                c = Vector(fp(F, cu, cv, df))
                if f.normal.dot(f.calc_center_median() - c) < 0:
                    f.normal_flip()


def entrance_bay(wall, glass, frames, F, u0, u1, v0, v1, depth=1.6, ch=0.04):
    tube(wall, F, (u0 - ch, u1 + ch, v0, v1 + ch), 0.0, ch, "Granite_Facade", rect1=(u0, u1, v0, v1), skip_edges=(0,))
    o, U, Vv, N = F
    # reveal sides and soffit only (the floor is the podium paving)
    A = [fp(F, u0, v0, ch), fp(F, u1, v0, ch), fp(F, u1, v1, ch), fp(F, u0, v1, ch)]
    B = [fp(F, u0, v0, depth), fp(F, u1, v0, depth), fp(F, u1, v1, depth), fp(F, u0, v1, depth)]
    centre = Vector(fp(F, (u0 + u1) / 2, (v0 + v1) / 2, depth / 2))
    for k in (1, 2, 3):
        k2 = (k + 1) % 4
        f = wall.face([A[k], A[k2], B[k2], B[k]], "Granite_Facade")
        f.normal_update()
        if f.normal.dot(centre - f.calc_center_median()) < 0:
            f.normal_flip()
    glass.face([fp(F, u0, v0 + 0.02, depth - 0.05), fp(F, u1, v0 + 0.02, depth - 0.05), fp(F, u1, v1, depth - 0.05),
                fp(F, u0, v1, depth - 0.05)], "Glass_Dark", want=N)
    K = "Metal_DoorFrame"
    n = 6
    w = (u1 - u0) / n
    dg = depth - 0.05                      # glass plane
    # profiled mullions: chamfered 0.16 m face, a deeper web behind; chamfered transoms
    for i in range(n + 1):
        u = u0 + i * w
        frames.fbox(F, K, max(u0, u - 0.08), min(u1, u + 0.08), v0, v1, dg - 0.16, dg + 0.02, skip=("k1",), bevel=0.012)
        frames.fbox(F, K, max(u0, u - 0.035), min(u1, u + 0.035), v0, v1, dg - 0.26, dg - 0.16, skip=("k1",), bevel=0.008)
    for vv, hh in ((v0 + 0.06, 0.06), (v0 + 3.2, 0.09), (v1 - 0.05, 0.05)):
        frames.fbox(F, K, u0, u1, vv - hh, vv + hh, dg - 0.15, dg + 0.02, skip=("k1",), bevel=0.01)
    # pairs of glazed doors in the two central bays: stiles, top rail, kick rail, pull handles
    for bi in (n // 2 - 1, n // 2):
        b0, b1 = u0 + bi * w + 0.08, u0 + (bi + 1) * w - 0.08
        mid = (b0 + b1) / 2
        dd0, dd1 = dg - 0.12, dg - 0.06
        for (l0, l1) in ((b0, mid - 0.006), (mid + 0.006, b1)):
            frames.fbox(F, K, l0, l0 + 0.09, v0 + 0.12, v0 + 3.1, dd0, dd1, bevel=0.008)
            frames.fbox(F, K, l1 - 0.09, l1, v0 + 0.12, v0 + 3.1, dd0, dd1, bevel=0.008)
            frames.fbox(F, K, l0 + 0.09, l1 - 0.09, v0 + 2.98, v0 + 3.1, dd0, dd1, bevel=0.008)
            frames.fbox(F, K, l0 + 0.09, l1 - 0.09, v0 + 0.12, v0 + 0.42, dd0, dd1, bevel=0.008)
            hu = (l1 - 0.2) if l0 < mid else (l0 + 0.2)
            frames.fbox(F, "Steel_Brushed", hu - 0.018, hu + 0.018, v0 + 0.85, v0 + 2.15, dd0 - 0.095, dd0 - 0.059,
                        bevel=0.008)
            for hv in (v0 + 0.95, v0 + 2.05):
                frames.fbox(F, "Steel_Brushed", hu - 0.011, hu + 0.011, hv - 0.011, hv + 0.011, dd0 - 0.06, dd0)
    # granite threshold and a stepped architrave round the opening
    wall.fbox(F, "Granite_Facade", u0, u1, v0, v0 + 0.025, dg - 0.4, dg + 0.04, skip=("k1",), bevel=0.008)
    for (e, pr) in ((0.42, 0.10), (0.24, 0.17)):
        wall.fbox(F, "Granite_Facade", u0 - e, u0 - ch, v0, v1 + 0.04, -pr, 0.02, skip=("k1",), bevel=0.015)
        wall.fbox(F, "Granite_Facade", u1 + ch, u1 + e, v0, v1 + 0.04, -pr, 0.02, skip=("k1",), bevel=0.015)
    # stone canopy band over the entrance
    wall.fbox(F, "Granite_Facade", u0 - 0.3, u1 + 0.3, v1 + 0.04, v1 + 0.6, -0.35, 0.05, skip=("k1",), bevel=0.02)


def rect_loft(mb, hx, hy, profile, key):
    """Sweep a (offset, z) profile around a rectangle (mitred corners); trace the profile
    from the bottom-outside upward and over the top inward for outward normals."""
    rings = []
    for (d, z) in profile:
        X, Y = hx + d, hy + d
        rings.append([(X, -Y, z), (X, Y, z), (-X, Y, z), (-X, -Y, z)])
    return mb.ring_loft(rings, key)


def build_cornice(coll):
    mb = MB("Cornice_Granite")
    K = "Granite_Facade"
    prof = [(0.0, COL_TOP), (0.0, 38.45), (-0.6, 38.45), (-0.6, 39.15), (0.08, 39.15), (0.08, 39.35), (0.16, 39.35),
            (0.16, 41.7), (0.24, 41.7), (0.24, 41.86), (0.32, 41.86), (0.32, 42.44), (0.28, 42.5), (-0.6, 42.5),
            (-0.6, ROOF_DECK)]
    rect_loft(mb, SLAB_HX, SLAB_HY, prof, K)
    # soffit ring between the slab edge and the body walls
    o_ = (SLAB_HX, SLAB_HY)
    i_ = (BODY_HX, BODY_HY)
    z = COL_TOP
    ring_o = [(o_[0], -o_[1], z), (o_[0], o_[1], z), (-o_[0], o_[1], z), (-o_[0], -o_[1], z)]
    ring_i = [(i_[0], -i_[1], z), (i_[0], i_[1], z), (-i_[0], i_[1], z), (-i_[0], -i_[1], z)]
    for k in range(4):
        k2 = (k + 1) % 4
        mb.face([ring_o[k], ring_o[k2], ring_i[k2], ring_i[k]], K, want=(0, 0, -1))
    # roof deck inside the parapet
    X, Y = SLAB_HX - 0.6, SLAB_HY - 0.6
    mb.face([(X, -Y, ROOF_DECK), (X, Y, ROOF_DECK), (-X, Y, ROOF_DECK), (-X, -Y, ROOF_DECK)], K, want=(0, 0, 1))
    # set-back attic storey carrying the drum, with a projecting top band
    A = ATTIC_HALF
    mb.box(K, -A, A, -A, A, ROOF_DECK, ATTIC_TOP - 0.45, skip=("-z", "+z"), bevel=0.03)
    mb.box(K, -A - 0.25, A + 0.25, -A - 0.25, A + 0.25, ATTIC_TOP - 0.45, ATTIC_TOP, skip=("-z",), bevel=0.03)
    mb.box(K, -A - 0.08, A + 0.08, -A - 0.08, A + 0.08, ATTIC_TOP - 1.25, ATTIC_TOP - 1.0, skip=(), bevel=0.02)
    # beams under the slab: radial beams at every column, perimeter beams on the column lines
    zb = COL_TOP - 1.0
    for (cx, cy) in col_centres():
        if abs(cy) > COL_LINE_Y - 0.1:
            s = 1 if cy > 0 else -1
            mb.box(K, cx - 0.6, cx + 0.6, *sorted((s * BODY_HY, s * (SLAB_HY - 0.12))), zb, COL_TOP, skip=("+z",), bevel=0.02)
        if abs(cx) > COL_LINE_X - 0.1:
            s = 1 if cx > 0 else -1
            mb.box(K, *sorted((s * BODY_HX, s * (SLAB_HX - 0.12))), cy - 0.6, cy + 0.6, zb, COL_TOP, skip=("+z",), bevel=0.02)
    for s in (-1, 1):
        mb.box(K, -COL_LINE_X, COL_LINE_X, s * COL_LINE_Y - 0.55, s * COL_LINE_Y + 0.55, COL_TOP - 0.8, COL_TOP,
               skip=("+z",), bevel=0.02)
        mb.box(K, s * COL_LINE_X - 0.55, s * COL_LINE_X + 0.55, -COL_LINE_Y, COL_LINE_Y, COL_TOP - 0.8, COL_TOP,
               skip=("+z",), bevel=0.02)
    # secondary ribs (coffers) between the radial beams
    xs = [-COL_LINE_X + i * (2 * COL_LINE_X / 7) for i in range(8)]
    for s in (-1, 1):
        for a, b in zip(xs[:-1], xs[1:]):
            for t in (0.25, 0.5, 0.75):
                x = a + (b - a) * t
                mb.box(K, x - 0.15, x + 0.15, *sorted((s * BODY_HY, s * (SLAB_HY - 0.3))), COL_TOP - 0.4, COL_TOP,
                       skip=("+z",))
    ys = [-COL_LINE_Y + i * (2 * COL_LINE_Y / 5) for i in range(6)]
    for s in (-1, 1):
        for a, b in zip(ys[:-1], ys[1:]):
            for t in (0.25, 0.5, 0.75):
                y = a + (b - a) * t
                mb.box(K, *sorted((s * BODY_HX, s * (SLAB_HX - 0.3))), y - 0.15, y + 0.15, COL_TOP - 0.4, COL_TOP,
                       skip=("+z",))
    BOUNDS["roof-slab"] = (-SLAB_HX - 0.22, SLAB_HX + 0.22, -SLAB_HY - 0.22, SLAB_HY + 0.22, COL_TOP - 1.0, SLAB_TOP)
    return mb.finish(coll)


def build_drum_dome(coll):
    drum = MB("Drum_Granite")
    prof = []
    for i in range(9):
        a = (math.pi / 2) * i / 8
        prof.append((DRUM_R0 - (DRUM_R0 - DRUM_R1) * math.sin(a), DRUM_TOP - 1.6 - (DRUM_TOP - 1.6 - ATTIC_TOP) * math.cos(a)))
    prof += [(DRUM_R1, DRUM_TOP), (DOME_R, DRUM_TOP)]
    drum.lathe(prof, DOME_SEG, ["Granite_Facade"] * (len(prof) - 1), uv=("cyl", TILE["Granite_Facade"], True))
    # small dark vents around the foot of the drum (seen on the photos)
    for k in range(48):
        a = 2 * math.pi * (k + 0.5) / 48
        cr, z0 = DRUM_R0 - 0.25, ATTIC_TOP + 0.3
        c = Vector((math.cos(a) * cr, math.sin(a) * cr, 0))
        U = Vector((-math.sin(a), math.cos(a), 0))
        Nn = Vector((math.cos(a), math.sin(a), 0))
        F = (c + Vector((0, 0, z0)), U, Vector((0, 0, 1)), Nn)
        drum.fbox(F, "Glass_Dark", -0.45, 0.45, 0.0, 0.42, -0.12, 0.3, skip=("k1",))
    d = drum.finish(coll, smooth_angle=35.0)

    dome = MB("Dome_Copper")
    a, h = DOME_R, DOME_H
    R = (a * a + h * h) / (2 * h)
    zc = DOME_BASE + h - R
    phi0 = math.asin(a / R)
    nr = DOME_RINGS
    prof = [(R * math.sin(phi0 * (1 - i / nr)), zc + R * math.cos(phi0 * (1 - i / nr))) for i in range(nr)]
    prof.append((0.0, DOME_BASE + h))
    gore = DOME_SEG // DOME_RIBS
    dome.lathe(prof, DOME_SEG, ["Copper_Patina"] * nr, uv=("gore", TILE["Copper_Patina"], gore))
    # 12 raised ribs on the gore seams, tapering toward the crown
    cvec = Vector((0, 0, zc))
    for r_i in range(DOME_RIBS):
        th = 2 * math.pi * r_i / DOME_RIBS
        rings = []
        for i in range(nr - 3):
            phi = phi0 * (1 - i / nr)
            p = Vector((R * math.sin(phi) * math.cos(th), R * math.sin(phi) * math.sin(th), zc + R * math.cos(phi)))
            n = (p - cvec).normalized()
            t = Vector((-math.sin(th), math.cos(th), 0))
            k = max(0.35, math.sin(phi) / math.sin(phi0)) ** 0.5
            w, hh = 0.30 * k, 0.22 * k
            base = p - n * 0.03
            rings.append([tuple(base - t * w), tuple(base - t * w * 0.7 + n * hh), tuple(base + t * w * 0.7 + n * hh),
                          tuple(base + t * w)])
        dome.ring_loft(rings, "Copper_Patina", closed=False)
    # crown collar and finial
    zt = DOME_BASE + h
    dome.lathe([(2.6, zt - 0.12), (2.6, zt + 0.15), (1.6, zt + 0.32), (0.45, zt + 0.42), (0.45, zt + 0.9),
                (0.0, zt + 1.15)], 48, ["Copper_Patina"] * 5)
    dm = dome.finish(coll, smooth_angle=40.0)
    BOUNDS["dome"] = (-a, a, -a, a, DOME_BASE, zt + 1.15)
    return [d, dm]


def build_podium_and_stairs(coll):
    mb = MB("Podium_Granite")
    ash = MB("Podium_Ashlar")
    K = "Granite_Podium"
    hx, hy = POD_HX, POD_HY
    zc0, zc1 = POD_TOP - 0.6, POD_TOP + 0.02
    sw = STAIR_HW + CHEEK_W
    # coping band (perimeter, split at the stairs)
    segs = [
        (-hx - 0.05, hx + 0.05, hy - COPING_W, hy + 0.05),
        (hx - COPING_W, hx + 0.05, -hy - 0.05, hy - COPING_W),
        (-hx - 0.05, -hx + COPING_W, -hy - 0.05, hy - COPING_W),
        (-hx + COPING_W, -sw, -hy - 0.05, -hy + COPING_W),
        (sw, hx - COPING_W, -hy - 0.05, -hy + COPING_W),
    ]
    for s in segs:
        mb.box(K, s[0], s[1], s[2], s[3], zc0, zc1, bevel=0.03)      # closed underside: it overhangs the wall
    # rough ashlar retaining walls under the coping
    z0, z1 = -0.1, zc0
    inset = 0.08
    walls = [((-hx + inset, -hy + inset), (-sw, -hy + inset)), ((sw, -hy + inset), (hx - inset, -hy + inset)),
             ((hx - inset, -hy + inset), (hx - inset, hy - inset)), ((hx - inset, hy - inset), (-hx + inset, hy - inset)),
             ((-hx + inset, hy - inset), (-hx + inset, -hy + inset))]
    for (a, b) in walls:
        f = ash.face([(a[0], a[1], z0), (b[0], b[1], z0), (b[0], b[1], z1), (a[0], a[1], z1)], "Granite_Ashlar")
        f.normal_update()
        if f.normal.dot(f.calc_center_median() - Vector((0, 0, 2.5))) < 0:
            f.normal_flip()
    # podium top paving: ring between the coping and a line 2 m inside the facade, so the granite runs
    # under the walls, through the entrance recesses (1.6 m deep) and under every sill; the interior
    # floor (build_interior) continues from there
    zt = POD_TOP
    oi = (hx - COPING_W, hy - COPING_W)
    bi = (BODY_HX - POD_UNDER, BODY_HY - POD_UNDER)
    ro = [(oi[0], -oi[1], zt), (oi[0], oi[1], zt), (-oi[0], oi[1], zt), (-oi[0], -oi[1], zt)]
    rb = [(bi[0], -bi[1], zt), (bi[0], bi[1], zt), (-bi[0], bi[1], zt), (-bi[0], -bi[1], zt)]
    for k in range(4):
        k2 = (k + 1) % 4
        mb.face([ro[k], ro[k2], rb[k2], rb[k]], K, want=(0, 0, 1))
    # front strip where the stairs arrive (between the coping segments)
    mb.face([(-sw, -hy - 0.05, zt), (sw, -hy - 0.05, zt), (sw, -oi[1], zt), (-sw, -oi[1], zt)], K, want=(0, 0, 1))
    # low parapets on the coping (sides, back, and the front beside the stairs)
    pz0, pz1, pt = zc1, zc1 + 0.95, 0.45
    par = [
        (-hx + 0.05, hx - 0.05, hy - pt - 0.05, hy - 0.05),
        (hx - pt - 0.05, hx - 0.05, -hy + 0.05, hy - pt - 0.05),
        (-hx + 0.05, -hx + pt + 0.05, -hy + 0.05, hy - pt - 0.05),
        (-hx + pt + 0.05, -sw - 0.3, -hy + 0.05, -hy + pt + 0.05),
        (sw + 0.3, hx - pt - 0.05, -hy + 0.05, -hy + pt + 0.05),
    ]
    for i, s in enumerate(par):
        mb.box(K, s[0], s[1], s[2], s[3], pz0, pz1, skip=("-z",), bevel=0.03)
        BOXES.append(("podium-parapet-%d" % (i + 1), s[0], s[1], s[2], s[3]))
        TOPY["podium-parapet-%d" % (i + 1)] = pz1
    BOUNDS["podium"] = (-hx, hx, -hy, hy, -0.1, POD_TOP)
    # grand stairs with nosings
    st = MB("Stairs_Granite")
    n = STAIR_STEPS
    run = (-hy - STAIR_FRONT_Y) / n
    rise = POD_TOP / n
    prof = [(STAIR_FRONT_Y, 0.0)]
    for i in range(n):
        y = STAIR_FRONT_Y + i * run
        z = (i + 1) * rise
        prof += [(y, z - 0.04), (y - 0.03, z - 0.04), (y - 0.03, z - 0.012), (y - 0.018, z), (y + run, z)]
    prof[-1] = (-hy - 0.05, POD_TOP)
    L = [st.bm.verts.new((-STAIR_HW, y, z)) for (y, z) in prof]
    Rr = [st.bm.verts.new((STAIR_HW, y, z)) for (y, z) in prof]
    for i in range(len(prof) - 1):
        f = st.face(None, K, verts=[L[i], Rr[i], Rr[i + 1], L[i + 1]])
        f.normal_update()
        dy, dz = prof[i + 1][0] - prof[i][0], prof[i + 1][1] - prof[i][1]
        want = Vector((0, -dz, dy))
        if f.normal.dot(want) < 0:
            f.normal_flip()
    BOUNDS["front-stairs"] = (-STAIR_HW, STAIR_HW, STAIR_FRONT_Y, -hy, 0.0, POD_TOP)
    # cheek walls with sloping coping
    for side, (x0, x1) in (("left", (-sw, -STAIR_HW)), ("right", (STAIR_HW, sw))):
        y0, y1 = STAIR_FRONT_Y, -hy - 0.05
        top0, top1 = 0.9, POD_TOP + 0.9
        P = [[[(x, y, z) for z in ((-0.1, top0) if y == y0 else (-0.1, top1))] for y in (y0, y1)] for x in (x0, x1)]
        st.hexa(P, K, skip=("k0", "j1"), bevel=0.03)
        Pc = [[[(x, y, z) for z in ((top0, top0 + 0.25) if y == y0 - 0.12 else (top1, top1 + 0.25))]
               for y in (y0 - 0.12, y1)] for x in (x0 - 0.1, x1 + 0.1)]
        st.hexa(Pc, K, skip=("j1",), bevel=0.03)
        BOXES.append(("stairs-wall-" + side, x0 - 0.1, x1 + 0.1, y0 - 0.12, y1))
    stair_handrails(st, run, rise, hy)
    return [mb.finish(coll), ash.finish(coll), st.finish(coll)]


def stair_handrails(st, run, rise, hy):
    """Brushed stainless handrails down the grand stairs: four lines, posts on every fourth step
    with base plates, a rounded rail 0.9 m above the nosing line with level extensions."""
    K = "Steel_Brushed"
    r = 0.024

    def rail(a, b):
        d = (Vector(b) - Vector(a)).normalized()
        nrm = Vector((0.0, -d.z, d.y)) if abs(d.x) < 0.5 else Vector((0, 0, 1))
        side = Vector((1.0, 0.0, 0.0))
        P = [[[tuple(Vector(p) + side * sx * r + nrm * sk * r) for sk in (-1, 1)] for p in (a, b)] for sx in (-1, 1)]
        st.hexa(P, K, bevel=0.012)

    for x in (-24.0, -8.0, 8.0, 24.0):
        y0 = STAIR_FRONT_Y + 0.25
        y1 = -hy - 0.4
        nose = lambda y: rise + (y - STAIR_FRONT_Y) / run * rise
        a = (x, y0, nose(y0) + 0.9)
        rail((x, y0 - 0.3, nose(y0) + 0.9), a)
        rail(a, (x, y1 - 0.0, nose(y1) + 0.9))
        rail((x, y1, nose(y1) + 0.9), (x, y1 + 0.3, nose(y1) + 0.9))
        for i in range(1, STAIR_STEPS, 4):
            yc = STAIR_FRONT_Y + (i + 0.5) * run
            zb = (i + 1) * rise
            st.box(K, x - 0.06, x + 0.06, yc - 0.06, yc + 0.06, zb, zb + 0.012, skip=("-z",), bevel=0.004)
            st.lathe([(r * 0.9, zb + 0.012), (r * 0.9, nose(yc) + 0.9 - r)], 12, [K], centre=(x, yc))
        BOXES.append(("handrail-%d" % int(x), x - 0.1, x + 0.1, STAIR_FRONT_Y, -hy))


def build_flagpoles(coll):
    """Two flagpoles in the forecourt flanking the axis in front of the grand stairs (national
    flag on the left seen from the approach). Flags are separate Flag_* meshes, pivot at the pole."""
    objs = []
    for i, (x, mat) in enumerate(((-24.0, "Flag_Taegukgi"), (24.0, "Flag_Assembly"))):
        y = FORECOURT_Y + 9.0
        mb = MB("Flagpole_%02d" % (i + 1))
        mb.box("Kerb_Granite", x - 0.9, x + 0.9, y - 0.9, y + 0.9, Z_PAVE - 0.02, Z_PAVE + 0.32, skip=("-z",), bevel=0.03)
        mb.box("Kerb_Granite", x - 0.6, x + 0.6, y - 0.6, y + 0.6, Z_PAVE + 0.32, Z_PAVE + 0.5, skip=("-z",), bevel=0.03)
        top = 21.0
        mb.lathe([(0.2, Z_PAVE + 0.5), (0.2, Z_PAVE + 1.1), (0.15, Z_PAVE + 1.25), (0.13, Z_PAVE + 1.3), (0.07, top),
                  (0.0, top)], 20, ["Steel_Flagpole"] * 5, centre=(x, y))
        mb.sphere((x, y, top + 0.18), 0.2, "Gold_Finial", segs=16, rings=10)
        objs.append(mb.finish(coll, smooth_angle=40.0))
        CIRCLES.append(("flagpole-%d" % (i + 1), x, y, 1.0))
        W, Hh, nu, nv = 4.5, 3.0, 24, 16
        fm = MB("Flag_%02d" % (i + 1))
        vg = [[fm.bm.verts.new((W * a / nu, 0.0, Hh * (b / nv - 0.5))) for b in range(nv + 1)] for a in range(nu + 1)]
        for a in range(nu):
            for b in range(nv):
                f = fm.face(None, mat, want=(0, -1, 0), verts=[vg[a][b], vg[a + 1][b], vg[a + 1][b + 1], vg[a][b + 1]])
                f[fm.done] = 1
                for lp in f.loops:
                    co = lp.vert.co
                    lp[fm.uvl].uv = (co.x / W, co.z / Hh + 0.5)
        fob = fm.finish(coll)
        fob.location = (x + 0.1, y, top - 0.25 - Hh / 2)
        objs.append(fob)
    return objs


def build_interior(coll):
    """What the glazing looks into: a dark interior floor at podium level across the footprint, dark
    back walls INTERIOR_D behind the facade (full height), and a floor / ceiling plate at every
    storey between them, so no window or door ever shows the ground, the sky or the far facade.
    Plates stop 1.2 m behind the facade at the central lattice bays (glass 1.08 m deep) and 0.5 m
    behind it elsewhere (behind the window glass, hidden by the wall band at floor level)."""
    mb = MB("Interior_Shell")
    z0 = POD_TOP
    H = COL_TOP - POD_TOP
    fx, fy = BODY_HX - POD_UNDER, BODY_HY - POD_UNDER
    mb.face([(-fx, -fy, z0), (fx, -fy, z0), (fx, fy, z0), (-fx, fy, z0)], "Interior_Floor", want=(0, 0, 1))
    ix, iy = BODY_HX - INTERIOR_D, BODY_HY - INTERIOR_D
    ring = [(-ix, -iy), (ix, -iy), (ix, iy), (-ix, iy)]
    for k in range(4):
        a, b = ring[k], ring[(k + 1) % 4]
        mid = ((a[0] + b[0]) / 2, (a[1] + b[1]) / 2)
        n = (mid[0] / max(abs(mid[0]), 1e-6) if abs(mid[0]) > 1 else 0, mid[1] / max(abs(mid[1]), 1e-6) if abs(mid[1]) > 1 else 0, 0)
        mb.face([(a[0], a[1], z0), (b[0], b[1], z0), (b[0], b[1], z0 + H), (a[0], a[1], z0 + H)], "Interior_Wall", want=n)

    def slab(x0, x1, y0, y1, z):
        mb.face([(x0, y0, z), (x1, y0, z), (x1, y1, z), (x0, y1, z)], "Interior_Floor", want=(0, 0, 1))
        mb.face([(x0, y0, z - 0.35), (x1, y0, z - 0.35), (x1, y1, z - 0.35), (x0, y1, z - 0.35)], "Interior_Ceiling",
                want=(0, 0, -1))
    ox, oy = BODY_HX - 1.2, BODY_HY - 1.2          # behind the lattice glass everywhere
    ex, ey = BODY_HX - 0.5, BODY_HY - 0.5          # behind the window glass outside the lattice bays
    lh = LATTICE_HALF + 0.1
    levels = floor_levels()[1:] + [H - 0.05]
    for lv in levels:
        z = z0 + lv
        # ring between the back walls and the 1.2 m line
        slab(-ox, ox, -oy, -iy, z)
        slab(-ox, ox, iy, oy, z)
        slab(-ox, -ix, -iy, iy, z)
        slab(ix, ox, -iy, iy, z)
        # lips out to 0.5 m, cut back at the lattice bays
        for sx in (-1, 1):
            slab(min(sx * lh, sx * ex), max(sx * lh, sx * ex), -ey, -oy, z)
            slab(min(sx * lh, sx * ex), max(sx * lh, sx * ex), oy, ey, z)
            slab(min(sx * ox, sx * ex), max(sx * ox, sx * ex), -oy, -lh, z)
            slab(min(sx * ox, sx * ex), max(sx * ox, sx * ex), lh, oy, z)
    ob = mb.finish(coll)
    log("interior shell: %d triangles" % sum(len(p.vertices) - 2 for p in ob.data.polygons))
    return ob


def build_building(coll):
    objs = []
    objs += build_podium_and_stairs(coll)
    objs.append(build_columns(coll))
    objs += build_body(coll)
    objs.append(build_interior(coll))
    objs.append(build_cornice(coll))
    objs += build_drum_dome(coll)
    return objs


# ---------------------------------------------------------------------------
# Site layout (2D shapes -> boolean regions)
# ---------------------------------------------------------------------------
def rect(x0, y0, x1, y1):
    return [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]


def rrect(x0, y0, x1, y1, r, seg=8):
    pts = []
    for (cx, cy, a0) in ((x1 - r, y0 + r, -90), (x1 - r, y1 - r, 0), (x0 + r, y1 - r, 90), (x0 + r, y0 + r, 180)):
        for i in range(seg + 1):
            a = math.radians(a0 + 90 * i / seg)
            pts.append((cx + r * math.cos(a), cy + r * math.sin(a)))
    return pts


def circle(cx, cy, r, seg=64):
    return [(cx + r * math.cos(2 * math.pi * i / seg), cy + r * math.sin(2 * math.pi * i / seg)) for i in range(seg)]


def prism_object(name, polys, z0=-2.0, z1=2.0):
    """Closed prisms (one per polygon) in one temporary object, for booleans."""
    bm = bmesh.new()
    for poly in polys:
        bot = [bm.verts.new((x, y, z0)) for (x, y) in poly]
        top = [bm.verts.new((x, y, z1)) for (x, y) in poly]
        bm.faces.new(top)
        bm.faces.new(list(reversed(bot)))
        n = len(poly)
        for k in range(n):
            k2 = (k + 1) % n
            bm.faces.new((bot[k], bot[k2], top[k2], top[k]))
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])
    me = tag(bpy.data.meshes.new("TMP_" + name))
    bm.to_mesh(me)
    bm.free()
    ob = bpy.data.objects.new("TMP_" + name, me)
    tmp_coll().objects.link(ob)
    return ob


def plane_object(name, polys, grid=None):
    """Flat surface from polygons at z=0; optionally subdivided on a world grid."""
    bm = bmesh.new()
    for poly in polys:
        tris = geometry.tessellate_polygon([[Vector((x, y, 0.0)) for (x, y) in poly]])
        vs = [bm.verts.new((x, y, 0.0)) for (x, y) in poly]
        for t in tris:
            try:
                f = bm.faces.new((vs[t[0]], vs[t[1]], vs[t[2]]))
                f.normal_update()
                if f.normal.z < 0:
                    f.normal_flip()
            except ValueError:
                pass
    bmesh.ops.remove_doubles(bm, verts=bm.verts[:], dist=1e-4)
    me = tag(bpy.data.meshes.new("TMP_" + name))
    bm.to_mesh(me)
    bm.free()
    ob = bpy.data.objects.new("TMP_" + name, me)
    tmp_coll().objects.link(ob)
    return ob


def grid_plane_object(name, x0, y0, x1, y1, cell):
    bm = bmesh.new()
    nx = max(1, int(round((x1 - x0) / cell)))
    ny = max(1, int(round((y1 - y0) / cell)))
    vs = [[bm.verts.new((x0 + (x1 - x0) * i / nx, y0 + (y1 - y0) * j / ny, 0.0)) for j in range(ny + 1)]
          for i in range(nx + 1)]
    for i in range(nx):
        for j in range(ny):
            bm.faces.new((vs[i][j], vs[i + 1][j], vs[i + 1][j + 1], vs[i][j + 1]))
    me = tag(bpy.data.meshes.new("TMP_" + name))
    bm.to_mesh(me)
    bm.free()
    ob = bpy.data.objects.new("TMP_" + name, me)
    tmp_coll().objects.link(ob)
    return ob


def tmp_coll():
    c = bpy.data.collections.get("NA_Tmp")
    if c is None:
        c = tag(bpy.data.collections.new("NA_Tmp"))
        bpy.context.scene.collection.children.link(c)
    return c


def boolean_solver():
    items = [i.identifier for i in bpy.types.BooleanModifier.bl_rna.properties["solver"].enum_items]
    return "EXACT" if "EXACT" in items else items[0]


def apply_booleans(target, cutters, op="DIFFERENCE"):
    """Evaluate target minus/union the cutter objects and return a new bmesh."""
    if not cutters:
        bm = bmesh.new()
        bm.from_mesh(target.data)
        return bm
    cc = tag(bpy.data.collections.new("TMP_cutters"))
    for c in cutters:
        cc.objects.link(c)
    mod = target.modifiers.new("NA_bool", "BOOLEAN")
    mod.operation = op
    mod.operand_type = "COLLECTION"
    mod.collection = cc
    mod.solver = boolean_solver()
    for attr, val in (("use_self", True), ("use_hole_tolerant", True)):
        if hasattr(mod, attr):
            setattr(mod, attr, val)
    dg = bpy.context.evaluated_depsgraph_get()
    ev = target.evaluated_get(dg)
    me = bpy.data.meshes.new_from_object(ev)
    bm = bmesh.new()
    bm.from_mesh(me)
    bpy.data.meshes.remove(me)
    target.modifiers.remove(mod)
    for c in cutters:
        cc.objects.unlink(c)
    bpy.data.collections.remove(cc)
    return bm


def zone_bands(x0, y0, x1, y1, pitch=12.0, border=0.6, band=0.3, xoff=6.0):
    """Border course + a band grid (symmetric about the axis) for a rectangular paved zone."""
    h = band / 2
    out = [rect(x0, y0, x1, y0 + border), rect(x0, y1 - border, x1, y1),
           rect(x0, y0, x0 + border, y1), rect(x1 - border, y0, x1, y1)]
    k = 0
    while True:
        x = xoff + pitch * k
        if x > max(abs(x0), abs(x1)) - 3.0:
            break
        for xx in (x, -x):
            if x0 + 3.0 < xx < x1 - 3.0:
                out.append(rect(xx - h, y0, xx + h, y1))
        k += 1
    y = y0 + pitch
    while y < y1 - 3.0:
        out.append(rect(x0, y - h, x1, y + h))
        y += pitch
    return out


def parterre_spans():
    fy = FOUNTAIN[1]
    ys = [fy + PLAZA_R + 2.0] + [v for ab in CROSS_Y for v in ab] + [FORECOURT_Y - 8.0]
    return [(ys[i], ys[i + 1]) for i in range(0, len(ys), 2)]


def site_shapes():
    S = {}
    fx, fy = FOUNTAIN
    sw = STAIR_HW + CHEEK_W
    S["building"] = [rect(-POD_HX - 0.06, -POD_HY - 0.06, POD_HX + 0.06, POD_HY + 0.06),
                     rect(-sw - 0.12, STAIR_FRONT_Y - 0.13, sw + 0.12, -POD_HY)]
    S["basin"] = [circle(fx, fy, FOUNTAIN_FOOT_R, 128)]
    S["pools"] = [rect(-POOL_HW - POOL_COPING, y0, POOL_HW + POOL_COPING, y1) for (y0, y1) in POOL_SEGS]
    S["gate"] = [rect(-GATE_HALF_W, GATE_Y - GATE_BACK, GATE_HALF_W, GATE_Y + GATE_BACK)]
    S["walls"] = [(SITE_X0, -GATE_WINGS_X), (GATE_WINGS_X, SITE_X1)]
    S["gate_complex"] = [rect(-GATE_WINGS_X - 1.0, GATE_Y - 9.0, GATE_WINGS_X + 1.0, GATE_Y + GATE_BACK + 0.3),
                         rect(-32.0, GATE_Y - GATE_FRONT - 1.0, 32.0, GATE_Y)]
    S["site"] = [rect(SITE_X0, SITE_Y0, SITE_X1, SITE_Y1)]
    S["inner_site"] = [rect(SITE_X0, INNER_Y0, SITE_X1, SITE_Y1)]
    # promenade loop around the building + links to the apron and the contemporary garden
    S["prom_outer"] = [rrect(-RO_X, RO_Y0, RO_X, RO_Y1, 14)]
    S["prom_inner"] = [rrect(-RI_X, RI_Y0, RI_X, RI_Y1, 8)]
    S["prom_extra"] = [rect(APRON_X - 0.5, -20, RI_X + 0.5, -11), rect(-RI_X - 0.5, -20, -APRON_X + 0.5, -11),
                       rect(RO_X - 0.5, CONT["cy"] - 1.75, CONT["cx"] - CONT["hx"] + 0.2, CONT["cy"] + 1.75)]
    # inner ring path (inside the wall) and branch paths into the two side gardens
    S["path_outer"] = [rrect(-200, RO_Y0, 200, SITE_Y1 - 7, 10)]
    S["path_inner"] = [rrect(-197, RO_Y0 + 3.0, 197, SITE_Y1 - 10, 7)]
    S["branches"] = [rect(-197.5, TRAD["cy"] - 1.75, TRAD["cx"] - TRAD["hx"] + 0.2, TRAD["cy"] + 1.75),
                     rect(CONT["cx"] + CONT["hx"] - 0.2, CONT["cy"] - 1.75, 197.5, CONT["cy"] + 1.75)]
    # courts of the side gardens
    t, c = TRAD, CONT
    S["trad_court"] = [rect(t["cx"] - t["hx"], t["cy"] - t["hy"], t["cx"] + t["hx"], t["cy"] + t["hy"])]
    S["cont_court"] = [rect(c["cx"] - c["hx"], c["cy"] - c["hy"], c["cx"] + c["hx"], c["cy"] + c["hy"])]
    S["cont_terrace"] = [rect(c["cx"] - c["hx"], c["cy"] - 6.0, c["cx"] - c["hx"] + 12.0, c["cy"] + 6.0)]
    # granite: forecourt/apron, pool head terrace, gate inner court, fountain plaza, arrival forecourt, approach
    ax0, ay0, ax1, ay1 = ARRIVAL
    S["plaza"] = [circle(fx, fy, PLAZA_R, 160)]
    S["paving_granite"] = [rect(-APRON_X, FORECOURT_Y, APRON_X, APRON_Y1),
                           rect(-22.0, POOL_SEGS[-1][1], 22.0, FORECOURT_Y + 0.5),
                           rect(-20.0, GATE_Y + GATE_BACK - 0.2, 20.0, fy),
                           rect(-GATE_HALF_W, INNER_Y0 - 0.01, GATE_HALF_W, GATE_Y + GATE_BACK),
                           rect(ax0, ay0, ax1, ay1),
                           rect(-APPROACH_HW, SITE_Y0, APPROACH_HW, ay0 + 0.5)] + [circle(x, y, 3.8, 72) for (x, y) in HAETAE_POS]
    # axis walks either side of the pool and the cross walks (large light slabs)
    S["axis_lanes"] = [rect(-WALK_X1, fy, -WALK_X0, FORECOURT_Y + 0.5), rect(WALK_X0, fy, WALK_X1, FORECOURT_Y + 0.5)]
    S["axis_lanes"] += [rect(-AVENUE_X - 2.0, y0, AVENUE_X + 2.0, y1) for (y0, y1) in CROSS_Y]
    ga = GATE_Y - GATE_FRONT + 0.2
    S["approach_lanes"] = [rect(-3.0, SITE_Y0, 3.0, ga)] + [rect(sx * GATE_SIDE_X - 2.25, ARRIVAL[1] + 0.6,
                                                                 sx * GATE_SIDE_X + 2.25, ga) for sx in (-1, 1)]
    S["axis_lanes"] += S["approach_lanes"]
    # beds: building foot, Haetae beds at the stairs, parterre borders and flower strips, forecourt edge
    beds = []
    beds += [rect(-POD_HX, -POD_HY - 3.0, -sw - 0.12, -POD_HY - 0.06), rect(sw + 0.12, -POD_HY - 3.0, POD_HX, -POD_HY - 0.06)]
    beds += [rect(POD_HX + 0.06, -POD_HY, POD_HX + 3.0, POD_HY), rect(-POD_HX - 3.0, -POD_HY, -POD_HX - 0.06, POD_HY)]
    beds += [rect(-POD_HX, POD_HY + 0.06, POD_HX, POD_HY + 3.0)]
    beds += [rect(-82, FORECOURT_Y - 6.0, -24, FORECOURT_Y - 2.0), rect(24, FORECOURT_Y - 6.0, 82, FORECOURT_Y - 2.0)]
    for sx in (-1, 1):
        a0, a1 = sorted((sx * (APPROACH_HW + 0.4), sx * (APPROACH_HW + 2.2)))
        beds.append(rect(a0, SITE_Y0 + 3.0, a1, ARRIVAL[1] - 1.0))
        c0, c1 = sorted((sx * 20.4, sx * 22.2))
        beds.append(rect(c0, GATE_Y + GATE_BACK + 1.6, c1, fy - 3.0))
        k0, k1 = sorted((sx * (PACK_HX + 0.2), sx * (PACK_HX + 1.8)))
        beds.append(rect(k0, GATE_Y - 34.0, k1, GATE_Y - 0.6))
    S["parterre_panels"] = []
    S["parterre_rings"] = []
    for (py0, py1) in parterre_spans():
        for sx in (-1, 1):
            x0, x1 = sorted((sx * PARTERRE_X0, sx * PARTERRE_X1))
            S["parterre_panels"].append((x0, py0, x1, py1))
            S["parterre_rings"].append((rect(x0, py0, x1, py1), rect(x0 + 1.0, py0 + 1.0, x1 - 1.0, py1 - 1.0)))
            for (u0, u1) in (PARTERRE_STRIP,):
                a0, a1 = sorted((sx * (PARTERRE_X0 + u0), sx * (PARTERRE_X0 + u1)))
                beds.append(rect(a0, py0 + 2.4, a1, py1 - 2.4))
    S["beds"] = beds
    # informal groves and the garden backdrops (woodland floor)
    grng = random.Random(RNG_SEED + 5)
    S["groves"] = []
    for (gx, gy, gr) in GROVES:
        ph = [grng.uniform(0, 6.283) for _ in range(3)]
        S["groves"].append([(gx + math.cos(a) * gr * (1 + 0.16 * math.sin(3 * a + ph[0]) + 0.1 * math.sin(5 * a + ph[1])),
                             gy + math.sin(a) * gr * (1 + 0.16 * math.sin(2 * a + ph[2])))
                            for a in [2 * math.pi * i / 40 for i in range(40)]])
    S["groves"] += [rect(t["cx"] + t["hx"] + 0.9, t["cy"] - t["hy"] - 6.0, t["cx"] + t["hx"] + 12.0, t["cy"] + t["hy"] + 6.0),
                    rect(t["cx"] - t["hx"] - 1.0, t["cy"] + t["hy"] + 0.8, t["cx"] + t["hx"] + 0.9, t["cy"] + t["hy"] + 7.0),
                    rect(t["cx"] - t["hx"] - 1.0, t["cy"] - t["hy"] - 7.0, t["cx"] + t["hx"] + 0.9, t["cy"] - t["hy"] - 0.8),
                    rect(c["cx"] - c["hx"], c["cy"] + c["hy"] + 0.8, c["cx"] + c["hx"], c["cy"] + c["hy"] + 6.0)]
    S["wood_in_cut"] = [rrect(SITE_X0 + 27.0, INNER_Y0 + 27.0, SITE_X1 - 27.0, SITE_Y1 - 27.0, 4),
                        rect(-70.0, INNER_Y0 - 1.0, 70.0, INNER_Y0 + 40.0)]
    S["arrival_belts"] = [rect(SITE_X0, SITE_Y0, SITE_X0 + 14.0, INNER_Y0 - 0.45),
                          rect(SITE_X1 - 14.0, SITE_Y0, SITE_X1, INNER_Y0 - 0.45),
                          rect(SITE_X0, SITE_Y0, -APPROACH_HW - 8.0, SITE_Y0 + 12.0),
                          rect(APPROACH_HW + 8.0, SITE_Y0, SITE_X1, SITE_Y0 + 12.0)]
    # bands: axis walks, crossings, zones; drains; tree pits
    bands = []
    for sx in (-1, 1):
        for (u0, u1) in ((WALK_X0, WALK_X0 + 0.45), (WALK_X1 - 0.45, WALK_X1)):
            x0, x1 = sorted((sx * u0, sx * u1))
            bands.append(rect(x0, fy, x1, FORECOURT_Y + 0.5))
        x0, x1 = sorted((sx * WALK_X0, sx * WALK_X1))
        y = FORECOURT_Y - AXIS_BAND_PITCH
        while y > fy + PLAZA_R:
            if not any(a - 0.5 < y < b + 0.5 for (a, b) in CROSS_Y):
                bands.append(rect(x0, y - 0.15, x1, y + 0.15))
            y -= AXIS_BAND_PITCH
    for (y0, y1) in CROSS_Y:
        bands += [rect(-AVENUE_X - 2.0, y0, AVENUE_X + 2.0, y0 + 0.45), rect(-AVENUE_X - 2.0, y1 - 0.45, AVENUE_X + 2.0, y1)]
    for (p0, p1, p2, p3) in S["approach_lanes"]:
        bands += [rect(p0[0] - 0.35, p0[1], p0[0], p2[1]), rect(p2[0], p0[1], p2[0] + 0.35, p2[1])]
    S["axis_bands"] = bands
    fb = zone_bands(-APRON_X, FORECOURT_Y, APRON_X, APRON_Y1)
    fb += zone_bands(ax0, ay0, ax1, ay1, xoff=13.0)
    fb += zone_bands(-APPROACH_HW, SITE_Y0, APPROACH_HW, ay0 + 0.5, pitch=10.0, xoff=6.0)
    fb += [rect(-22.0, POOL_SEGS[-1][1], 22.0, POOL_SEGS[-1][1] + 0.45)]
    S["bands"] = fb
    yc = math.sqrt(PLAZA_R ** 2 - GATE_SIDE_X ** 2) + 0.6
    S["drains"] = []
    for sx in (-1, 1):
        y0 = fy + yc
        for (a, b) in CROSS_Y + [(FORECOURT_Y - 0.5, FORECOURT_Y)]:
            S["drains"].append(rect(sx * GATE_SIDE_X - DRAIN_W / 2, y0, sx * GATE_SIDE_X + DRAIN_W / 2, a - 1.0))
            y0 = b + 1.0
    S["tree_pits"] = [rect(x - 0.8, y - 0.8, x + 0.8, y + 0.8) for (x, y) in TREE_PITS + ARRIVAL_PITS]
    return S


def surface_from(bm, z, name, key, coll, grid_vc=False, split=False, min_area=0.5):
    """Keep the top faces of a boolean result (all verts at the highest z), make them face
    up, put them at height z and build objects."""
    zmax = max((v.co.z for v in bm.verts), default=0.0)
    bad = [f for f in bm.faces if any(abs(v.co.z - zmax) > 1e-3 for v in f.verts)]
    bmesh.ops.delete(bm, geom=bad, context="FACES")
    for f in bm.faces:
        f.normal_update()
        if f.normal.z < 0:
            f.normal_flip()
    bmesh.ops.triangulate(bm, faces=[f for f in bm.faces if len(f.verts) > 4], quad_method="BEAUTY", ngon_method="BEAUTY")
    bmesh.ops.dissolve_degenerate(bm, dist=1e-4, edges=bm.edges[:])
    for v in bm.verts:
        v.co.z = z
    islands = []
    if split:
        seen = set()
        for f in bm.faces:
            if f.index in seen:
                continue
            stack, isl = [f], []
            seen.add(f.index)
            while stack:
                g = stack.pop()
                isl.append(g)
                for e in g.edges:
                    for h in e.link_faces:
                        if h.index not in seen:
                            seen.add(h.index)
                            stack.append(h)
            islands.append(isl)
    else:
        islands = [list(bm.faces)]
    objs = []
    areas = [sum(f.calc_area() for f in isl) for isl in islands]
    order = sorted(range(len(islands)), key=lambda i: -areas[i])
    n_out = 0
    for idx in order:
        if areas[idx] < min_area:
            continue
        isl = islands[idx]
        n_out += 1
        mb = MB("%s_%02d" % (name, n_out))
        vmap = {}
        for f in isl:
            vs = []
            for v in f.verts:
                if v not in vmap:
                    vmap[v] = mb.bm.verts.new(v.co)
                vs.append(vmap[v])
            try:
                nf = mb.face(None, key, want=(0, 0, 1), verts=vs)
            except ValueError:
                pass
        ob = mb.finish(coll)
        if grid_vc:
            add_lawn_colours(ob)
            lawn_uvs(ob)
        objs.append(ob)
    bm.free()
    return objs


def lawn_uvs(ob, cell=20.0):
    """World-scale grass UVs with a random quarter-turn and offset per 20 m cell, which breaks
    up the visible repeat on the large lawns (seams between grass patches are invisible)."""
    me = ob.data
    uvl = me.uv_layers.active.data
    tile = TILE["Lawn_Grass"]
    for p in me.polygons:
        c = p.center
        ci, cj = math.floor(c.x / cell), math.floor(c.y / cell)
        h = (ci * 73856093) ^ (cj * 19349663) ^ RNG_SEED
        rot = h % 4
        ou, ov = ((h >> 3) % 997) / 997.0, ((h >> 13) % 991) / 991.0
        for li in p.loop_indices:
            co = me.vertices[me.loops[li].vertex_index].co
            lu, lv = (co.x - ci * cell) / tile, (co.y - cj * cell) / tile
            for _ in range(rot):
                lu, lv = -lv, lu
            uvl[li].uv = (lu + ou, lv + ov)


def add_lawn_colours(ob):
    """Low-frequency colour variation (multiplied into the grass texture)."""
    me = ob.data
    ca = me.color_attributes.new("Col", "FLOAT_COLOR", "POINT")
    rng = random.Random(RNG_SEED + 7)
    waves = [(rng.uniform(0.01, 0.05), rng.uniform(0, 2 * math.pi), rng.uniform(0, 2 * math.pi), rng.uniform(0.3, 1.0))
             for _ in range(7)]
    for i, v in enumerate(me.vertices):
        x, y = v.co.x, v.co.y
        n = sum(a * math.sin(f * (x * math.cos(d) + y * math.sin(d)) + p) for (f, p, d, a) in waves) / 3.0
        b = 0.90 + 0.10 * max(-1.0, min(1.0, n))
        yel = 0.5 + 0.5 * math.sin(0.021 * x + 0.017 * y + 1.3)
        ca.data[i].color = (b * (1.0 + 0.05 * yel), b, b * (1.0 - 0.12 * yel), 1.0)
    me.color_attributes.active_color = ca


def boundary_loops(ob):
    """Closed boundary loops of a flat mesh, oriented with the surface on the left."""
    me = ob.data
    bm = bmesh.new()
    bm.from_mesh(me)
    nxt = {}
    for e in bm.edges:
        if len(e.link_faces) != 1:
            continue
        f = e.link_faces[0]
        # follow the face winding so the face is on the left of a -> b
        for lp in f.loops:
            if lp.edge == e:
                a, b = lp.vert, lp.link_loop_next.vert
                nxt[a.index] = (b.index, tuple(b.co[:2]), tuple(a.co[:2]))
                break
    loops = []
    used = set()
    co = {v.index: tuple(v.co[:2]) for v in bm.verts}
    for start in list(nxt.keys()):
        if start in used:
            continue
        loop = []
        cur = start
        guard = 0
        while cur not in used and cur in nxt and guard < 100000:
            used.add(cur)
            loop.append(co[cur])
            cur = nxt[cur][0]
            guard += 1
        if len(loop) >= 3:
            loops.append(simplify_loop(loop))
    bm.free()
    return [l for l in loops if len(l) >= 3]


def simplify_loop(pts, tol=0.01):
    out = list(pts)
    changed = True
    while changed and len(out) > 3:
        changed = False
        res = []
        n = len(out)
        for i in range(n):
            a, b, c = out[i - 1], out[i], out[(i + 1) % n]
            abx, aby = b[0] - a[0], b[1] - a[1]
            bcx, bcy = c[0] - b[0], c[1] - b[1]
            cross = abx * bcy - aby * bcx
            la = math.hypot(abx, aby)
            lc = math.hypot(bcx, bcy)
            if la < 1e-4 or (lc > 0 and abs(cross) / max(la * lc, 1e-9) < tol and abx * bcx + aby * bcy > 0):
                changed = True
                continue
            res.append(b)
        out = res
    return out


def signed_area(pts):
    return 0.5 * sum(pts[i][0] * pts[(i + 1) % len(pts)][1] - pts[(i + 1) % len(pts)][0] * pts[i][1] for i in range(len(pts)))


def offset_loop(pts, off):
    """Offset a closed loop to the LEFT by off (mitred, clamped)."""
    n = len(pts)
    res = []
    for i in range(n):
        p0, p1, p2 = Vector(pts[i - 1]), Vector(pts[i]), Vector(pts[(i + 1) % n])
        d1 = (p1 - p0).normalized()
        d2 = (p2 - p1).normalized()
        n1 = Vector((-d1.y, d1.x))
        n2 = Vector((-d2.y, d2.x))
        m = (n1 + n2)
        if m.length < 1e-6:
            m = n1
        m.normalize()
        k = 1.0 / max(0.35, m.dot(n1))
        res.append(tuple(p1 + m * off * k))
    return res


def sweep_kerb(mb, loop, prof, key):
    """Sweep a cross profile [(lateral offset to the left, z)] along a closed loop."""
    rings = [offset_loop(loop, d) for (d, z) in prof]
    n = len(loop)
    V = [[mb.bm.verts.new((p[0], p[1], prof[r][1])) for p in rings[r]] for r in range(len(prof))]
    for r in range(len(prof) - 1):
        dz = prof[r + 1][1] - prof[r][1]
        dd = prof[r + 1][0] - prof[r][0]
        for k in range(n):
            k2 = (k + 1) % n
            f = mb.face(None, key, verts=[V[r][k], V[r][k2], V[r + 1][k2], V[r + 1][k]])
            f.normal_update()
            a = Vector(loop[k])
            b = Vector(loop[k2])
            t = (b - a).normalized()
            left = Vector((-t.y, t.x, 0))
            # outward normal of the profile segment in (left, z): (dd, dz) rotated counter-clockwise
            want = left * (-dz) + Vector((0, 0, dd))
            if f.normal.dot(want) < 0:
                f.normal_flip()


def solid_from_bm(bm, name):
    me = tag(bpy.data.meshes.new("TMP_" + name))
    bm.to_mesh(me)
    bm.free()
    ob = bpy.data.objects.new("TMP_" + name, me)
    tmp_coll().objects.link(ob)
    return ob


def union_solid(name, shapes):
    """Boolean union of prisms (one per 2D shape) -> one closed solid object."""
    objs = [prism_object("%s_%d" % (name, i), [s]) for i, s in enumerate(shapes)]
    if len(objs) == 1:
        return objs[0]
    return solid_from_bm(apply_booleans(objs[0], objs[1:], op="UNION"), name + "_u")


def region(name, add_shapes, sub_objs, extra_sub_shapes=()):
    """Solid region = union(add_shapes) - union(extra_sub_shapes) - sub_objs (solids)."""
    t = union_solid(name, add_shapes)
    subs = list(sub_objs)
    if extra_sub_shapes:
        subs.append(union_solid(name + "_sub", list(extra_sub_shapes)))
    if not subs:
        bm = bmesh.new()
        bm.from_mesh(t.data)
        return solid_from_bm(bm, name + "_r")
    return solid_from_bm(apply_booleans(t, subs), name + "_r")


def top_bm(ob):
    bm = bmesh.new()
    bm.from_mesh(ob.data)
    return bm


def build_site(coll):
    S = site_shapes()
    SITE_SHAPES.clear()
    SITE_SHAPES.update(S)
    objs = []
    fx, fy = FOUNTAIN
    c_building = union_solid("building", S["building"])
    c_basin = prism_object("basin", S["basin"])
    c_plaza = prism_object("plaza", S["plaza"])
    c_pools = union_solid("pools", S["pools"])
    c_wall = prism_object("wall_strip", [rect(SITE_X0 - 1.0, GATE_Y - 0.55, SITE_X1 + 1.0, GATE_Y + 0.55)])
    c_pack = prism_object("pack_ground", [rect(-PACK_HX, GATE_Y - PACK_FRONT, PACK_HX, GATE_Y - 0.5)])
    blockers = [c_building, c_basin, c_pools, c_wall, c_pack]
    # Concrete pavers: promenade loop, ring path, branch paths, links (paths win over beds)
    prom = region("prom", S["prom_outer"], [], S["prom_inner"])
    ring = region("path", S["path_outer"], [], S["path_inner"])
    links = union_solid("links", S["prom_extra"] + S["branches"])
    pc_u = solid_from_bm(apply_booleans(prom, [ring, links], op="UNION"), "pav_c_u")
    gate_keep = union_solid("gate_keep", S["gate"] + S["trad_court"] + S["cont_court"])
    pc_s = solid_from_bm(apply_booleans(pc_u, blockers + [gate_keep]), "pav_c_all")
    pav_c = surface_from(top_bm(pc_s), Z_PAVE + 0.005, "Paving_Concrete", "Paving_Concrete", coll)
    objs += pav_c
    # Beds: building foot, Haetae beds, forecourt edge, parterre flower strips + hedge border rings
    beds_main = region("beds_main", S["beds"], blockers + [pc_s])
    prings = [region("pring_%d" % i, [o], [], [inn]) for i, (o, inn) in enumerate(S["parterre_rings"])]
    bed_s = solid_from_bm(apply_booleans(beds_main, prings, op="UNION"), "beds_all")
    beds = surface_from(top_bm(bed_s), Z_BED, "Bed", "Bed_Mulch", coll, split=True)
    objs += beds
    # Side-garden courts: fine granite gravel, the contemporary seating terrace in granite
    terr = union_solid("terrace", S["cont_terrace"])
    court_s = solid_from_bm(apply_booleans(union_solid("courts", S["trad_court"] + S["cont_court"]), [terr]), "courts_g")
    courts = surface_from(top_bm(court_s), Z_PAVE + 0.01, "Gravel_Court", "Gravel_Court", coll, split=True)
    objs += courts
    # Granite paving minus grated tree pits; dark bands divide it into fields
    pits = union_solid("pits", S["tree_pits"])
    pg_s = region("pav_g", S["paving_granite"] + S["plaza"] + S["axis_lanes"] + S["cont_terrace"],
                  blockers + [bed_s, pc_s, pits, court_s])
    lane_b = region("lane_bands", S["axis_bands"], [c_plaza])
    rings = [region("pband_%d" % i, [circle(fx, fy, r1, 160)], [], [circle(fx, fy, r0, 160)])
             for i, (r0, r1) in enumerate(((FOUNTAIN_FOOT_R, FOUNTAIN_FOOT_R + 0.5), (PLAZA_R - 0.6, PLAZA_R)))]
    radial = []
    for k in range(16):
        a = math.radians(11.25 + 22.5 * k)
        c, s = math.cos(a), math.sin(a)
        r0, r1, hw = FOUNTAIN_FOOT_R + 0.4, PLAZA_R - 0.4, 0.15
        radial.append([(fx + c * r0 - s * hw, fy + s * r0 + c * hw), (fx + c * r0 + s * hw, fy + s * r0 - c * hw),
                       (fx + c * r1 + s * hw, fy + s * r1 - c * hw), (fx + c * r1 - s * hw, fy + s * r1 + c * hw)])
    pads = [region("hband_%d" % i, [circle(x, y, 4.2, 96)], [], [circle(x, y, 3.7, 96)])
            for i, (x, y) in enumerate(HAETAE_POS)]
    other_b = union_solid("bands_o", S["bands"] + radial)
    band_u = solid_from_bm(apply_booleans(other_b, [lane_b] + rings + pads, op="UNION"), "bands_u")
    drains = union_solid("drains", S["drains"])
    band_in = solid_from_bm(apply_booleans(band_u, [pg_s], op="INTERSECT"), "bands_in")
    band_in = solid_from_bm(apply_booleans(band_in, [drains]), "bands_final")
    fields = solid_from_bm(apply_booleans(pg_s, [band_u, drains]), "fields")
    axis_zone = region("axis_zone", S["axis_lanes"], [c_plaza])
    f_axis = solid_from_bm(apply_booleans(fields, [axis_zone], op="INTERSECT"), "fields_axis")
    f_other = solid_from_bm(apply_booleans(fields, [axis_zone]), "fields_other")
    pav_a = surface_from(top_bm(f_axis), Z_PAVE, "Paving_Axis", "Paving_Axis", coll)
    pav_g = surface_from(top_bm(f_other), Z_PAVE, "Paving_Granite", "Paving_Granite", coll)
    pav_b = surface_from(top_bm(band_in), Z_PAVE + 0.002, "Paving_Band", "Paving_Band", coll)
    for ob in pav_a:
        paving_fields(ob, TILE["Paving_Axis"], axis_field)
    for ob in pav_g:
        paving_fields(ob, TILE["Paving_Granite"], granite_field)
    objs += pav_a + pav_g + pav_b
    objs.append(build_slot_drains(coll, S["drains"]))
    objs += build_tree_pits(coll)  # lowered with the rest at the end of build_site
    # Woodland floor: inner belt between the site edge and the ring path, a band inside the ring
    # path, groves, garden backdrops and the belts of the arrival zone (soft edge, short skirt)
    w_out = region("wood_out", S["inner_site"], [], S["path_outer"])
    w_in = region("wood_in", S["path_inner"], [], S["wood_in_cut"])
    w_gr = union_solid("wood_groves", S["groves"] + S["arrival_belts"])
    wood_u = solid_from_bm(apply_booleans(w_out, [w_in, w_gr], op="UNION"), "wood_u")
    wood_s = solid_from_bm(apply_booleans(wood_u, blockers + [pc_s, bed_s, pg_s, court_s, gate_keep]), "wood_all")
    woods = surface_from(top_bm(wood_s), Z_WOOD, "Bed_Woodland", "Bed_Woodland", coll, split=True, min_area=2.0)
    objs += woods
    sk = MB("Bed_Woodland_Edge")
    for wd in woods:
        for lp in boundary_loops(wd):
            sweep_kerb(sk, lp, [(0.0, -0.12), (0.0, Z_WOOD)], "Bed_Woodland")
    objs.append(sk.finish(coll))
    # Lawn: the whole site minus everything else, on a 5 m grid for colour variation
    lawn_t = grid_plane_object("lawn", SITE_X0, SITE_Y0, SITE_X1, SITE_Y1, 5.0)
    bm = apply_booleans(lawn_t, blockers + [bed_s, pg_s, pc_s, wood_s, court_s, gate_keep])
    lawns = surface_from(bm, Z_LAWN, "Lawn", "Lawn_Grass", coll, grid_vc=True, split=True, min_area=4.0)
    objs += lawns
    # surrounding meadow beyond the site edge at the arrival level, with an 8 m embankment down
    # from the inner grounds (so views and the aerial never end in void)
    objs.append(build_surround(coll))
    # safety net under everything: a soil-coloured base plane catches any sliver gaps
    gb = MB("Ground_Base")
    py0 = GATE_Y - PACK_FRONT
    for (x0, y0, x1, y1) in ((SITE_X0, GATE_Y, SITE_X1, SITE_Y1), (SITE_X0, SITE_Y0, SITE_X1, py0),
                             (SITE_X0, py0, -PACK_HX, GATE_Y - 0.01), (PACK_HX, py0, SITE_X1, GATE_Y - 0.01)):
        gb.face([(x0, y0, -0.2), (x1, y0, -0.2), (x1, y1, -0.2), (x0, y1, -0.2)], "Bed_Mulch", want=(0, 0, 1))
    objs.append(gb.finish(coll))
    # granite mowing edge along every hard lawn edge (none where the lawn meets woodland floor or
    # the site edge), stone edging round the beds and the gravel courts
    kb = MB("Kerbs")
    lawn_prof = [(0.0, -0.12), (0.0, 0.085), (0.015, 0.10), (0.185, 0.10), (0.2, 0.085), (0.2, Z_LAWN - 0.01)]
    for lw in lawns:
        loops = boundary_loops(lw)
        outer = max(loops, key=lambda l: abs(signed_area(l)))
        LAWN_POLYS.append((lw.name, outer, [l for l in loops if l is not outer]))
        for lp in loops:
            n = len(lp)
            hard = []
            for i in range(n):
                a, b = lp[i], lp[(i + 1) % n]
                mx, my = (a[0] + b[0]) / 2, (a[1] + b[1]) / 2
                dx, dy = b[0] - a[0], b[1] - a[1]
                L = math.hypot(dx, dy) or 1.0
                ox, oy = mx + dy / L * 0.4, my - dx / L * 0.4          # just outside the lawn (right side)
                on_edge = (abs(mx - SITE_X0) < 0.2 or abs(mx - SITE_X1) < 0.2 or abs(my - SITE_Y0) < 0.2
                           or abs(my - SITE_Y1) < 0.2)
                hard.append(not on_edge and not is_woodland(ox, oy) and not in_beds(ox, oy))
            if all(hard):
                sweep_kerb(kb, lp, lawn_prof, "Kerb_Granite")
                continue
            for run in split_runs(lp, hard):
                if len(run) >= 2:
                    sweep_kerb_open(kb, run, lawn_prof, "Kerb_Granite")
    for bd in beds:
        for lp in boundary_loops(bd):
            sweep_kerb(kb, lp, [(0.0, -0.05), (0.0, 0.17), (0.012, 0.185), (0.108, 0.185), (0.12, 0.17),
                                (0.12, Z_BED - 0.01)], "Kerb_Granite")
    for ct in courts:
        for lp in boundary_loops(ct):
            sweep_kerb(kb, lp, [(0.0, -0.05), (0.0, 0.035), (0.01, 0.045), (0.29, 0.045), (0.3, 0.035),
                                (0.3, Z_PAVE + 0.005)], "Stone_Dressed")
    objs.append(kb.finish(coll))
    BOUNDS["ground"] = (SITE_X0, SITE_X1, SITE_Y0, SITE_Y1, Z_PAVE, Z_LAWN)
    lower_arrival([o for o in objs if o.name != "Ground_Surround"])
    return objs


def lower_arrival(objs):
    """Everything in front of the wall line sits Z_ARRIVAL lower (the gate's outer approach)."""
    for ob in objs:
        if ob is None or ob.type != "MESH":
            continue
        for v in ob.data.vertices:
            if v.co.y < GATE_Y:
                v.co.z += Z_ARRIVAL_G
        ob.data.update()


def edge_z(y):
    return 0.0 if y >= GATE_Y else Z_ARRIVAL_G


def surround_z(x, y):
    """Ground height outside the site: an 8 m embankment from the site edge down to the meadow."""
    dx = max(SITE_X0 - x, 0.0, x - SITE_X1)
    dy = max(SITE_Y0 - y, 0.0, y - SITE_Y1)
    d = max(dx, dy)
    low = Z_ARRIVAL_G - 0.03
    ez = edge_z(min(max(y, SITE_Y0), SITE_Y1))
    return low + (ez - low) * max(0.0, 1.0 - d / 8.0)


def build_surround(coll):
    sm = MB("Ground_Surround")
    E, B = 1500.0, 8.0
    ys = sorted(set([SITE_Y0 - B] + [y for y in frange(SITE_Y0, SITE_Y1, 10.0)] + [GATE_Y - 0.6, GATE_Y, SITE_Y1, SITE_Y1 + B]))
    xs = sorted(set([SITE_X0] + [x for x in frange(SITE_X0, SITE_X1, 10.0)] + [SITE_X1]))
    # side embankments (full height range incl. corners), back and front embankments
    for (xa, xb) in ((SITE_X0 - B, SITE_X0), (SITE_X1, SITE_X1 + B)):
        for j in range(len(ys) - 1):
            q = [(xa, ys[j]), (xb, ys[j]), (xb, ys[j + 1]), (xa, ys[j + 1])]
            sm.face([(x, y, surround_z(x, y) if not (SITE_X0 <= x <= SITE_X1) else edge_z(y)) for (x, y) in q],
                    "Lawn_Grass", want=(0, 0, 1))
    for (ya, yb) in ((SITE_Y1, SITE_Y1 + B), (SITE_Y0 - B, SITE_Y0)):
        for i in range(len(xs) - 1):
            q = [(xs[i], ya), (xs[i + 1], ya), (xs[i + 1], yb), (xs[i], yb)]
            sm.face([(x, y, surround_z(x, y) if not (SITE_Y0 <= y <= SITE_Y1) else edge_z(y)) for (x, y) in q],
                    "Lawn_Grass", want=(0, 0, 1))
    low = Z_ARRIVAL_G - 0.03
    for (x0, y0, x1, y1) in ((-E, -E, SITE_X0 - B, E), (SITE_X1 + B, -E, E, E), (SITE_X0 - B, -E, SITE_X1 + B, SITE_Y0 - B),
                             (SITE_X0 - B, SITE_Y1 + B, SITE_X1 + B, E)):
        nx, ny = max(1, int(round((x1 - x0) / 60.0))), max(1, int(round((y1 - y0) / 60.0)))
        V = [[sm.bm.verts.new((x0 + (x1 - x0) * i / nx, y0 + (y1 - y0) * j / ny, low)) for j in range(ny + 1)]
             for i in range(nx + 1)]
        for i in range(nx):
            for j in range(ny):
                sm.face(None, "Lawn_Grass", want=(0, 0, 1), verts=[V[i][j], V[i + 1][j], V[i + 1][j + 1], V[i][j + 1]])
    bmesh.ops.remove_doubles(sm.bm, verts=sm.bm.verts[:], dist=0.01)
    sur = sm.finish(coll)
    add_lawn_colours(sur)
    lawn_uvs(sur)
    return sur


def frange(a, b, st):
    out = []
    v = a
    while v < b - 1e-6:
        out.append(v)
        v += st
    return out


def axis_field(x, y):
    if y < GATE_Y:
        return ("l", int(round(x / 4.0)))
    for i, (a, b) in enumerate(CROSS_Y):
        if a - 0.01 <= y <= b + 0.01:
            return ("c", i, math.floor(x / 6.0))
    return ("a", x > 0, math.floor((y - FORECOURT_Y) / AXIS_BAND_PITCH))


SITE_SHAPES = {}


def granite_field(x, y):
    """Paving field key for the warm grey granite (between the dark bands)."""
    fx, fy = FOUNTAIN
    if math.hypot(x - fx, y - fy) < PLAZA_R:
        return ("p", math.floor(((math.degrees(math.atan2(y - fy, x - fx)) - 11.25) % 360.0) / 22.5))
    if y < ARRIVAL[1]:
        return ("q", math.floor((x - 6.0) / 10.0), math.floor((y - SITE_Y0) / 10.0))
    if y < INNER_Y0:
        return ("r", math.floor((x - GATE_SIDE_X - 1.5) / 12.0), math.floor((y - ARRIVAL[1]) / 12.0))
    if y < fy:
        return ("g",)
    for (hx, hy) in HAETAE_POS:
        if math.hypot(x - hx, y - hy) < 4.3:
            return ("h", hx > 0)
    if y < FORECOURT_Y:
        return ("t",)
    return ("f", math.floor((x - 6.0) / 12.0), math.floor((y - FORECOURT_Y) / 12.0))


def paving_fields(ob, tile, field_of):
    """World-scale UVs with a random quarter turn and offset per paving field, plus a per-field
    tone (vertex colour 'Col', multiplied into the base colour) and a faint large-scale wash."""
    me = ob.data
    uvl = me.uv_layers.active.data
    ca = me.color_attributes.new("Col", "FLOAT_COLOR", "CORNER")
    for p in me.polygons:
        c = p.center
        key = field_of(c.x, c.y)
        h = zlib.crc32(repr(key).encode()) ^ RNG_SEED
        rng = random.Random(h)
        rot = rng.randrange(4)
        ou, ov = rng.random(), rng.random()
        tone = rng.uniform(0.88, 1.0)
        warm = rng.uniform(-0.015, 0.015)
        for li in p.loop_indices:
            co = me.vertices[me.loops[li].vertex_index].co
            lu, lv = co.x / tile, co.y / tile
            for _ in range(rot):
                lu, lv = -lv, lu
            uvl[li].uv = (lu + ou, lv + ov)
            wash = 1.0 + 0.035 * math.sin(co.x * 0.043 + 1.1) * math.sin(co.y * 0.037 + 0.4)
            b = tone * wash
            ca.data[li].color = (b * (1 + warm), b, b * (1 - warm), 1.0)
    me.color_attributes.active_color = ca


def build_slot_drains(coll, rects):
    """Stainless slot drains: two brushed steel strips flush with the paving either side of a
    narrow dark slot, with the slot walls going down into the channel."""
    mb = MB("Drain_Channels")
    for (p0, p1, p2, p3) in rects:
        x0, x1 = p0[0], p2[0]
        y0, y1 = p0[1], p2[1]
        xm = (x0 + x1) / 2
        g = 0.012                      # half slot width
        for (a, b) in ((x0, xm - g), (xm + g, x1)):
            mb.face([(a, y0, Z_PAVE + 0.001), (b, y0, Z_PAVE + 0.001), (b, y1, Z_PAVE + 0.001), (a, y1, Z_PAVE + 0.001)],
                    "Steel_Brushed", want=(0, 0, 1))
        for (xx, wx) in ((xm - g, 1), (xm + g, -1)):
            mb.face([(xx, y0, Z_PAVE + 0.001), (xx, y1, Z_PAVE + 0.001), (xx, y1, -0.06), (xx, y0, -0.06)],
                    "Steel_Brushed", want=(wx, 0, 0))
        mb.face([(xm - g, y0, -0.06), (xm + g, y0, -0.06), (xm + g, y1, -0.06), (xm - g, y1, -0.06)], "Drain_Slot",
                want=(0, 0, 1))
        for (yy, wy) in ((y0, -1), (y1, 1)):
            mb.face([(x0, yy, Z_PAVE + 0.001), (x1, yy, Z_PAVE + 0.001), (x1, yy, -0.06), (x0, yy, -0.06)],
                    "Steel_Brushed", want=(0, wy, 0))
    return mb.finish(coll)


def build_tree_pits(coll):
    """Planting pits in the paving: a dark granite surround course and a soil floor under the
    cast-iron grate (the grate itself is the VegLib_TreeGrate prop)."""
    mb = MB("Tree_Pits")
    for (x, y) in TREE_PITS + ARRIVAL_PITS:
        h = 0.8
        mb.face([(x - h, y - h, -0.07), (x + h, y - h, -0.07), (x + h, y + h, -0.07), (x - h, y + h, -0.07)], "Bed_Mulch",
                want=(0, 0, 1))
        for (ax, ay, bx, by, n) in ((x - h, y - h, x + h, y - h, (0, 1, 0)), (x + h, y - h, x + h, y + h, (-1, 0, 0)),
                                    (x + h, y + h, x - h, y + h, (0, -1, 0)), (x - h, y + h, x - h, y - h, (1, 0, 0))):
            mb.face([(ax, ay, Z_PAVE), (bx, by, Z_PAVE), (bx, by, -0.07), (ax, ay, -0.07)], "Kerb_Granite", want=n)
    return [mb.finish(coll)]


def point_in_poly(x, y, poly):
    inside = False
    n = len(poly)
    j = n - 1
    for i in range(n):
        xi, yi = poly[i]
        xj, yj = poly[j]
        if (yi > y) != (yj > y) and x < (xj - xi) * (y - yi) / ((yj - yi) or 1e-12) + xi:
            inside = not inside
        j = i
    return inside


def is_woodland(x, y):
    """True inside the woodland-floor areas (belts, groves, garden backdrops), before cut-outs."""
    S = SITE_SHAPES
    if y > INNER_Y0 and not point_in_poly(x, y, S["path_outer"][0]):
        return True
    if point_in_poly(x, y, S["path_inner"][0]) and not any(point_in_poly(x, y, p) for p in S["wood_in_cut"]):
        return True
    return any(point_in_poly(x, y, p) for p in S["groves"] + S["arrival_belts"])


def split_runs(loop, flags):
    """Split a closed loop into open runs of consecutive segments whose flag is True."""
    n = len(loop)
    if not any(flags):
        return []
    start = next(i for i in range(n) if not flags[i])
    runs, cur = [], []
    for k in range(1, n + 1):
        i = (start + k) % n
        if flags[i]:
            if not cur:
                cur = [loop[i]]
            cur.append(loop[(i + 1) % n])
        elif cur:
            runs.append(cur)
            cur = []
    if cur:
        runs.append(cur)
    return runs


def sweep_kerb_open(mb, pts, prof, key):
    """Kerb profile swept along an open polyline (surface on the left), with end caps."""
    n = len(pts)
    rings = []
    for (d, z) in prof:
        row = []
        for i in range(n):
            p = Vector(pts[i])
            if i == 0:
                t = (Vector(pts[1]) - p).normalized()
                nrm = Vector((-t.y, t.x))
                k = 1.0
            elif i == n - 1:
                t = (p - Vector(pts[i - 1])).normalized()
                nrm = Vector((-t.y, t.x))
                k = 1.0
            else:
                t1 = (p - Vector(pts[i - 1])).normalized()
                t2 = (Vector(pts[i + 1]) - p).normalized()
                n1, n2 = Vector((-t1.y, t1.x)), Vector((-t2.y, t2.x))
                nrm = (n1 + n2)
                nrm = nrm.normalized() if nrm.length > 1e-6 else n1
                k = 1.0 / max(0.35, nrm.dot(n1))
            row.append(tuple(p + nrm * d * k))
        rings.append(row)
    V = [[mb.bm.verts.new((p[0], p[1], prof[r][1])) for p in rings[r]] for r in range(len(prof))]
    for r in range(len(prof) - 1):
        dz = prof[r + 1][1] - prof[r][1]
        dd = prof[r + 1][0] - prof[r][0]
        for i in range(n - 1):
            f = mb.face(None, key, verts=[V[r][i], V[r][i + 1], V[r + 1][i + 1], V[r + 1][i]])
            f.normal_update()
            t = (Vector(pts[i + 1]) - Vector(pts[i])).normalized()
            left = Vector((-t.y, t.x, 0))
            want = left * (-dz) + Vector((0, 0, dd))
            if f.normal.dot(want) < 0:
                f.normal_flip()
    for (i, sgn) in ((0, -1), (n - 1, 1)):
        cap = [V[r][i] for r in range(len(prof))]
        try:
            f = mb.face(None, key, verts=cap)
            f.normal_update()
            t = (Vector(pts[1]) - Vector(pts[0])) if i == 0 else (Vector(pts[-1]) - Vector(pts[-2]))
            if f.normal.dot(Vector((t.x, t.y, 0)) * sgn) < 0:
                f.normal_flip()
        except ValueError:
            pass


def on_site_edge(loop):
    return any(abs(p[0] - SITE_X0) < 0.1 or abs(p[0] - SITE_X1) < 0.1 or abs(p[1] - SITE_Y0) < 0.1 or abs(p[1] - SITE_Y1) < 0.1
               for p in loop)


def mesh_from_bm(bm, name):
    me = tag(bpy.data.meshes.new("TMP_" + name))
    for f in list(bm.faces):
        f.normal_update()
    bad = [f for f in bm.faces if f.normal.z < 0.5]
    bmesh.ops.delete(bm, geom=bad, context="FACES")
    bm.to_mesh(me)
    bm.free()
    ob = bpy.data.objects.new("TMP_" + name, me)
    tmp_coll().objects.link(ob)
    return ob


def solidify_from_objects(name, objs, z0=-2.0, z1=2.0):
    """Closed solid (extruded) copy of flat surface objects, for use as a boolean cutter."""
    bm = bmesh.new()
    for ob in objs:
        bm.from_mesh(ob.data)
    for v in bm.verts:
        v.co.z = z1
    bmesh.ops.remove_doubles(bm, verts=bm.verts[:], dist=1e-4)
    ext = bmesh.ops.extrude_face_region(bm, geom=bm.faces[:])
    for e in ext["geom"]:
        if isinstance(e, bmesh.types.BMVert):
            e.co.z = z0
    bmesh.ops.recalc_face_normals(bm, faces=bm.faces[:])
    me = tag(bpy.data.meshes.new("TMP_" + name))
    bm.to_mesh(me)
    bm.free()
    ob = bpy.data.objects.new("TMP_" + name, me)
    tmp_coll().objects.link(ob)
    return ob


# ---------------------------------------------------------------------------
# Water, walls, plinths and garden structures (properly modelled stonework only)
# ---------------------------------------------------------------------------
def build_fountain(coll):
    """Architectural basin at the foot of the reflecting pool: a chamfered step all round, a
    basin wall with an overhanging moulded coping, a dark lining and a low central drum that
    carries the main jet. No figurative centrepiece. Jets are Fountain_Jet_* empties."""
    fx, fy = FOUNTAIN
    R, F = FOUNTAIN_R, FOUNTAIN_FOOT_R
    prof = [(F, -0.05), (F, 0.13), (F - 0.02, 0.15), (R + 0.06, 0.15),
            (R, 0.15), (R, 0.45), (R + 0.04, 0.45), (R + 0.04, 0.53), (R + 0.02, 0.55), (R - 0.56, 0.55),
            (R - 0.585, 0.54), (R - 0.6, 0.515), (R - 0.6, 0.33), (R - 0.6, 0.0), (2.6, 0.0),
            (2.6, 0.47), (2.64, 0.47), (2.64, 0.6), (2.62, 0.62), (2.06, 0.62), (2.02, 0.6), (2.0, 0.57), (2.0, 0.5),
            (0.0, 0.5)]
    # inner step (a ledge just under the water) between the basin wall and the floor
    prof = prof[:13] + [(R - 0.6, 0.18), (R - 1.15, 0.18), (R - 1.15, 0.0)] + prof[14:]
    keys = ["Stone_Dressed"] * 12 + ["Pool_Lining"] * 4 + ["Stone_Dressed"] * 9
    mb = MB("Fountain_Basin")
    mb.lathe(prof, 160, keys, centre=(fx, fy), uv=("cyl", 2.4, True))
    basin = mb.finish(coll, smooth_angle=32.0)
    # bronze nozzle ring standing just proud of the water, and the crown nozzle on the drum
    nz = MB("Fountain_Nozzles")
    for k in range(16):
        a = 2 * math.pi * k / 16
        cx_, cy_ = fx + math.cos(a) * 6.3, fy + math.sin(a) * 6.3
        nz.lathe([(0.13, 0.0), (0.13, 0.04), (0.06, 0.08), (0.05, Z_WATER + 0.06), (0.035, Z_WATER + 0.08),
                  (0.0, Z_WATER + 0.08)], 16, ["Bronze_Nozzle"] * 5, centre=(cx_, cy_))
    nz.lathe([(0.32, 0.6), (0.3, 0.66), (0.12, 0.72), (0.09, 0.8), (0.0, 0.8)], 24, ["Bronze_Nozzle"] * 4, centre=(fx, fy))
    nozzles = nz.finish(coll, smooth_angle=40.0)
    wm = MB("Water_04")
    wm.lathe([(R - 0.6, Z_WATER), (2.6, Z_WATER)], 160, ["Water"], centre=(fx, fy))
    water = wm.finish(coll)
    jets = []
    for k in range(16):
        a = 2 * math.pi * k / 16
        jets.append(((fx + math.cos(a) * 6.3, fy + math.sin(a) * 6.3, Z_WATER), 2.2))
    jets.append(((fx, fy, 0.8), 6.0))
    out = [basin, nozzles, water]
    for i, (p, hgt) in enumerate(jets):
        e = bpy.data.objects.new("Fountain_Jet_%02d" % (i + 1), None)
        e.empty_display_type = "SINGLE_ARROW"
        e.empty_display_size = 0.5
        e.location = p
        e["jet_height_m"] = hgt
        coll.objects.link(e)
        out.append(e)
    for k in range(28):
        a = 2 * math.pi * k / 28
        CIRCLES.append(("fountain-rim-%02d" % (k + 1), fx + math.cos(a) * (R - 0.25), fy + math.sin(a) * (R - 0.25), 1.2))
        TOPY["fountain-rim-%02d" % (k + 1)] = 0.55
    CIRCLES.append(("fountain-drum", fx, fy, 2.65))
    TOPY["fountain-drum"] = 0.8
    h_ = (R - 0.6) / math.sqrt(2.0)
    BOXES.append(("water-fountain", fx - h_, fx + h_, fy - h_, fy + h_))
    TOPY["water-fountain"] = Z_WATER
    return out


def build_pools(coll):
    """Long shallow reflecting pool in three basins (paved crossings between them): moulded
    dressed-stone coping 0.45 m above the walks, dark granite lining, water at Z_WATER."""
    cop = MB("Pool_Coping")
    lin = MB("Pool_Lining")
    prof_c = [(0.04, -0.05), (0.04, 0.33), (0.0, 0.33), (0.0, 0.42), (0.02, 0.45), (0.56, 0.45), (0.58, 0.443),
              (0.595, 0.428), (0.6, 0.40), (0.6, 0.33)]
    out = []
    for i, (y0, y1) in enumerate(POOL_SEGS):
        x0, x1 = -POOL_HW - POOL_COPING, POOL_HW + POOL_COPING
        loop = [(x0, y0), (x1, y0), (x1, y1), (x0, y1)]
        sweep_kerb(cop, loop, prof_c, "Stone_Dressed")
        sweep_kerb(lin, loop, [(0.6, 0.33), (0.6, -0.15)], "Pool_Lining")
        inner = offset_loop(loop, POOL_COPING)
        lin.face([(p[0], p[1], -0.15) for p in inner], "Pool_Lining", want=(0, 0, 1))
        w = MB("Water_%02d" % (i + 1))
        w.face([(p[0], p[1], Z_WATER) for p in inner], "Water", want=(0, 0, 1))
        out.append(w.finish(coll))
        c = POOL_COPING
        for (nm, a0, a1, b0, b1) in (("s", x0, x1, y0, y0 + c), ("n", x0, x1, y1 - c, y1), ("w", x0, x0 + c, y0 + c, y1 - c),
                                     ("e", x1 - c, x1, y0 + c, y1 - c)):
            BOXES.append(("pool-%d-coping-%s" % (i + 1, nm), a0, a1, b0, b1))
            TOPY["pool-%d-coping-%s" % (i + 1, nm)] = 0.45
        BOXES.append(("water-pool-%d" % (i + 1), x0 + c, x1 - c, y0 + c, y1 - c))
        TOPY["water-pool-%d" % (i + 1)] = Z_WATER
    out += [cop.finish(coll, smooth_angle=35.0), lin.finish(coll)]
    return out


def build_walls(coll):
    """Restrained dressed-stone boundary wall either side of the gate: chamfered plinth course,
    ashlar body, overhanging coping with a weathered top, piers with caps every 12 m."""
    mb = MB("Boundary_Wall")
    yc, t = GATE_Y, WALL_T
    for (x0, x1) in SITE_SHAPES["walls"]:
        mb.box("Stone_Dressed", x0, x1, yc - t / 2 - 0.1, yc + t / 2 + 0.1, Z_ARRIVAL_G - 0.1, 0.42, bevel=0.03)
        mb.box("Wall_Ashlar", x0, x1, yc - t / 2, yc + t / 2, 0.42, WALL_H - 0.24, skip=("-z", "+z"))
        mb.box("Stone_Dressed", x0, x1, yc - t / 2 - 0.08, yc + t / 2 + 0.08, WALL_H - 0.24, WALL_H - 0.1, bevel=0.02)
        mb.box("Stone_Dressed", x0, x1, yc - t / 2 + 0.04, yc + t / 2 - 0.04, WALL_H - 0.1, WALL_H, skip=("-z",), bevel=0.03)
        n = max(1, int(round(abs(x1 - x0) / 12.0)))
        for k in range(n + 1):
            x = x0 + (x1 - x0) * k / n
            x = min(max(x, min(x0, x1) + 0.7), max(x0, x1) - 0.7)
            mb.box("Stone_Dressed", x - 0.7, x + 0.7, yc - 0.7, yc + 0.7, Z_ARRIVAL_G - 0.1, 0.5, bevel=0.03)
            mb.box("Wall_Ashlar", x - 0.62, x + 0.62, yc - 0.62, yc + 0.62, 0.5, WALL_H + 0.2, skip=("-z", "+z"))
            mb.box("Stone_Dressed", x - 0.74, x + 0.74, yc - 0.74, yc + 0.74, WALL_H + 0.2, WALL_H + 0.36, bevel=0.025)
            mb.box("Stone_Dressed", x - 0.6, x + 0.6, yc - 0.6, yc + 0.6, WALL_H + 0.36, WALL_H + 0.46, skip=("-z",),
                   bevel=0.03)
        BOXES.append(("wall-%d" % (len(BOXES) + 1), min(x0, x1), max(x0, x1), yc - t / 2 - 0.1, yc + t / 2 + 0.1))
    return [mb.finish(coll)]


def build_bollards(coll):
    """Dressed-granite bollards: a threshold row across the front of the arrival forecourt (the
    three approach lines left open) - chamfered base, square shaft, pyramidal cap."""
    mb = MB("Bollards")
    K = "Stone_Dressed"
    y = ARRIVAL[1] + 1.4
    x = -ARRIVAL[2] + 2.0
    pits = ARRIVAL_PITS
    while x < ARRIVAL[2] - 1.9:
        free = abs(x) > 3.8 and abs(abs(x) - GATE_SIDE_X) > 3.0 and all(math.hypot(x - px, y - py) > 1.6 for (px, py) in pits)
        if free:
            mb.box(K, x - 0.21, x + 0.21, y - 0.21, y + 0.21, Z_PAVE - 0.02, Z_PAVE + 0.08, skip=("-z",), bevel=0.015)
            mb.box(K, x - 0.16, x + 0.16, y - 0.16, y + 0.16, Z_PAVE + 0.08, Z_PAVE + 0.74, skip=("-z", "+z"), bevel=0.012)
            P_ = [[[(x + sx * hw, y + sy * hw, z) for (z, hw) in ((Z_PAVE + 0.74, 0.18), (Z_PAVE + 0.86, 0.06))]
                   for sy in (-1, 1)] for sx in (-1, 1)]
            mb.hexa(P_, K, bevel=0.008)
            CIRCLES.append(("bollard-%d" % (len(CIRCLES) + 1), x, y, 0.25))
            TOPY[CIRCLES[-1][0]] = Z_ARRIVAL_G + 0.86
        x += 2.4
    return [mb.finish(coll)]


def dressed_plinth(mb, x, y, w, d, top, z0=Z_PAVE):
    """Dressed granite plinth: base course, moulded (two chamfered) base, die, cap - bevelled."""
    hw, hd = w / 2, d / 2
    for (e, z_a, z_b, bev, skip) in ((0.35, z0 - 0.05, z0 + 0.28, 0.03, ()), (0.2, z0 + 0.28, z0 + 0.4, 0.04, ("-z",)),
                                     (0.06, z0 + 0.4, top - 0.24, 0.015, ("-z",)), (0.18, top - 0.24, top - 0.09, 0.035, ("-z",)),
                                     (0.1, top - 0.09, top, 0.03, ("-z",))):
        mb.box("Stone_Dressed", x - hw - e, x + hw + e, y - hd - e, y + hd + e, z_a, z_b, skip=skip, bevel=bev)
    return (x - hw - 0.35, x + hw + 0.35, y - hd - 0.35, y + hd + 0.35)


def low_foundation(mb, x, y, w, d, h=0.36, z0=Z_PAVE + 0.01):
    """Two-course dressed-stone foundation for a heritage piece standing in the gravel court."""
    mb.box("Stone_Dressed", x - w / 2 - 0.5, x + w / 2 + 0.5, y - d / 2 - 0.5, y + d / 2 + 0.5, z0 - 0.06, z0 + h * 0.5,
           bevel=0.03)
    mb.box("Stone_Dressed", x - w / 2 - 0.2, x + w / 2 + 0.2, y - d / 2 - 0.2, y + d / 2 + 0.2, z0 + h * 0.5, z0 + h,
           skip=("-z",), bevel=0.03)
    return (x - w / 2 - 0.5, x + w / 2 + 0.5, y - d / 2 - 0.5, y + d / 2 + 0.5)


HERITAGE_DIR = os.path.join(os.path.dirname(OUTPUT_DIR), "haetae")
GATE_DIR = os.path.join(os.path.dirname(OUTPUT_DIR), "gwanghwamun")
COLL_HERITAGE = "NA_Heritage"
COLL_GATE = "NA_Gate"
# slot -> file, node name, position, yaw (radians, 0 = the piece's front toward -Y), stand kind
HERITAGE_SLOTS = {
    # the pair faces each other across the approach, as authored (A looks toward -X, B toward +X);
    # both carry their own two-tier pedestals, so they stand straight on the paving
    "haetae_a": dict(file="haetae_a.glb", node="Heritage_Haetae_A", pos=HAETAE_POS[1], yaw=0.0, stand="none"),
    "haetae_b": dict(file="haetae_b.glb", node="Heritage_Haetae_B", pos=HAETAE_POS[0], yaw=0.0, stand="none"),
    # Wonwonsa twin pagodas (Treasure No. 1429): the east one includes a 0.31 m ground slab, the west
    # one gets a matching dressed-stone slab of the same size so the pair reads symmetrical
    "pagoda_w": dict(file="pagoda_wonwonsa_west.glb", node="Heritage_Pagoda_West",
                     pos=(TRAD["cx"] + 5.0, TRAD["cy"] - 4.8), yaw=0.0, stand="slab"),
    "pagoda_e": dict(file="pagoda_wonwonsa_east.glb", node="Heritage_Pagoda_East",
                     pos=(TRAD["cx"] + 5.0, TRAD["cy"] + 4.8), yaw=0.0, stand="none"),
    "lantern": dict(file="lantern_wonwonsa.glb", node="Heritage_Lantern_Wonwonsa",
                    pos=(TRAD["cx"] - 2.0, TRAD["cy"]), yaw=0.0, stand="none"),
    "sundial": dict(file="sundial.glb", node="Heritage_Sundial",
                    pos=(CONT["cx"] - CONT["hx"] + 6.0, CONT["cy"]), yaw=0.0, stand="pedestal"),
}
HERITAGE_DEFAULT_FOOT = {"haetae": 1.8, "pagoda": 3.2, "lantern": 1.2, "sundial": 0.9, "animal": 1.0}


def heritage_facts():
    """Facts per piece file: heritage.json (supersedes haetae.json) when present, otherwise the
    exporter's per-file facts_<name>.json (sizeM = x, height, z in glTF axes, lowestY, facing)."""
    out = {}
    for nm in ("heritage.json", "haetae.json"):
        p = os.path.join(HERITAGE_DIR, nm)
        if os.path.isfile(p):
            with open(p, encoding="utf-8") as f:
                d = json.load(f)
            items = (d.get("items") or d.get("pieces") or d) if isinstance(d, dict) else d
            if isinstance(items, dict):
                for k, v in items.items():
                    if isinstance(v, dict):
                        out[os.path.basename(v.get("file", k if k.endswith(".glb") else k + ".glb"))] = v
            elif isinstance(items, list):
                for v in items:
                    if isinstance(v, dict) and v.get("file"):
                        out[os.path.basename(v["file"])] = v
            break
    for d in HERITAGE_SLOTS.values():
        fn = d["file"]
        p = os.path.join(HERITAGE_DIR, "facts_" + os.path.splitext(fn)[0] + ".json")
        if fn not in out and os.path.isfile(p):
            with open(p, encoding="utf-8") as f:
                out[fn] = json.load(f)
    return out


def piece_footprint(slot, facts):
    f = facts.get(HERITAGE_SLOTS[slot]["file"], {})
    sz = f.get("sizeM")
    if isinstance(sz, (list, tuple)) and len(sz) >= 3:
        return float(sz[0]), float(sz[2])
    fp = f.get("footprint") or f.get("footprintM")
    if isinstance(fp, (list, tuple)) and len(fp) >= 2:
        return float(fp[0]), float(fp[1])
    if isinstance(fp, dict) and "widthX" in fp:
        return float(fp["widthX"]), float(fp.get("depthZ", fp["widthX"]))
    for k, v in HERITAGE_DEFAULT_FOOT.items():
        if k in slot:
            return v, v
    return 1.5, 1.5


def piece_has_base(slot, facts):
    f = facts.get(HERITAGE_SLOTS[slot]["file"], {})
    for k in ("includes_base", "base_included", "includesPedestal", "has_pedestal", "pedestal", "base"):
        if k in f:
            return bool(f[k])
    return False


HERITAGE_TOPS = {}      # slot -> z where the piece stands


def build_heritage_bases(coll):
    """Plinths, foundations and the traditional-garden stonework that carry the heritage pieces.
    Built whether or not the pieces have arrived (their places are prepared)."""
    facts = heritage_facts()
    mb = MB("Heritage_Plinths")
    ew, ed = piece_footprint("pagoda_e", facts)
    for slot, d in HERITAGE_SLOTS.items():
        x, y = d["pos"]
        w, dd = piece_footprint(slot, facts)
        if abs(math.sin(d["yaw"])) > 0.7:
            w, dd = dd, w
        if not os.path.isfile(os.path.join(HERITAGE_DIR, d["file"])) and d["stand"] != "slab":
            HERITAGE_TOPS[slot] = Z_PAVE
            continue
        base_z = Z_PAVE + (0.01 if slot.startswith(("pagoda", "lantern")) else 0.0)
        if d["stand"] == "none":
            HERITAGE_TOPS[slot] = base_z
            bx = (x - w / 2, x + w / 2, y - dd / 2, y + dd / 2)
        elif d["stand"] == "slab":
            mb.box("Stone_Dressed", x - ew / 2, x + ew / 2, y - ed / 2, y + ed / 2, base_z - 0.05, base_z + 0.31, bevel=0.02)
            HERITAGE_TOPS[slot] = base_z + 0.31
            bx = (x - ew / 2, x + ew / 2, y - ed / 2, y + ed / 2)
        else:   # waist-high pedestal with a top just larger than the instrument
            t = max(w, dd) + 0.1
            mb.box("Stone_Dressed", x - 0.3, x + 0.3, y - 0.3, y + 0.3, Z_PAVE - 0.02, Z_PAVE + 0.12, skip=("-z",), bevel=0.015)
            mb.box("Stone_Dressed", x - 0.2, x + 0.2, y - 0.2, y + 0.2, Z_PAVE + 0.12, 0.84, skip=("-z",), bevel=0.012)
            mb.box("Stone_Dressed", x - t / 2, x + t / 2, y - t / 2, y + t / 2, 0.84, 0.92, skip=("-z",), bevel=0.012)
            HERITAGE_TOPS[slot] = 0.92
            bx = (x - 0.3, x + 0.3, y - 0.3, y + 0.3)
        BOXES.append(("plinth-" + slot.replace("_", "-"), bx[0], bx[1], bx[2], bx[3]))
        if d["stand"] in ("slab", "pedestal"):
            TOPY["plinth-" + slot.replace("_", "-")] = HERITAGE_TOPS[slot]
    objs = [mb.finish(coll)]
    # traditional garden: low dressed-stone retaining wall behind the court (pagodas read against
    # the dark pine backdrop planted behind it)
    t = TRAD
    rw = MB("Garden_Retaining_Wall")
    x0 = t["cx"] + t["hx"] + 0.05
    y0, y1 = t["cy"] - t["hy"] - 0.6, t["cy"] + t["hy"] + 0.6
    rw.box("Stone_Dressed", x0, x0 + 0.85, y0, y1, -0.05, 0.25, bevel=0.025)
    rw.box("Wall_Ashlar", x0 + 0.05, x0 + 0.75, y0 + 0.05, y1 - 0.05, 0.25, 0.68, skip=("-z", "+z"))
    rw.box("Stone_Dressed", x0 - 0.04, x0 + 0.84, y0 - 0.04, y1 + 0.04, 0.68, 0.84, bevel=0.025)
    BOXES.append(("garden-wall", x0 - 0.04, x0 + 0.85, y0 - 0.04, y1 + 0.04))
    TOPY["garden-wall"] = 0.84
    objs.append(rw.finish(coll))
    return objs


def import_glb_as(path, name, coll):
    """Import a glTF into `coll` under one parent empty named `name`; returns the empty."""
    before = set(bpy.data.objects)
    bpy.ops.import_scene.gltf(filepath=path)
    new = [o for o in bpy.data.objects if o not in before]
    root = bpy.data.objects.new(name, None)
    coll.objects.link(root)
    for o in new:
        for c in list(o.users_collection):
            c.objects.unlink(o)
        coll.objects.link(o)
        if o.parent is None:
            o.parent = root
    return root, new


def place_heritage():
    """Import the heritage pieces that have arrived and stand them on their prepared bases."""
    facts = heritage_facts()
    c = bpy.data.collections.get(COLL_HERITAGE)
    if c:
        remove_collection(c)
    c = tag(bpy.data.collections.new(COLL_HERITAGE))
    bpy.context.scene.collection.children.link(c)
    placed, pending = [], []
    for slot, d in HERITAGE_SLOTS.items():
        p = os.path.join(HERITAGE_DIR, d["file"])
        if not os.path.isfile(p):
            pending.append(d["node"])
            continue
        root, objs = import_glb_as(p, d["node"], c)
        bpy.context.view_layer.update()
        pts = [o.matrix_world @ Vector(v) for o in objs if o.type == "MESH" for v in o.bound_box]
        if not pts:
            pending.append(d["node"])
            continue
        mn = Vector((min(q.x for q in pts), min(q.y for q in pts), min(q.z for q in pts)))
        mx = Vector((max(q.x for q in pts), max(q.y for q in pts), max(q.z for q in pts)))
        off = Vector(((mn.x + mx.x) / 2, (mn.y + mx.y) / 2, mn.z))
        for o in objs:
            if o.parent is root:
                o.location -= off
        x, y = d["pos"]
        root.location = (x, y, HERITAGE_TOPS.get(slot, Z_PAVE))
        root.rotation_euler = (0.0, 0.0, d["yaw"] + float(facts.get(d["file"], {}).get("yaw_fix_rad", 0.0)))
        r = 0.5 * math.hypot(mx.x - mn.x, mx.y - mn.y)
        CIRCLES.append((d["node"].lower().replace("_", "-"), x, y, round(min(r, 2.5), 2)))
        placed.append(d["node"])
    RESULTS["heritage"] = {"placed": placed, "pending": pending}
    log("heritage placed:", placed, "pending:", pending)


def gate_heightfield():
    """(sampler, info) for the gate's doors-open walking grid: sampler(local_x, local_z) -> local y."""
    gc = os.path.join(GATE_DIR, "gate-colliders.json")
    if not os.path.isfile(gc):
        return None, None
    with open(gc, encoding="utf-8") as f:
        g = json.load(f)
    hs = [h for h in g.get("heightfields", []) if h.get("variant") == "doors-open"]
    if not hs:
        return None, None
    h = hs[0]
    p = os.path.join(GATE_DIR, h["file"])
    if not os.path.isfile(p):
        return None, None
    with open(p, "rb") as f:
        raw = f.read()
    cols, rows = h["cols"], h["rows"]
    vals = struct.unpack("<%dH" % (cols * rows), raw)
    lo, hi = h["minY"], h["maxY"]

    def at(lx, lz):
        c = int((lx - h["originX"]) / h["cellM"])
        r = int((lz - h["originZ"]) / h["cellM"])
        if not (0 <= c < cols and 0 <= r < rows):
            return None
        v = vals[r * cols + c]
        return None if v == 65535 else lo + v / 65534.0 * (hi - lo)
    return at, h


def build_gate_fill(coll):
    """Ground where the gate pack has none inside its footprint (the front corners beyond its curved
    road): granite paving at the height of the gate's own walking grid, so there is no hole and no
    step. Cells are found by casting rays down at the pack's ground pieces."""
    from mathutils.bvhtree import BVHTree
    gcol = bpy.data.collections.get(COLL_GATE)
    if not gcol:
        return []
    keys = ("Ground", "Road", "Grass", "Stereobate", "Woldae", "Stairs", "Cornerstone", "Balustrade", "Gwanghwamun")
    obs = [o for o in gcol.all_objects if o.type == "MESH" and any(k in o.name for k in keys) and "Doors" not in o.name]
    if not obs:
        return []
    dg = bpy.context.evaluated_depsgraph_get()
    trees = [BVHTree.FromObject(o, dg) for o in obs]
    mws = [(o.matrix_world.copy(), o.matrix_world.inverted()) for o in obs]
    at, info = gate_heightfield()
    cell = 0.5
    y_lo, y_hi = GATE_Y - PACK_FRONT, GATE_Y - 0.5
    nx = int(round(2 * PACK_HX / cell))
    ny = int(round((y_hi - y_lo) / cell))
    mb = MB("Gate_Forecourt_Fill")
    V = {}

    def vert(i, j, z):
        k = (i, j)
        if k not in V:
            V[k] = mb.bm.verts.new((-PACK_HX + i * cell, y_lo + j * cell, z))
        return V[k]

    def covered(x, y):
        for t, (mw, mwi) in zip(trees, mws):
            o = mwi @ Vector((x, y, 60.0))
            d = (mwi.to_3x3() @ Vector((0.0, 0.0, -1.0))).normalized()
            if t.ray_cast(o, d)[0] is not None:
                return True
        return False

    n = 0
    nb = 0
    q = 0.5 * cell - 0.02
    for i in range(nx):
        x = -PACK_HX + (i + 0.5) * cell
        for j in range(ny):
            y = y_lo + (j + 0.5) * cell
            # centre and four corners: a cell the pack's ground only partly covers (along its curved
            # road edge) is filled too, 2 cm lower so it tucks under the pack's surface - no gaps
            hits = sum(covered(x + dx, y + dy) for (dx, dy) in ((0, 0), (-q, -q), (q, -q), (q, q), (-q, q)))
            if hits == 5:
                continue
            ly = at(x, GATE_Y - y) if at else None
            drop = 0.005 if hits == 0 else 0.02
            nb += hits > 0
            z = (Z_ARRIVAL + ly - drop) if ly is not None else Z_ARRIVAL_G
            f = mb.face(None, "Paving_Granite", want=(0, 0, 1),
                        verts=[vert(i, j, z), vert(i + 1, j, z), vert(i + 1, j + 1, z), vert(i, j + 1, z)])
            n += 1
    if not n:
        mb.bm.free()
        return []
    ob = mb.finish(coll)
    paving_fields(ob, TILE["Paving_Granite"], granite_field)
    log("gate forecourt fill: %d cells (%d along the pack's edge)" % (n, nb))
    return [ob]


def place_gate():
    """Import the Gwanghwamun gate model at its placement (never exported by this script), or a
    clearly labelled placeholder volume when the files have not arrived yet."""
    c = bpy.data.collections.get(COLL_GATE)
    if c:
        remove_collection(c)
    c = tag(bpy.data.collections.new(COLL_GATE))
    bpy.context.scene.collection.children.link(c)
    files = [os.path.join(GATE_DIR, n) for n in ("scenery-gate-1.glb", "scenery-gate-2.glb")]
    if all(os.path.isfile(p) for p in files):
        for i, p in enumerate(files):
            root, objs = import_glb_as(p, "Gate_Import_%d" % (i + 1), c)
            root.location = (0.0, GATE_Y, Z_ARRIVAL)
        RESULTS["gate"] = "imported"
        return
    m = new_material("Placeholder_Marker")
    b = bsdf_of(m)
    sock(b, "Base Color").default_value = (0.9, 0.35, 0.1, 1.0)
    sock(b, "Alpha").default_value = 0.35
    try:
        m.surface_render_method = "BLENDED"
    except (AttributeError, TypeError):
        pass
    MATS["Placeholder_Marker"] = m
    mb = MB("Gate_Placeholder")
    mb.box("Placeholder_Marker", -GATE_HALF_W, GATE_HALF_W, GATE_Y - GATE_BACK, GATE_Y + GATE_BACK, 0.0, 19.5)
    mb.box("Placeholder_Marker", -15.0, 15.0, GATE_Y - GATE_FRONT, GATE_Y - GATE_BACK, 0.0, 1.0)
    mb.finish(c)
    cu = bpy.data.curves.new("Gate_Placeholder_Label", "FONT")
    cu.body = "PLACEHOLDER - Gwanghwamun gate (files pending)"
    cu.size = 2.2
    cu.align_x = "CENTER"
    lab = bpy.data.objects.new("Gate_Placeholder_Label", cu)
    lab.location = (0.0, GATE_Y - GATE_BACK - 0.3, 21.0)
    lab.rotation_euler = (math.radians(90), 0.0, 0.0)
    lab.data.materials.append(m)
    c.objects.link(lab)
    RESULTS["gate"] = "placeholder"


