def leafy(mat):
    """Foliage card material: leaf/twig/needle in the name or an alpha/opacity texture."""
    if mat is None:
        return False
    n = mat.name.lower()
    if any(k in n for k in ("twig", "leaves", "leaf", "needle")):
        return True
    if mat.node_tree:
        for nd in mat.node_tree.nodes:
            if nd.type == "TEX_IMAGE" and nd.image:
                inm = nd.image.name.lower()
                if "alpha" in inm or "opacity" in inm:
                    return True
    return False


def check_mesh(me, what):
    me.validate(verbose=False)
    if len(me.vertices) == 0 or len(me.polygons) == 0:
        raise RuntimeError("%s: empty or invalid mesh (%d verts, %d faces)" % (what, len(me.vertices), len(me.polygons)))


def safe_evaluated_mesh(ob, what):
    """Mesh with modifiers applied, evaluated through an up-to-date depsgraph."""
    bpy.context.view_layer.update()
    dg = bpy.context.evaluated_depsgraph_get()
    dg.update()
    oe = ob.evaluated_get(dg)
    me = bpy.data.meshes.new_from_object(oe, preserve_all_data_layers=True, depsgraph=dg)
    check_mesh(me, what)
    return me


def fix_tree_material(m):
    """Rebuild a Poly Haven plant material as a plain glTF-readable Principled BSDF:
    base colour, roughness, normal (+ alpha clip through Math:Round for foliage).
    Keeps the UV mapping (scale/rotation) of the main diffuse texture."""
    if m is None or m.get("na_simplified"):
        return
    foliage = leafy(m)
    nt = m.node_tree
    imgs = [n for n in nt.nodes if n.type == "TEX_IMAGE" and n.image]
    if not imgs:
        return                      # our own flat materials (hedge core, cast iron) stay as they are
    key = m.name.split("_tree_")[-1] if "_tree_" in m.name else m.name
    key = key.replace("tree_small_02_", "")

    def pick(*kinds):
        cands = [n for n in imgs if any(k in n.image.name.lower() for k in kinds)]
        pref = [n for n in cands if key.lower() in n.image.name.lower()]
        return (pref or cands or [None])[0]

    d, r, nn, a = pick("diff"), pick("rough"), pick("nor_gl", "nor"), pick("alpha", "opacity")
    loc, rot, scl = (0, 0, 0), (0, 0, 0), (1, 1, 1)
    if d is not None and d.inputs["Vector"].links:
        mp = d.inputs["Vector"].links[0].from_node
        while mp.type == "REROUTE" and mp.inputs[0].links:
            mp = mp.inputs[0].links[0].from_node
        if mp.type == "MAPPING":
            loc = tuple(sock(mp, "Location").default_value)
            rot = tuple(sock(mp, "Rotation").default_value)
            scl = tuple(sock(mp, "Scale").default_value)
    keep_imgs = {"d": d.image if d else None, "r": r.image if r else None, "n": nn.image if nn else None,
                 "a": a.image if a else None}
    for n in list(nt.nodes):
        nt.nodes.remove(n)
    out = nt.nodes.new("ShaderNodeOutputMaterial")
    b = nt.nodes.new("ShaderNodeBsdfPrincipled")
    nt.links.new(sock(b, "BSDF", True), out.inputs["Surface"])
    uvn = nt.nodes.new("ShaderNodeUVMap")
    uvn.uv_map = "UVMap"
    vec = sock(uvn, "UV", True)
    if any(abs(x - 1) > 1e-4 for x in scl) or any(abs(x) > 1e-4 for x in loc + rot):
        mp = nt.nodes.new("ShaderNodeMapping")
        sock(mp, "Location").default_value = loc
        sock(mp, "Rotation").default_value = rot
        sock(mp, "Scale").default_value = scl
        nt.links.new(vec, sock(mp, "Vector"))
        vec = sock(mp, "Vector", True)

    def img_node(img, non_color):
        t = nt.nodes.new("ShaderNodeTexImage")
        t.image = img
        img.colorspace_settings.name = "Non-Color" if non_color else "sRGB"
        nt.links.new(vec, sock(t, "Vector"))
        return t

    if keep_imgs["d"]:
        nt.links.new(sock(img_node(keep_imgs["d"], False), "Color", True), sock(b, "Base Color"))
    if keep_imgs["r"]:
        nt.links.new(sock(img_node(keep_imgs["r"], True), "Color", True), sock(b, "Roughness"))
    else:
        sock(b, "Roughness").default_value = 0.8
    if keep_imgs["n"]:
        nm = nt.nodes.new("ShaderNodeNormalMap")
        nt.links.new(sock(img_node(keep_imgs["n"], True), "Color", True), sock(nm, "Color"))
        nt.links.new(sock(nm, "Normal", True), sock(b, "Normal"))
    sock(b, "Specular IOR Level").default_value = 0.3
    if foliage and keep_imgs["a"]:
        rnd = nt.nodes.new("ShaderNodeMath")
        rnd.operation = "ROUND"
        nt.links.new(sock(img_node(keep_imgs["a"], True), "Color", True), rnd.inputs[0])
        nt.links.new(rnd.outputs[0], sock(b, "Alpha"))
        m.use_backface_culling = False
        try:
            m.surface_render_method = "DITHERED"
        except (AttributeError, TypeError):
            pass
    else:
        m.use_backface_culling = True
    m["na_simplified"] = 1
    tag(m)


def clean_prop_material(m):
    """Manufactured-object materials keep their Poly Haven node setup (glTF readable); drop
    displacement only."""
    if m is None or m.get("na_simplified"):
        return
    for n in list(m.node_tree.nodes):
        if n.type == "DISPLACEMENT":
            m.node_tree.nodes.remove(n)
    m["na_simplified"] = 1
    tag(m)


def fix_tree_mesh(me, prop=False):
    for m in me.materials:
        if prop:
            clean_prop_material(m)
        else:
            fix_tree_material(m)
    for uv in [u for u in me.uv_layers if u.name != "UVMap"]:
        me.uv_layers.remove(uv)
    for ca in list(me.color_attributes):
        me.color_attributes.remove(ca)


def veglib_path(name):
    return os.path.join(PREPARED_DIR, "VegLib_%s.blend" % name)


def append_objects(asset, onames):
    path = os.path.join(MODELS_SRC, asset, asset + "_2k.blend")
    with bpy.data.libraries.load(path, link=False) as (src, dst):
        missing = [o for o in onames if o not in src.objects]
        if missing:
            raise RuntimeError("%s not in %s" % (missing, path))
        dst.objects = list(onames)
    for ob in dst.objects:
        if ob is None:
            raise RuntimeError("could not append from %s" % path)
    return list(dst.objects)


def append_mesh_copies(asset, onames):
    """Append objects from a Poly Haven .blend in one go (shared materials) and return mesh copies
    (raw mesh data, no modifiers - avoids evaluating heavy geometry-node setups)."""
    out = []
    for ob in append_objects(asset, onames):
        if ob.type != "MESH":
            raise RuntimeError("%s is not a mesh" % ob.name)
        me = ob.data.copy()
        src_mesh = ob.data
        bpy.data.objects.remove(ob, do_unlink=True)
        if src_mesh.users == 0:
            bpy.data.meshes.remove(src_mesh)
        check_mesh(me, asset)
        out.append(me)
    return out


def mesh_islands(bm, allowed):
    """Connected face islands restricted to faces whose material index is in `allowed`."""
    bm.faces.ensure_lookup_table()
    seen = bytearray(len(bm.faces))
    islands = []
    for f in bm.faces:
        if seen[f.index] or f.material_index not in allowed:
            continue
        stack, isl = [f], []
        seen[f.index] = 1
        while stack:
            g = stack.pop()
            isl.append(g)
            for v in g.verts:
                for h in v.link_faces:
                    if not seen[h.index] and h.material_index in allowed:
                        seen[h.index] = 1
                        stack.append(h)
        islands.append(isl)
    return islands


def decimated_copy(me, ratio, what):
    po = bpy.data.objects.new("TMP_dec", me.copy())
    tmp_coll().objects.link(po)
    md = po.modifiers.new("dec", "DECIMATE")
    md.ratio = max(0.01, min(1.0, ratio))
    md.use_collapse_triangulate = True
    em = safe_evaluated_mesh(po, what)
    src = po.data
    bpy.data.objects.remove(po, do_unlink=True)
    bpy.data.meshes.remove(src)
    return em


_ALPHA_CACHE = {}


def _alpha_map(mat):
    """Opacity of a foliage material as a numpy array (rows bottom-up), or None."""
    import numpy as np
    if mat is None or not mat.node_tree:
        return None
    if mat.name in _ALPHA_CACHE:
        return _ALPHA_CACHE[mat.name]
    b = next((n for n in mat.node_tree.nodes if n.type == "BSDF_PRINCIPLED"), None)
    out = None
    stack = [b.inputs["Alpha"]] if b else []
    seen = set()
    while stack and out is None:
        s = stack.pop()
        for lk in s.links:
            nd = lk.from_node
            if nd.name in seen:
                continue
            seen.add(nd.name)
            if nd.type == "TEX_IMAGE" and nd.image:
                w, h = nd.image.size
                px = np.empty(w * h * 4, dtype=np.float32)
                nd.image.pixels.foreach_get(px)
                px = px.reshape(h, w, 4)
                out = px[..., 3] if lk.from_socket.identifier == "Alpha" else px[..., 0]
                break
            stack.extend(i for i in nd.inputs if i.is_linked)
    _ALPHA_CACHE[mat.name] = out
    return out


def reduce_tree(src, target, rng, flatten=False):
    """One LOD from a source plant mesh: foliage cards thinned to the leaf budget (outer crown
    favoured, kept cards enlarged to preserve coverage), wood decimated to the wood budget.
    flatten=True (LOD1/LOD2): flat foliage islands are rebuilt as single quads first."""
    if len(src.polygons) > MAX_BMESH_FACES:
        raise RuntimeError("source has %d faces (> %d); refusing bmesh" % (len(src.polygons), MAX_BMESH_FACES))
    mats = list(src.materials)
    leaf_idx = {i for i, m in enumerate(mats) if m is not None and leafy(m)}
    dead_idx = {i for i, m in enumerate(mats) if m is not None and "dead" in m.name.lower()}
    wood_idx = set(range(len(mats))) - leaf_idx - dead_idx
    total = sum(len(p.vertices) - 2 for p in src.polygons)
    if total <= target * 1.02:
        out = src.copy()
        if dead_idx:
            bm = bmesh.new()
            bm.from_mesh(out)
            bmesh.ops.delete(bm, geom=[f for f in bm.faces if f.material_index in dead_idx], context="FACES")
            bm.to_mesh(out)
            bm.free()
        check_mesh(out, "lod copy")
        return out
    bm = bmesh.new()
    bm.from_mesh(src)
    leaves = mesh_islands(bm, leaf_idx)
    wood_tris = sum(len(f.verts) - 2 for f in bm.faces if f.material_index in wood_idx)
    leaf_tris = [sum(len(f.verts) - 2 for f in isl) for isl in leaves]
    total_leaf = sum(leaf_tris)
    wood_budget = min(wood_tris, target * (0.22 if target >= 20000 else 0.3)) if leaves else min(wood_tris, target)
    leaf_budget = max(0, target - wood_budget)
    k = min(1.0, leaf_budget / max(1, total_leaf))
    cents = []
    for isl in leaves:
        vs = {v for f in isl for v in f.verts}
        cents.append(sum((v.co for v in vs), Vector()) / len(vs))
    kill = [f for f in bm.faces if f.material_index in dead_idx]
    if leaves and not flatten:
        # kept cards grow so the crown keeps its coverage (area ~ count x scale^2)
        lscale = 1.0 if k >= 0.999 else min(6.0, max(1.0, k ** -0.5))
        cc = sum(cents, Vector()) / len(cents)
        dmax = max((c - cc).length for c in cents) or 1.0
        order = sorted(range(len(leaves)),
                       key=lambda i: -(rng.random() ** (1.0 / (0.2 + ((cents[i] - cc).length / dmax) ** 2))))
        keep, acc = set(), 0
        for i in order:
            if acc >= leaf_budget:
                break
            keep.add(i)
            acc += leaf_tris[i]
        for i, isl in enumerate(leaves):
            if i not in keep:
                kill.extend(isl)
            elif lscale > 1.0:
                vs = {v for f in isl for v in f.verts}
                for v in vs:
                    v.co = cents[i] + (v.co - cents[i]) * lscale
    elif leaves:
        # mid / far levels: every kept foliage island that is a flat card becomes ONE quad spanning
        # its UV rectangle (affine UV -> 3D fit), so the budget buys many more, smaller cards spread
        # over the whole crown; the kept cards grow by the leaf AREA kept, not the triangle count.
        import numpy as np
        uvl = bm.loops.layers.uv.active
        quads, area = [], []
        for isl in leaves:
            P = np.array([tuple(lp.vert.co) for f in isl for lp in f.loops])
            U = np.array([tuple(lp[uvl].uv) for f in isl for lp in f.loops])
            area.append(sum(f.calc_area() for f in isl))
            A = np.c_[U, np.ones(len(U))]
            X, *_ = np.linalg.lstsq(A, P, rcond=None)
            ext = float(np.linalg.norm(P.max(0) - P.min(0)))
            res = float(np.linalg.norm(A @ X - P, axis=1).max())
            (u0, v0), (u1, v1) = U.min(0), U.max(0)
            uva = 0.0
            for f in isl:
                uv = np.array([tuple(lp[uvl].uv) for lp in f.loops])
                uva += 0.5 * abs(float(np.dot(uv[:, 0], np.roll(uv[:, 1], 1)) - np.dot(uv[:, 1], np.roll(uv[:, 0], 1))))
            fill = uva / max((u1 - u0) * (v1 - v0), 1e-9)
            # opaque pieces (bark or stems that share the twig atlas) must not become big cards
            am = _alpha_map(mats[isl[0].material_index])
            opaque = 0.0
            if am is not None:
                ah, aw = am.shape
                gu = np.clip(((np.linspace(u0, u1, 7) % 1.0) * aw).astype(int), 0, aw - 1)
                gv = np.clip(((np.linspace(v0, v1, 7) % 1.0) * ah).astype(int), 0, ah - 1)
                opaque = float((am[np.ix_(gv, gu)] > 0.5).mean())
            if ext > 1e-5 and res <= 0.12 * ext and fill >= 0.35 and opaque < 0.85 and \
                    (u1 - u0) > 1e-5 and (v1 - v0) > 1e-5:
                cuv = [(u0, v0), (u1, v0), (u1, v1), (u0, v1)]
                quads.append(([Vector(tuple(np.array([u, v, 1.0]) @ X)) for (u, v) in cuv], cuv,
                              isl[0].material_index))
            else:
                quads.append(None)
        cost = [2 if q else t for q, t in zip(quads, leaf_tris)]
        total_area = sum(area) or 1.0
        cc = sum(cents, Vector()) / len(cents)
        dmax = max((c - cc).length for c in cents) or 1.0
        order = sorted(range(len(leaves)),
                       key=lambda i: -(rng.random() ** (1.0 / (0.2 + ((cents[i] - cc).length / dmax) ** 2))))
        if sum(a for a, q in zip(area, quads) if q) >= 0.5 * total_area:
            order = [i for i in order if quads[i]]       # curved / odd islands are left out entirely
        keep, acc, kept_area = [], 0, 0.0
        for i in order:
            if acc >= leaf_budget:
                break
            keep.append(i)
            acc += cost[i]
            kept_area += area[i]
        ka = min(1.0, kept_area / total_area)
        lscale = 1.0 if ka >= 0.999 else min(8.0, max(1.0, ka ** -0.5))
        keep_set = set(keep)
        for i, isl in enumerate(leaves):
            if i not in keep_set or quads[i]:
                kill.extend(isl)
            elif lscale > 1.0:
                vs = {v for f in isl for v in f.verts}
                for v in vs:
                    v.co = cents[i] + (v.co - cents[i]) * lscale
        for i in keep:
            if not quads[i]:
                continue
            corners, cuv, mi = quads[i]
            c = sum(corners, Vector()) / 4.0
            vs = [bm.verts.new(c + (p - c) * lscale) for p in corners]
            try:
                f = bm.faces.new(vs)
            except ValueError:
                continue
            f.material_index = mi
            for lp, uv in zip(f.loops, cuv):
                lp[uvl].uv = uv
        dbg("reduce_tree flatten: %d islands, %d flat, kept %d (area %.3f), card scale %.2f" % (
            len(leaves), sum(1 for q in quads if q), len(keep), ka, lscale))
    if wood_budget / max(1, wood_tris) < 0.2:
        for isl in mesh_islands(bm, wood_idx):
            if sum(len(f.verts) - 2 for f in isl) < 120:
                kill.extend(isl)
    bmesh.ops.delete(bm, geom=list(set(kill)), context="FACES")
    tmp = bpy.data.meshes.new("TMP_lod")
    bm.to_mesh(tmp)
    bm.free()
    for m in mats:
        tmp.materials.append(m)
    check_mesh(tmp, "lod")
    wood_left = sum(len(p.vertices) - 2 for p in tmp.polygons if p.material_index in wood_idx)
    ratio = min(1.0, wood_budget / max(1, wood_left))
    final = bmesh.new()
    for mi in range(len(mats)):
        part = bmesh.new()
        part.from_mesh(tmp)
        bmesh.ops.delete(part, geom=[f for f in part.faces if f.material_index != mi], context="FACES")
        if not part.faces:
            part.free()
            continue
        pm = bpy.data.meshes.new("TMP_part")
        part.to_mesh(pm)
        part.free()
        for m in mats:
            pm.materials.append(m)
        if mi in wood_idx and ratio < 0.98:
            em = decimated_copy(pm, ratio, "decimate")
            if ratio < 0.3 and len(em.polygons) > 20:
                # hard decimation can bridge a fork with one huge, compact triangle: drop those (the
                # decimated trunk has large faces too, but long thin ones; the root flare is spared)
                ar = sorted(p.area for p in em.polygons)
                lim = 10.0 * ar[len(ar) // 2]
                zmin = min(v.co.z for v in em.vertices)

                def compact(p):
                    vv = [em.vertices[i].co for i in p.vertices]
                    e2 = sum((vv[i] - vv[i - 1]).length_squared for i in range(len(vv)))
                    return 4.0 * math.sqrt(3.0) * p.area / max(e2, 1e-12)
                big = [p.index for p in em.polygons
                       if p.area > lim and p.center.z > zmin + 1.5 and compact(p) > 0.35]
                if big:
                    bmw = bmesh.new()
                    bmw.from_mesh(em)
                    bmw.faces.ensure_lookup_table()
                    bmesh.ops.delete(bmw, geom=[bmw.faces[i] for i in big], context="FACES")
                    bmw.to_mesh(em)
                    bmw.free()
                    dbg("reduce_tree: dropped %d oversized wood triangles (> %.3f)" % (len(big), lim))
        else:
            em = pm.copy()
        final.from_mesh(em)
        bpy.data.meshes.remove(em)
        bpy.data.meshes.remove(pm)
    out = bpy.data.meshes.new("TMP_lodout")
    final.to_mesh(out)
    final.free()
    for m in mats:
        out.materials.append(m)
    bpy.data.meshes.remove(tmp)
    check_mesh(out, "lod out")
    out["card_scale"] = float(lscale) if leaves else 1.0
    return out


def tree_metrics(me):
    """Trunk base (x, y, min z), height and trunk radius at breast height."""
    mats = list(me.materials)
    wood = [p for p in me.polygons if p.material_index < len(mats) and mats[p.material_index]
            and not leafy(mats[p.material_index])]
    zs = [v.co.z for v in me.vertices]
    zmin = min(zs)
    pts = [me.vertices[vi].co for p in wood for vi in p.vertices if me.vertices[vi].co.z < zmin + 0.6]
    if not pts:
        pts = [v.co for v in me.vertices if v.co.z < zmin + 0.3]
    if not pts:
        pts = [v.co for v in me.vertices]
    bx = sum(p.x for p in pts) / len(pts)
    by = sum(p.y for p in pts) / len(pts)
    ring = [me.vertices[vi].co for p in wood for vi in p.vertices if zmin + 0.9 < me.vertices[vi].co.z < zmin + 1.5]
    r = max((math.hypot(c.x - bx, c.y - by) for c in ring), default=0.2)
    return (bx, by, zmin), max(zs) - zmin, r


def downscale_images(meshes, size):
    """Point every texture larger than `size` at a downscaled PNG copy (cached next to the
    library), so the exported files stay inside the budget."""
    os.makedirs(os.path.join(PREPARED_DIR, "textures"), exist_ok=True)
    done = set()
    for me in meshes:
        for m in me.materials:
            if not m or not m.node_tree:
                continue
            for n in m.node_tree.nodes:
                if n.type != "TEX_IMAGE" or not n.image or n.image.name in done:
                    continue
                img = n.image
                done.add(img.name)
                if max(img.size) <= size:
                    continue
                stem = os.path.splitext(os.path.basename(bpy.path.abspath(img.filepath) or img.name))[0]
                dst = os.path.join(PREPARED_DIR, "textures", "%s_%d.png" % (stem.replace("_2k", ""), size))
                if not os.path.isfile(dst):
                    tmp = img.copy()
                    tmp.scale(size, size)
                    tmp.filepath_raw = dst
                    tmp.file_format = "PNG"
                    tmp.save()
                    bpy.data.images.remove(tmp)
                cs = img.colorspace_settings.name
                img.filepath = dst
                img.reload()
                img.colorspace_settings.name = cs


def recentre(meshes, base, scale):
    mtx = Matrix.Scale(scale, 4) @ Matrix.Translation((-base[0], -base[1], -base[2]))
    for me in meshes:
        me.transform(mtx)


def bottom_centre(me):
    xs = [v.co.x for v in me.vertices]
    ys = [v.co.y for v in me.vertices]
    zs = [v.co.z for v in me.vertices]
    return ((min(xs) + max(xs)) / 2, (min(ys) + max(ys)) / 2, min(zs))


def build_bench_meshes(spec):
    """One bench module of the Poly Haven modular street seating kit, assembled (the .blend lays the
    kit pieces out side by side, not assembled). Module rule read from the pieces: the 1.862 m
    crossbar spans between the leg posts (post +-0.04 m), so the legs stand at +-0.971 m from the seat
    centre; their top brackets (post to +0.092 m) carry the 1.84 m seat ends (+-0.92 m) and the foot
    plates of the back supports (kit offset +-0.94 m from the seat); the end armrests sit on the
    posts and meet the back uprights. The right leg and armrest are the left ones mirrored.
    Front toward -Y (back on +Y), origin at the floor centre, seat top at 0.45 m."""
    LEG = 0.971
    # suspended_support_01 is left out: 0.20 m tall, it cannot reach from the crossbar to the seat
    # (0.28 m apart), so at any height it would float under the seat or hang off the crossbar
    kit = ["seat", "seat_back", "back_support_r", "back_support_l", "legs_single", "arm_rest_01", "crossbar"]
    obs = {o.name.split(".")[0]: o for o in append_objects(spec["asset"], kit)}
    seat_x = obs["seat"].location.x          # every piece is placed relative to the seat centre
    place = [  # (piece, x relative to the seat centre, mirrored in x)
        ("seat", 0.0, False), ("seat_back", 0.0, False), ("crossbar", 0.0, False),
        ("back_support_r", obs["back_support_r"].location.x - seat_x, False),
        ("back_support_l", obs["back_support_l"].location.x - seat_x, False),
        ("legs_single", -LEG, False), ("legs_single", LEG, True),
        ("arm_rest_01", -LEG, False), ("arm_rest_01", LEG, True),
    ]
    bm = bmesh.new()
    mats = []
    for (pn, x, mirror) in place:
        ob = obs[pn]
        me = ob.data
        idx = []
        for m in me.materials:
            if m not in mats:
                mats.append(m)
            idx.append(mats.index(m))
        n0 = len(bm.faces)
        v0 = len(bm.verts)
        bm.from_mesh(me)
        bm.verts.ensure_lookup_table()
        bm.faces.ensure_lookup_table()
        loc, rot, scl = ob.matrix_basis.decompose()
        mw = Matrix.Translation((x, loc.y, loc.z)) @ rot.to_matrix().to_4x4() @ Matrix.Diagonal((*scl, 1.0))
        if mirror:
            mw = mw @ Matrix.Diagonal((-1.0, 1.0, 1.0, 1.0))
        for v in bm.verts[v0:]:
            v.co = mw @ v.co
        new_faces = bm.faces[n0:]
        for f in new_faces:
            f.material_index = idx[f.material_index] if f.material_index < len(idx) else 0
        if mirror:
            bmesh.ops.reverse_faces(bm, faces=list(new_faces))
    for ob in obs.values():
        me = ob.data
        bpy.data.objects.remove(ob, do_unlink=True)
        if me.users == 0:
            bpy.data.meshes.remove(me)
    me0 = bpy.data.meshes.new("TMP_bench")
    bm.to_mesh(me0)
    bm.free()
    for m in mats:
        me0.materials.append(m)
    bc = bottom_centre(me0)
    me0.transform(Matrix.Translation((-bc[0], -bc[1], -bc[2])))
    back_y = [v.co.y for v in me0.vertices if v.co.z > 0.75]
    if sum(back_y) / max(1, len(back_y)) < 0:       # back on -Y: turn so the sitter faces -Y (back on +Y)
        me0.transform(Matrix.Rotation(math.pi, 4, "Z"))
    check_mesh(me0, "bench")
    t0 = sum(len(p.vertices) - 2 for p in me0.polygons)
    groups = {}
    for p in me0.polygons:
        g = groups.setdefault(me0.materials[p.material_index].name, [1e9, -1e9])
        for vi in p.vertices:
            x = me0.vertices[vi].co.x
            g[0], g[1] = min(g[0], x), max(g[1], x)
    zs = [v.co.z for v in me0.vertices]
    seat_top = max(me0.vertices[vi].co.z for p in me0.polygons if "timber" in me0.materials[p.material_index].name
                   for vi in p.vertices if me0.vertices[vi].co.z < 0.47)
    log("bench assembled: %d tris, width %.3f m, seat top %.3f m, height %.3f m; material x-extents %s" % (
        t0, max(g[1] for g in groups.values()) - min(g[0] for g in groups.values()), seat_top, max(zs),
        {k: (round(v[0], 3), round(v[1], 3), round(v[1] - v[0], 3)) for k, v in groups.items()}))
    RESULTS["bench assembly"] = {"tris": t0, "seat_top_m": round(seat_top, 3),
                                 "groups_x": {k: [round(v[0], 3), round(v[1], 3)] for k, v in groups.items()}}
    return [me0, decimated_copy(me0, 5000 / t0, "bench lod1"), decimated_copy(me0, 1400 / t0, "bench lod2")]


def build_grate_meshes():
    """Cast-iron tree grate, 1.6 m square: chamfered frame, concentric rings and radial ribs
    around a 0.6 m trunk opening, solid corner plates; top flush with the paving (z = 0)."""
    out = []
    for lod, (nring, nrib, seg) in enumerate(((6, 24, 64), (3, 12, 32), (0, 0, 16))):
        mb = MB("TMP_grate%d" % lod)
        K = "Cast_Iron"
        h, t = 0.8, 0.035
        for (x0, x1, y0, y1) in ((-h, h, -h, -h + 0.07), (-h, h, h - 0.07, h), (-h, -h + 0.07, -h + 0.07, h - 0.07),
                                 (h - 0.07, h, -h + 0.07, h - 0.07)):
            mb.box(K, x0, x1, y0, y1, -t, 0.0, skip=("-z",), bevel=0.006 if lod == 0 else 0.0)
        r_out = h - 0.07
        # corner plates (between the outer ring and the frame corners)
        for sx in (-1, 1):
            for sy in (-1, 1):
                pts = [(sx * r_out, sy * r_out)]
                for k in range(9):
                    a = math.radians(90 * k / 8)
                    pts.append((sx * r_out * math.cos(a), sy * r_out * math.sin(a)))
                mb.face([(px, py, 0.0) for (px, py) in pts], K, want=(0, 0, 1))
        # rings and ribs between r 0.3 and r_out
        r_in = 0.3
        rings = [r_in + (r_out - r_in) * i / max(1, nring) for i in range(nring + 1)] if nring else [r_in, r_out]
        for r in rings:
            mb.lathe([(r + 0.012, -t), (r + 0.012, 0.0), (r - 0.012, 0.0), (r - 0.012, -t)], seg, [K] * 3)
        for i in range(nrib):
            a = 2 * math.pi * i / nrib
            c, s = math.cos(a), math.sin(a)
            w = 0.011
            p = [(c * r_in - s * w, s * r_in + c * w), (c * r_out - s * w, s * r_out + c * w),
                 (c * r_out + s * w, s * r_out - c * w), (c * r_in + s * w, s * r_in - c * w)]
            mb.face([(x, y, -0.002) for (x, y) in p], K, want=(0, 0, 1))
        if lod == 2:
            mb.lathe([(r_out, 0.0), (r_in, 0.0)], seg, [K])
        ob = mb.finish(tmp_coll())
        me = ob.data
        bpy.data.objects.remove(ob, do_unlink=True)
        out.append(me)
    return out


def leaf_templates(asset, oname, count, rng):
    """Individual leaf cards (single quads with their UVs) taken from a Poly Haven shrub's foliage,
    each recentred and turned so its face normal is +Z. Returns (material, [[(co, uv), ...], ...])."""
    src = append_mesh_copies(asset, [oname])[0]
    leaf_mi = next(i for i, m in enumerate(src.materials) if m is not None and leafy(m))
    mat = src.materials[leaf_mi]
    bm = bmesh.new()
    bm.from_mesh(src)
    uvl = bm.loops.layers.uv.active
    cards = [f for f in bm.faces if f.material_index == leaf_mi and len(f.verts) == 4 and f.calc_area() > 1e-5]
    rng.shuffle(cards)
    out = []
    for f in cards[:count]:
        c = f.calc_center_median()
        q = f.normal.to_track_quat("Z", "Y").to_matrix().inverted()
        out.append([(tuple(q @ (lp.vert.co - c)), tuple(lp[uvl].uv)) for lp in f.loops])
    bm.free()
    bpy.data.meshes.remove(src)
    return mat, out


def build_hedge_meshes(spec):
    """Clipped hedge module (repeated along every run): a dark inner core under several layers of
    real leaf cards from the Poly Haven searsia_burchellii shrub (small leaves, like box or holly),
    scattered densely with random tilt so single leaves break the top edge and the corners.
    LOD1/LOD2 keep fewer, larger leaves."""
    L, W, H = spec["size"]
    rng = random.Random(RNG_SEED + int(L * 100 + W * 10 + H))
    leaf_mat, tmpl = leaf_templates("searsia_burchellii", "searsia_burchellii_small_LOD2", 120, rng)
    faces = [((0, 0, H), (L, W), (1, 0, 0), (0, 1, 0), (0, 0, 1), 1.0),
             ((0, -W / 2, H / 2), (L, H), (1, 0, 0), (0, 0, 1), (0, -1, 0), 1.0),
             ((0, W / 2, H / 2), (L, H), (1, 0, 0), (0, 0, 1), (0, 1, 0), 1.0),
             ((-L / 2, 0, H / 2), (W, H), (0, 1, 0), (0, 0, 1), (-1, 0, 0), 0.5),
             ((L / 2, 0, H / 2), (W, H), (0, 1, 0), (0, 0, 1), (1, 0, 0), 0.5)]
    leaves = []
    for (c, (su, sv), U, V, N, dens) in faces:
        n = int(spec["density"] * su * sv * dens)
        for _ in range(n):
            u, v = rng.uniform(-0.5, 0.5), rng.uniform(-0.5, 0.5)
            p = Vector(c) + Vector(U) * u * su + Vector(V) * v * sv
            # three layers: most leaves near the clipped surface, some deeper, a few proud of it
            r = rng.random()
            depth = rng.uniform(-0.03, 0.035) if r < 0.6 else (rng.uniform(-0.13, -0.03) if r < 0.93 else rng.uniform(0.035, 0.07))
            nrm = (Vector(N) + Vector((rng.uniform(-0.9, 0.9), rng.uniform(-0.9, 0.9), rng.uniform(-0.9, 0.9)))).normalized()
            if nrm.dot(Vector(N)) < 0.15:
                nrm = (nrm + Vector(N)).normalized()
            leaves.append((p + Vector(N) * depth, nrm, rng.randrange(len(tmpl)), rng.uniform(0, 2 * math.pi),
                           rng.uniform(0.7, 1.0), rng.random()))
    out = []
    kp = spec.get("keep", (1.0, 0.4, 0.12))
    for lod, (keep, grow) in enumerate(((kp[0], 1.0), (kp[1], 1.55 if kp[1] >= 0.35 else 1.75),
                                        (kp[2], 2.7 if kp[2] >= 0.1 else 3.6))):
        bm = bmesh.new()
        uvl = bm.loops.layers.uv.new("UVMap")
        for (p, nrm, ti, spin, sc, rk) in leaves:
            if rk > keep:
                continue
            m = Matrix.Translation(p) @ nrm.to_track_quat("Z", "Y").to_matrix().to_4x4() @ \
                Matrix.Rotation(spin, 4, "Z") @ Matrix.Scale(sc * grow, 4)
            t = tmpl[ti]
            vs = [bm.verts.new(m @ Vector(co)) for (co, uv) in t]
            try:
                f = bm.faces.new(vs)
            except ValueError:
                continue
            f.material_index = 0
            for lp, (co, uv) in zip(f.loops, t):
                lp[uvl].uv = uv
        inset = 0.12
        core = [bm.verts.new(c) for c in
                ((-L / 2, -W / 2 + inset, 0), (L / 2, -W / 2 + inset, 0), (L / 2, W / 2 - inset, 0), (-L / 2, W / 2 - inset, 0),
                 (-L / 2, -W / 2 + inset, H - inset), (L / 2, -W / 2 + inset, H - inset), (L / 2, W / 2 - inset, H - inset),
                 (-L / 2, W / 2 - inset, H - inset))]
        for q in ((0, 1, 5, 4), (1, 2, 6, 5), (2, 3, 7, 6), (3, 0, 4, 7), (4, 5, 6, 7)):
            f = bm.faces.new([core[i] for i in q])
            f.material_index = 1
            f.normal_update()
            if f.normal.dot(f.calc_center_median() - Vector((0, 0, H / 2))) < 0:
                f.normal_flip()
        me = bpy.data.meshes.new("TMP_hedge%d" % lod)
        bm.to_mesh(me)
        bm.free()
        me.materials.append(leaf_mat)
        me.materials.append(MATS["Hedge_Core"])
        check_mesh(me, "hedge")
        out.append(me)
    return out


def crown_normal(co, crown):
    """Shading normal of the far levels (LOD3 cards, LOD2 cluster cards): outward from the trunk axis,
    gently up in the upper crown, never facing down (trunk). crown = (centre z, vertical r, horizontal r)."""
    zc_, rz_, rx_ = crown
    # horizontal part damped: a real crown's leaves face every way, so its shadow side is not as dark
    # as a sphere's terminator
    r = Vector((0.45 * co.x / rx_, 0.45 * co.y / rx_, min(max(0.6 * (co.z - zc_) / rz_, -0.1), 1.0) + 0.3))
    return tuple(r.normalized()) if r.length > 1e-6 else (0.0, 0.0, 1.0)


IMP_TWIN = True     # LOD3 cards as back-to-back single-sided faces with crown normals (see make_impostor)
IMP_INFO = {}       # per species: impostor capture frame and masks (used by the cluster-card LOD2)


def _imp_scene(name):
    """Temp scene for impostor capture: Cycles, transparent film, neutral (Standard) transform,
    linear EXR output, lit only by a uniform white sky (so the colour is albedo x occlusion)."""
    sc = bpy.data.scenes.new(TMP_SCENE_PREFIX + "_imp_" + name)
    sc.render.engine = "CYCLES"
    enable_gpu(sc)
    sc.cycles.samples = 64
    sc.cycles.use_denoising = False
    sc.render.film_transparent = True
    try:
        sc.view_settings.view_transform = "Standard"
        sc.view_settings.look = "None"
    except TypeError:
        pass
    sc.view_settings.exposure = 0.0
    sc.view_settings.gamma = 1.0
    isf = sc.render.image_settings
    isf.file_format = "OPEN_EXR"
    isf.color_mode = "RGBA"
    isf.color_depth = "32"
    w = tag(bpy.data.worlds.new(TMP_SCENE_PREFIX + "_impworld"))
    nt = w.node_tree
    for n in list(nt.nodes):
        nt.nodes.remove(n)
    out = nt.nodes.new("ShaderNodeOutputWorld")
    bg = nt.nodes.new("ShaderNodeBackground")
    sock(bg, "Color").default_value = (1.0, 1.0, 1.0, 1.0)
    sock(bg, "Strength").default_value = 1.0
    nt.links.new(sock(bg, "Background", True), sock(out, "Surface"))
    sc.world = w
    return sc, w, bg


def _normal_material(m, mode="normal"):
    """Copy of a plant material that emits its camera-space normal (0..1) or, with mode="albedo",
    its base colour, keeping the alpha cut."""
    c = m.copy()
    nt = c.node_tree
    b = next((n for n in nt.nodes if n.type == "BSDF_PRINCIPLED"), None)
    alpha_src = b.inputs["Alpha"].links[0].from_socket if (b and b.inputs["Alpha"].links) else None
    out = next(n for n in nt.nodes if n.type == "OUTPUT_MATERIAL" and n.is_active_output)
    em = nt.nodes.new("ShaderNodeEmission")
    if mode == "mask":
        v = 1.0 if leafy(m) else 0.0
        em.inputs["Color"].default_value = (v, v, v, 1.0)
    elif mode == "albedo":
        bc = sock(b, "Base Color") if b else None
        if bc is not None and bc.links:
            nt.links.new(bc.links[0].from_socket, em.inputs["Color"])
        elif bc is not None:
            em.inputs["Color"].default_value = bc.default_value
    else:
        geo = nt.nodes.new("ShaderNodeNewGeometry")
        vt = nt.nodes.new("ShaderNodeVectorTransform")
        vt.vector_type = "NORMAL"
        vt.convert_from = "WORLD"
        vt.convert_to = "CAMERA"
        nt.links.new(geo.outputs["Normal"], vt.inputs["Vector"])
        ma = nt.nodes.new("ShaderNodeVectorMath")
        ma.operation = "MULTIPLY_ADD"
        ma.inputs[1].default_value = (0.5, 0.5, 0.5)
        ma.inputs[2].default_value = (0.5, 0.5, 0.5)
        nt.links.new(vt.outputs["Vector"], ma.inputs[0])
        nt.links.new(ma.outputs["Vector"], em.inputs["Color"])
    if alpha_src is not None:
        tr = nt.nodes.new("ShaderNodeBsdfTransparent")
        mix = nt.nodes.new("ShaderNodeMixShader")
        nt.links.new(alpha_src, mix.inputs["Fac"])
        nt.links.new(tr.outputs[0], mix.inputs[1])
        nt.links.new(em.outputs[0], mix.inputs[2])
        nt.links.new(mix.outputs[0], out.inputs["Surface"])
    else:
        nt.links.new(em.outputs[0], out.inputs["Surface"])
    return c


def _render_exr(sc, path):
    sc.render.filepath = path
    bpy.ops.render.render(write_still=True, scene=sc.name)
    arr, w, h = image_array(path)
    return arr


def _ortho_pair(name, me, cam_loc, cam_rot, extent, res):
    """Colour (neutral sky light) and camera-space normal renders of one orthographic view.
    Returns float arrays (rows bottom-up, premultiplied alpha as Cycles writes it)."""
    sc, world, bg = _imp_scene(name)
    ob = bpy.data.objects.new("TMP_imp", me)
    sc.collection.objects.link(ob)
    cd = bpy.data.cameras.new("TMP_impcam")
    cd.type = "ORTHO"
    cd.ortho_scale = extent
    cd.clip_start, cd.clip_end = 0.05, 500.0
    cam = bpy.data.objects.new("TMP_impcam", cd)
    sc.collection.objects.link(cam)
    cam.location = cam_loc
    cam.rotation_euler = cam_rot
    sc.camera = cam
    sc.render.resolution_x, sc.render.resolution_y = res
    sc.render.resolution_percentage = 100
    os.makedirs(os.path.join(PREPARED_DIR, "textures"), exist_ok=True)
    tmp = os.path.join(WORK_DIR, "veglib")
    os.makedirs(tmp, exist_ok=True)
    lit = _render_exr(sc, os.path.join(tmp, "imp_%s_lit.exr" % name))
    # albedo and normals: swap in emission copies of every material slot, no light
    orig = list(me.materials)
    sock(bg, "Strength").default_value = 0.0
    sc.cycles.samples = 16
    res_ = []
    for mode in ("albedo", "normal", "mask"):
        nmats = [(_normal_material(m, mode) if m else None) for m in orig]
        for i, m in enumerate(nmats):
            me.materials[i] = m
        res_.append(_render_exr(sc, os.path.join(tmp, "imp_%s_%s.exr" % (name, mode))))
        for i, m in enumerate(orig):
            me.materials[i] = m
        for m in nmats:
            if m:
                bpy.data.materials.remove(m)
    bpy.data.objects.remove(ob, do_unlink=True)
    bpy.data.objects.remove(cam, do_unlink=True)
    bpy.data.cameras.remove(cd)
    bpy.data.scenes.remove(sc)
    bpy.data.worlds.remove(world)
    return lit, res_[0], res_[1], res_[2]


def _unpremul(arr):
    import numpy as np
    a = np.clip(arr[..., 3], 0.0, 1.0)
    return np.where(a[..., None] > 1e-4, arr[..., :3] / np.maximum(a[..., None], 1e-4), 0.0), a


def _box_blur(x, r):
    import numpy as np
    out = x.copy()
    for ax in (0, 1):
        acc = np.zeros_like(out)
        for d in range(-r, r + 1):
            acc += np.roll(out, d, ax)
        out = acc / (2 * r + 1)
    return out


def _finish_maps(lit, alb, nor, mask=None, darken_centre=True, sphere=0.0, cards=False, info=None):
    """Impostor maps from the captures. Colour = albedo x softened occlusion (occlusion =
    white-sky render / albedo, softened as occ^0.7: the levels it replaces are drawn without
    ambient occlusion, so the impostor keeps only the depth cue, not the full darkening),
    sRGB with straight alpha, bled into the transparent texels; optionally a softly darker centre
    column on the foliage (no bright seam where crossed cards meet). cards=True thins the foliage
    alpha where the crossed cards overlap, by the local coverage, so three cards read as dense as
    the tree itself (wood is never thinned). Normal map: tangent space facing the viewer,
    optionally blended toward a crown ellipsoid so the card shades like a volume.
    info (dict, optional) receives the solid and foliage masks before thinning."""
    import numpy as np
    h, w = lit.shape[:2]
    lrgb, a = _unpremul(lit)
    argb, _ = _unpremul(alb)
    fol = (_unpremul(mask)[0][..., 0] > 0.5) if mask is not None else np.ones((h, w), dtype=bool)
    if info is not None:
        info["solid"] = a > 0.5
        info["fol"] = (a > 0.5) & fol
    lum = lambda c: c @ np.array([0.2126, 0.7152, 0.0722], dtype=np.float32)
    occ = np.clip(lum(lrgb) / np.maximum(lum(argb), 1e-3), 0.0, 1.0)
    rgb = argb * (occ ** 0.7)[..., None]
    if cards:
        solid0 = (a > 0.5).astype(np.float32)
        cov = np.clip(_box_blur(solid0, 5), 0.03, 1.0)
        u = np.abs(np.linspace(-1.0, 1.0, w))[None, :]
        mult = 1.0 + 1.3 * np.clip(1.0 - u / 0.75, 0.0, 1.0)
        keep = (1.0 - (1.0 - cov) ** (1.0 / mult)) / cov
        rng = np.random.default_rng(1729)
        blk = rng.random(((h + 1) // 2, (w + 1) // 2)).astype(np.float32)
        noise = np.repeat(np.repeat(blk, 2, axis=0), 2, axis=1)[:h, :w]
        a = np.where((noise < keep) | ~fol, a, 0.0)
    if darken_centre:
        u = np.abs(np.linspace(-1.0, 1.0, w))[None, :]
        dk = (0.86 + 0.14 * np.clip(u / 0.6, 0.0, 1.0) ** 0.8) * np.ones((h, 1))
        rgb *= np.where(fol, dk, 1.0)[..., None]
    lin = np.clip(rgb, 0.0, 1.0)
    srgb = np.where(lin <= 0.0031308, lin * 12.92, 1.055 * np.power(lin, 1 / 2.4) - 0.055)
    na = np.clip(nor[..., 3], 0.0, 1.0)
    n = np.where(na[..., None] > 1e-4, nor[..., :3] / np.maximum(na[..., None], 1e-4), 0.5) * 2.0 - 1.0
    n[..., 2] = np.abs(n[..., 2])
    n /= np.maximum(np.linalg.norm(n, axis=-1, keepdims=True), 1e-4)
    solid = a > 0.5
    if sphere > 0.0 and solid.any():
        # crown ellipse from the solid texels above the lower quarter (keeps the trunk out of it)
        rows = np.where(solid.any(axis=1))[0]
        r0, r1 = rows.min(), rows.max()
        upper = solid.copy()
        upper[:r0 + int(0.25 * (r1 - r0))] = False
        if upper.any():
            rr = np.where(upper.any(axis=1))[0]
            cc = np.where(upper.any(axis=0))[0]
            cy, ry = 0.5 * (rr.min() + rr.max()), max(2.0, 0.5 * (rr.max() - rr.min()))
            cx, rx = 0.5 * (cc.min() + cc.max()), max(2.0, 0.5 * (cc.max() - cc.min()))
            yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
            sx, sy = (xx - cx) / rx, (yy - cy) / ry
            r2 = sx * sx + sy * sy
            sz = np.sqrt(np.clip(1.0 - r2, 0.12, 1.0))
            s = np.stack([sx, sy, sz], axis=-1)
            s /= np.linalg.norm(s, axis=-1, keepdims=True)
            wgt = (sphere * np.clip(1.35 - np.sqrt(r2), 0.0, 1.0))[..., None]
            n = (1.0 - wgt) * n + wgt * s
            n /= np.maximum(np.linalg.norm(n, axis=-1, keepdims=True), 1e-4)
    n[~solid] = (0.0, 0.0, 1.0)
    # bleed colour outward (8 passes) so mip-mapping never pulls in black
    filled = solid.copy()
    for _ in range(8):
        acc = np.zeros_like(srgb)
        cnt = np.zeros((h, w), dtype=np.float32)
        for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            m = np.roll(filled, (dy, dx), (0, 1))
            acc += np.roll(srgb, (dy, dx), (0, 1)) * m[..., None]
            cnt += m
        grow = (~filled) & (cnt > 0)
        srgb[grow] = acc[grow] / cnt[grow][:, None]
        filled |= grow
    out_col = np.concatenate([srgb, a[..., None]], axis=-1)
    return out_col, n * 0.5 + 0.5


def _impostor_material(name, col_path, nor_path, double_sided=True):
    m = new_material("Impostor_" + name)
    nt = m.node_tree
    b = bsdf_of(m)
    tc = nt.nodes.new("ShaderNodeTexImage")
    tc.image = load_image(col_path, False)
    tc.image.alpha_mode = "STRAIGHT"
    nt.links.new(sock(tc, "Color", True), sock(b, "Base Color"))
    rnd = nt.nodes.new("ShaderNodeMath")
    rnd.operation = "ROUND"
    nt.links.new(sock(tc, "Alpha", True), rnd.inputs[0])
    nt.links.new(rnd.outputs[0], sock(b, "Alpha"))
    tn = nt.nodes.new("ShaderNodeTexImage")
    tn.image = load_image(nor_path, True)
    nm = nt.nodes.new("ShaderNodeNormalMap")
    nt.links.new(sock(tn, "Color", True), sock(nm, "Color"))
    nt.links.new(sock(nm, "Normal", True), sock(b, "Normal"))
    # a double-sided back face negates the whole tangent frame (three.js and Cycles alike), so an
    # up-facing leaf normal would turn down there: full strength only on the single-sided twin cards
    sock(nm, "Strength").default_value = 0.8 if not double_sided else 0.45
    sock(b, "Roughness").default_value = 0.7
    sock(b, "Specular IOR Level").default_value = 0.5
    m.use_backface_culling = not double_sided
    try:
        m.surface_render_method = "DITHERED"
    except (AttributeError, TypeError):
        pass
    m["na_simplified"] = 1
    return m


def make_impostor(name, me0, spec):
    """LOD3: three crossed cards through the trunk axis (trees, shrubs; 12 triangles) or a textured
    box (hedge module; 10 triangles) with colour+alpha and normal maps rendered from LOD0 under
    neutral sky light. Origin at the trunk base, LOD0 height and crown width."""
    import numpy as np
    xs = [v.co.x for v in me0.vertices]
    ys = [v.co.y for v in me0.vertices]
    zs = [v.co.z for v in me0.vertices]
    H = max(zs)
    tex_dir = os.path.join(PREPARED_DIR, "textures")
    col_p = os.path.join(tex_dir, "impostor_%s_col.png" % name)
    nor_p = os.path.join(tex_dir, "impostor_%s_nor.png" % name)
    mb = MB("TMP_imp_" + name)
    key = "Impostor_" + name
    if spec["kind"] != "hedge":
        hw = max(max(abs(min(xs)), abs(max(xs))), max(abs(min(ys)), abs(max(ys)))) * 1.02
        asp = 2 * hw / H
        res = (512, 1024) if asp < 0.7 else ((512, 512) if asp < 1.4 else (1024, 512))
        Wc = max(2 * hw, H * res[0] / res[1])
        Hc = Wc * res[1] / res[0]
        extent = max(Wc, Hc)
        cap = _ortho_pair(name, me0, (0.0, -200.0, Hc / 2), (math.radians(90), 0.0, 0.0), extent, res)
        info = {"Wc": Wc, "Hc": Hc, "res": res}
        c, n = _finish_maps(*cap, darken_centre=True, sphere=0.0, cards=True, info=info)
        IMP_INFO[name] = info
        save_array(c, col_p, fmt="PNG")
        save_array(n, nor_p, fmt="PNG")
        MATS[key] = _impostor_material(name, col_p, nor_p, double_sided=not IMP_TWIN)
        # three cards through the trunk axis, each split at the axis into two half-cards. IMP_TWIN:
        # every half-card is two single-sided faces back to back (5 mm apart) carrying crown-sphere
        # normals, so the shading depends on the position in the crown and not on which way a card
        # faces (one double-sided face would negate its normal on the back and split the crown into
        # a lit and an unlit half along the axis under a low side sun).
        for k in range(3):
            t = math.radians(60.0 * k)
            dx, dy = math.cos(t), math.sin(t)
            nx, ny = dy, -dx
            for (u0, u1) in ((-0.5, 0.0), (0.0, 0.5)):
                q = [(u0, 0.0), (u1, 0.0), (u1, 1.0), (u0, 1.0)]
                for side in ((1.0, -1.0) if IMP_TWIN else (0.0,)):
                    qq = q if side >= 0 else q[::-1]
                    o = 0.005 * side
                    vs = [mb.bm.verts.new((u * Wc * dx + o * nx, u * Wc * dy + o * ny, vv * Hc)) for (u, vv) in qq]
                    f = mb.bm.faces.new(vs)
                    f.material_index = mb.mi(key)
                    f[mb.done] = 1
                    for lp, (u, vv) in zip(f.loops, qq):
                        lp[mb.uvl].uv = (u + 0.5, vv)
        sol = info["solid"]
        rows = np.where(sol.any(axis=1))[0]
        up_ = sol.copy()
        up_[:rows.min() + int(0.25 * (rows.max() - rows.min()))] = False
        rr = np.where(up_.any(axis=1))[0]
        cc_ = np.where(up_.any(axis=0))[0]
        crown = ((0.5 * (rr.min() + rr.max()) + 0.5) / res[1] * Hc,            # centre height
                 max(0.5 * (rr.max() - rr.min()) / res[1] * Hc, 0.3),           # vertical radius
                 max(0.5 * (cc_.max() - cc_.min()) / res[0] * Wc, 0.3))         # horizontal radius
        info["crown"] = crown
        tex = "%dx%d" % res
    else:
        L, W, Hh = spec["size"]
        sx, sz = L + 0.36, H + 0.05
        ext = max(sx, sz)
        zc = ext / 2 - 0.02
        cap_s = _ortho_pair(name + "_side", me0, (0.0, -100.0, zc), (math.radians(90), 0.0, 0.0), ext, (512, 512))
        cap_t = _ortho_pair(name + "_top", me0, (0.0, 0.0, 100.0), (0.0, 0.0, 0.0), ext, (512, 512))
        cs, ns = _finish_maps(*cap_s, darken_centre=False)
        ct, nt_ = _finish_maps(*cap_t, darken_centre=False)
        # pixel rows run bottom-up: rows 0..511 = top view (lower half of the atlas), 512..1023 = side view
        save_array(np.concatenate([ct, cs], axis=0), col_p, fmt="PNG")
        save_array(np.concatenate([nt_, ns], axis=0), nor_p, fmt="PNG")
        MATS[key] = _impostor_material(name, col_p, nor_p)

        def uv_side(x, z):
            return (x / ext + 0.5, 0.5 + 0.5 * ((z - zc) / ext + 0.5))

        def uv_top(x, y):
            return (x / ext + 0.5, 0.5 * (y / ext + 0.5))
        # modules sit end to end, so the box stops exactly at +-L/2 (no overlapping coplanar faces)
        hl, yw, zt = L / 2, W / 2 + 0.05, H
        for (y, nrm) in ((-yw, (0, -1, 0)), (yw, (0, 1, 0))):
            f = mb.face([(-hl, y, 0.0), (hl, y, 0.0), (hl, y, zt), (-hl, y, zt)], key, want=nrm)
            f[mb.done] = 1
            for lp in f.loops:
                lp[mb.uvl].uv = uv_side(lp.vert.co.x, lp.vert.co.z)
        for (x, nrm) in ((-hl, (-1, 0, 0)), (hl, (1, 0, 0))):
            f = mb.face([(x, -yw, 0.0), (x, yw, 0.0), (x, yw, zt), (x, -yw, zt)], key, want=nrm)
            f[mb.done] = 1
            for lp in f.loops:
                lp[mb.uvl].uv = uv_side(lp.vert.co.y * hl / yw, lp.vert.co.z)
        zt2 = Hh + 0.02
        f = mb.face([(-hl, -yw, zt2), (hl, -yw, zt2), (hl, yw, zt2), (-hl, yw, zt2)], key, want=(0, 0, 1))
        f[mb.done] = 1
        for lp in f.loops:
            lp[mb.uvl].uv = uv_top(lp.vert.co.x, lp.vert.co.y)
        tex = "512x1024 atlas"
    ob = mb.finish(tmp_coll())
    me = ob.data
    bpy.data.objects.remove(ob, do_unlink=True)
    if spec["kind"] != "hedge" and IMP_TWIN:
        me.polygons.foreach_set("use_smooth", [True] * len(me.polygons))     # flat faces ignore custom normals
        me.normals_split_custom_set_from_vertices([crown_normal(v.co, crown) for v in me.vertices])
    log("impostor %s: %d tris, texture %s %s" % (name, sum(len(p.vertices) - 2 for p in me.polygons), tex,
                                                 os.path.basename(col_p)))
    return me


def render_lod_compare(name, mes, path, hedge_len=None):
    """LOD0 (left, reference), LOD2 (middle) and LOD3 (right) seen from 150 m in the project sky -
    the hand-over test. Top half: magnified (long lens). Bottom half: the same row at the viewer's
    pixel density (60 deg vertical FOV on a 1080-line screen), centre crop shown at 2x."""
    import numpy as np
    sc = bpy.data.scenes.new(TMP_SCENE_PREFIX + "_cmp")
    zs = [v.co.z for v in mes[0].vertices]
    xs = [v.co.x for v in mes[0].vertices]
    H = max(zs)
    W = (max(xs) - min(xs)) or 1.0
    reps = 1
    if hedge_len:
        reps = 4
        W = hedge_len * reps
    gap = W * 1.15 + 0.8
    # Cycles ignores backface culling: single-sided materials get a temporary copy that is
    # transparent on back faces, as three.js draws them (FrontSide)
    swaps, tmp_mats = [], {}
    for me in mes:
        for si, m in enumerate(me.materials):
            if m is None or not m.use_backface_culling:
                continue
            if m.name not in tmp_mats:
                c = m.copy()
                nt = c.node_tree
                out = next(n for n in nt.nodes if n.type == "OUTPUT_MATERIAL" and n.is_active_output)
                src = out.inputs["Surface"].links[0].from_socket if out.inputs["Surface"].links else None
                if src is not None:
                    geo = nt.nodes.new("ShaderNodeNewGeometry")
                    tr = nt.nodes.new("ShaderNodeBsdfTransparent")
                    mix = nt.nodes.new("ShaderNodeMixShader")
                    nt.links.new(geo.outputs["Backfacing"], mix.inputs["Fac"])
                    nt.links.new(src, mix.inputs[1])
                    nt.links.new(tr.outputs[0], mix.inputs[2])
                    nt.links.new(mix.outputs[0], out.inputs["Surface"])
                tmp_mats[m.name] = c
            swaps.append((me, si, m))
            me.materials[si] = tmp_mats[m.name]
    for i, me in enumerate(mes):
        for r in range(reps):
            ob = bpy.data.objects.new("TMP_c%d_%d" % (i, r), me)
            off = (r - (reps - 1) / 2) * (hedge_len or 0.0)
            ob.location = ((i - (len(mes) - 1) / 2) * gap + off, 0.0, 0.0)
            ob.rotation_euler = (0.0, 0.0, math.pi if r % 2 else 0.0)
            # lit as the web viewer draws it at this range: no shadow casting (castsShadowWithinM
            # ends well before 150 m) and no ambient occlusion between leaves or crossed cards
            ob.visible_shadow = False
            ob.visible_diffuse = False
            sc.collection.objects.link(ob)
    g = bpy.data.objects.new("TMP_cg", bpy.data.meshes.new("TMP_cg"))
    g.data.from_pydata([(-600, -600, 0), (600, -600, 0), (600, 600, 0), (-600, 600, 0)], [], [(0, 1, 2, 3)])
    g.data.materials.append(flat_material("TMP_cmp_ground", "#6F7A55", 0.9))
    sc.collection.objects.link(g)
    cd = bpy.data.cameras.new("TMP_ccam")
    cam = bpy.data.objects.new("TMP_ccam", cd)
    sc.collection.objects.link(cam)
    cam.location = (0.0, -150.0, 1.7)
    look_at(cam, Vector((0.0, 0.0, H * 0.45)))
    sc.camera = cam
    sc.world = ensure_preview_world()
    sc.render.engine = "CYCLES"
    enable_gpu(sc)
    sc.cycles.samples = 64
    sc.cycles.use_denoising = True
    sc.render.resolution_x, sc.render.resolution_y = 800, 500
    sc.render.resolution_percentage = 100
    sc.render.image_settings.file_format = "PNG"
    sc.render.image_settings.color_mode = "RGB"
    try:
        sc.view_settings.view_transform = "AgX"
    except TypeError:
        pass
    parts = []
    frame_w = 2 * gap + W * 1.3
    for (lens, tag_) in ((max(35.0, 36.0 * 150.0 / max(frame_w, H * 1.6 * 1.3)), "zoom"), (44.1, "viewer")):
        cd.lens = lens
        cd.sensor_fit = "HORIZONTAL"
        cd.sensor_width = 36.0
        p = path[:-4] + "_" + tag_ + ".png"
        sc.render.filepath = p
        bpy.ops.render.render(write_still=True, scene=sc.name)
        arr, _, _ = image_array(p)
        os.remove(p)
        parts.append(arr[..., :3])
    zoom, view = parts
    hh, ww = view.shape[:2]
    crop = view[hh // 2 - hh // 4: hh // 2 + hh // 4, ww // 2 - ww // 4: ww // 2 + ww // 4]
    crop = np.repeat(np.repeat(crop, 2, axis=0), 2, axis=1)[:hh, :ww]
    sep = np.ones((4, ww, 3), dtype=np.float32)
    save_array(np.concatenate([crop, sep, zoom], axis=0), path, quality=92, fmt="JPEG")
    bpy.data.scenes.remove(sc)
    for (me, si, m) in swaps:
        me.materials[si] = m
    for c in tmp_mats.values():
        bpy.data.materials.remove(c)
    log("lod compare -> %s" % path)


def cluster_lod(name, me0, lod2, target, rng, density=4.5):
    """LOD2 for crowns whose real leaves would have to grow absurdly to fill ~2k triangles
    (broadleaves): the decimated wood of `lod2` plus small leaf-cluster cards placed on LOD0's
    foliage (outer crown favoured, front faces outward, randomly spun), each showing the window of
    the LOD3 capture around its own position (shifted off the trunk), with the LOD3 crown normals.
    Shares the impostor material, so LOD2 -> LOD3 keeps the same colour and shading."""
    import numpy as np
    info = IMP_INFO[name]
    Wc, Hc = info["Wc"], info["Hc"]
    rw, rh = info["res"]
    fol = info["fol"].astype(np.float32)
    solid = info["solid"]
    folb = _box_blur(fol, 6)
    woodb = _box_blur((solid & ~info["fol"]).astype(np.float32), 4)
    hull = _box_blur(solid.astype(np.float32), 8) > 0.04
    a_hull = float(hull.sum()) * (Wc / rw) * (Hc / rh)
    key = "Impostor_" + name
    imp_mat = MATS[key]
    # wood only from the flattened LOD2
    mats = list(lod2.materials)
    wood_mi = [i for i, m in enumerate(mats) if m and not leafy(m)]
    bm = bmesh.new()
    bm.from_mesh(lod2)
    bmesh.ops.delete(bm, geom=[f for f in bm.faces if f.material_index not in wood_mi], context="FACES")
    # branch stubs high in the crown (hidden by leaves in LOD0, dark specks between cluster cards)
    zc_, rz_, rx_ = info["crown"]
    stubs = [f for f in bm.faces if f.calc_center_median().z > zc_ - 0.25 * rz_
             and math.hypot(f.calc_center_median().x, f.calc_center_median().y) > 0.3 * rx_]
    if stubs:
        bmesh.ops.delete(bm, geom=stubs, context="FACES")
    remap = {mi: j for j, mi in enumerate(wood_mi)}
    for f in bm.faces:
        f.material_index = remap[f.material_index]
    wood_tris = sum(len(f.verts) - 2 for f in bm.faces)
    n = max(150, (target - wood_tris) // 2)
    s = math.sqrt(density * a_hull / (0.6 * n))
    m0 = list(me0.materials)
    li0 = {i for i, m in enumerate(m0) if m and leafy(m)}
    polys = [p for p in me0.polygons if p.material_index in li0]
    C = np.array([tuple(p.center) for p in polys], dtype=np.float64)
    A = np.array([p.area for p in polys], dtype=np.float64)
    cc = C.mean(0)
    d = np.linalg.norm(C - cc, axis=1)
    wgt = A * (0.35 + (d / max(d.max(), 1e-6)) ** 2)
    nrng = np.random.default_rng(rng.randrange(1 << 30))
    idx = nrng.choice(len(polys), size=min(n, len(polys)), replace=False, p=wgt / wgt.sum())
    uvl = bm.loops.layers.uv.active or bm.loops.layers.uv.new("UVMap")
    imi = len(wood_mi)
    cards = []
    hu, hv = 0.71 * s / Wc, 0.71 * s / Hc        # spun square: half-diagonal
    for j in idx:
        p = Vector(C[j]) + Vector(tuple(nrng.normal(0.0, s * 0.15, 3)))
        yaw = nrng.uniform(0.0, math.pi)
        tilt = nrng.uniform(-0.6, 0.6)
        nrm = Vector((math.cos(yaw) * math.cos(tilt), math.sin(yaw) * math.cos(tilt), math.sin(tilt)))
        rad = p - Vector(tuple(cc))
        if nrm.dot(rad) < 0:
            nrm = -nrm
        right = Vector((0.0, 0.0, 1.0)).cross(nrm)
        if right.length < 1e-4:
            right = Vector((1.0, 0.0, 0.0))
        right.normalize()
        up = nrm.cross(right).normalized()
        # window centre: the card's own spot in the capture, nudged sideways off trunk and gaps
        best, bu = -1e9, 0.5
        for du in (0.0, -0.5, 0.5, -1.0, 1.0):
            uc = (p.x + du * s) / Wc + 0.5
            vc = p.z / Hc
            ix = int(np.clip(uc * rw, 0, rw - 1))
            iy = int(np.clip(vc * rh, 0, rh - 1))
            sc_ = folb[iy, ix] - 3.0 * woodb[iy, ix] - 0.05 * abs(du)
            if sc_ > best:
                best, bu = sc_, uc
        vc = min(max(p.z / Hc, hv), 1.0 - hv)
        bu = min(max(bu, hu), 1.0 - hu)
        flip = -1.0 if nrng.random() < 0.5 else 1.0
        spin = nrng.uniform(0.0, 2.0 * math.pi)
        cs_, sn_ = math.cos(spin), math.sin(spin)
        q = [(-1, -1), (1, -1), (1, 1), (-1, 1)]
        off = [((a * cs_ - b * sn_) * s / 2, (a * sn_ + b * cs_) * s / 2) for (a, b) in q]
        vs = [bm.verts.new(p + right * dx + up * dz) for (dx, dz) in off]
        f = bm.faces.new(vs)
        f.material_index = imi
        for lp, (dx, dz) in zip(f.loops, off):
            lp[uvl].uv = (bu + flip * dx / Wc, vc + dz / Hc)
        cards.append(f)
    out = tag(bpy.data.meshes.new("TMP_cluster"))
    bm.to_mesh(out)
    bm.free()
    for mi in wood_mi:
        out.materials.append(mats[mi])
    out.materials.append(imp_mat)
    check_mesh(out, "cluster lod")
    # cards share the LOD3 crown normal field (same material, same shading -> no step at LOD3)
    out.polygons.foreach_set("use_smooth", [True] * len(out.polygons))      # flat faces ignore custom normals
    out.calc_loop_triangles()
    vn = [tuple(pn.vector) for pn in out.vertex_normals]
    for poly in out.polygons:
        if poly.material_index == imi:
            for vi in poly.vertices:
                vn[vi] = crown_normal(out.vertices[vi].co, info["crown"])
    out.normals_split_custom_set_from_vertices(vn)
    log("cluster LOD2 %s: %d wood tris + %d cards of %.2f m (crown %.0f m2)" % (name, wood_tris, len(cards), s, a_hull))
    return out


def build_species(name):
    """Build the library meshes (LOD0..2, plus the LOD3 impostor where spec["imp"]) for one species /
    prop and cache them as
    models_src/prepared/VegLib_<name>.blend (one headless process per species)."""
    spec = VEG_SPECIES[name]
    t0 = time.time()
    rng = random.Random(RNG_SEED + sum(map(ord, name)))
    kind = spec["kind"]
    prop = kind in ("prop", "bench")
    if kind == "tree":
        src = append_mesh_copies(spec["asset"], [spec["obj"]])[0]
        dbg("veglib %s: source %d faces" % (name, len(src.polygons)))
        meshes = [reduce_tree(src, t, rng, flatten=(i > 0)) for i, t in enumerate(spec["tris"])]
        bpy.data.meshes.remove(src)
        base, _, _ = tree_metrics(meshes[0])
    elif kind == "lods":
        meshes = append_mesh_copies(spec["asset"], list(spec["objs"]))
        base = bottom_centre(meshes[0])
    elif kind == "rock":
        m01 = append_mesh_copies(spec["asset"], list(spec["objs"]))
        t1 = sum(len(p.vertices) - 2 for p in m01[1].polygons)
        meshes = m01 + [decimated_copy(m01[1], spec["dec"] / t1, name + " lod2")]
        base = bottom_centre(meshes[0])
        base = (base[0], base[1], base[2] + 0.12 * (max(v.co.z for v in meshes[0].vertices) - base[2]))
    elif kind == "prop":
        src = append_mesh_copies(spec["asset"], list(spec["objs"]))[0]
        t0_ = sum(len(p.vertices) - 2 for p in src.polygons)
        meshes = [src, decimated_copy(src, spec["dec"][0], name + " lod1"), decimated_copy(src, spec["dec"][1], name + " lod2")]
        base = bottom_centre(src)
    elif kind == "bench":
        meshes = build_bench_meshes(spec)
        base = (0.0, 0.0, 0.0)
    elif kind == "grate":
        meshes = build_grate_meshes()
        base = (0.0, 0.0, 0.0)
    elif kind == "hedge":
        meshes = build_hedge_meshes(spec)
        base = (0.0, 0.0, 0.0)
    else:
        raise ValueError(kind)
    recentre(meshes, base, spec.get("scale", 1.0))
    for i, me in enumerate(meshes):
        me.name = "VegLib_%s_LOD%d" % (name, i)
        tag(me)
        fix_tree_mesh(me, prop=prop)
        me.calc_loop_triangles()
    if kind == "tree":
        downscale_bark(meshes)
    if spec.get("tex", 2048) < 2048:
        downscale_images(meshes, spec["tex"])
    if kind == "tree":
        _, height, trunk_r = tree_metrics(meshes[0])
        trunk_r = max(0.12, min(trunk_r, 0.6))
    else:
        zs = [v.co.z for v in meshes[0].vertices]
        height = max(zs) - min(zs)
        trunk_r = spec.get("collider", 0.3)
    meshes[0]["height"] = height
    meshes[0]["trunk_r"] = trunk_r
    if spec.get("imp"):
        me3 = make_impostor(name, meshes[0], spec)
        me3.name = "VegLib_%s_LOD3" % name
        tag(me3)
        me3.calc_loop_triangles()
        meshes.append(me3)
        if kind == "tree" and float(meshes[2].get("card_scale", 1.0)) > 4.0:
            # real leaves would have to grow too much: leaf-cluster cards from the LOD3 capture
            old = meshes[2]
            meshes[2] = cluster_lod(name, meshes[0], old, spec["tris"][2], rng, spec.get("cdens", 4.5))
            bpy.data.meshes.remove(old)
            meshes[2].name = "VegLib_%s_LOD2" % name
            meshes[2].calc_loop_triangles()
        render_lod_compare(name, [meshes[0], meshes[2], meshes[3]],
                           os.path.join(WORK_DIR, "veglib", name + "_lod2_vs_lod3.jpg"),
                           hedge_len=spec["size"][0] if kind == "hedge" else None)
    for me in meshes:
        if "card_scale" in me:
            del me["card_scale"]
    os.makedirs(PREPARED_DIR, exist_ok=True)
    bpy.data.libraries.write(veglib_path(name), set(meshes), path_remap="ABSOLUTE", fake_user=False)
    tris = [len(m.loop_triangles) for m in meshes]
    log("veglib %s built in %.1fs: tris %s height %.2f r %.2f" % (name, time.time() - t0, tris, height, trunk_r))
    RESULTS["veglib " + name] = {"tris": tris, "height": round(height, 3), "r": round(trunk_r, 3),
                                 "textures": texture_sizes(meshes)}
    return meshes


def downscale_bark(meshes):
    """Trees keep 2K foliage atlases; bark and branch maps (non-foliage) go to 1K."""
    sub = []
    for me in meshes:
        for m in me.materials:
            if m and not leafy(m):
                sub.append(m)
    if not sub:
        return
    tmp = bpy.data.meshes.new("TMP_bark")
    for m in sub:
        tmp.materials.append(m)
    downscale_images([tmp], 1024)
    bpy.data.meshes.remove(tmp)


def texture_sizes(meshes):
    out = {}
    for me in meshes:
        for m in me.materials:
            if m and m.node_tree:
                for n in m.node_tree.nodes:
                    if n.type == "TEX_IMAGE" and n.image:
                        out[n.image.name] = list(n.image.size)
    return out


def load_species(name):
    p = veglib_path(name)
    if not os.path.isfile(p):
        return None
    want = ["VegLib_%s_LOD%d" % (name, i) for i in range(3)]
    with bpy.data.libraries.load(p, link=False) as (src, dst):
        if not all(w in src.meshes for w in want):
            return None
        if "VegLib_%s_LOD3" % name in src.meshes:
            want.append("VegLib_%s_LOD3" % name)
        dst.meshes = want
    meshes = list(dst.meshes)
    for me in meshes:
        check_mesh(me, me.name)
        tag(me)
        me.calc_loop_triangles()
        for m in me.materials:
            if m:
                tag(m)
                for n in m.node_tree.nodes:
                    if n.type == "TEX_IMAGE" and n.image:
                        tag(n.image)
    return meshes


def render_closeups(name, meshes, views, lods=None, ground=None):
    """Proof renders of a library model on paving under the project sky: eye-level (1.7 m) three-
    quarter close-ups ('frontleft', 'backright') and an orthographic 'front' view, per LOD, saved as
    _work/review/<name>_lod<i>_<view>.png (front = -Y side, the sitter's / viewer's side)."""
    d = os.path.join(WORK_DIR, "review")
    os.makedirs(d, exist_ok=True)
    out = []
    for i, me in enumerate(meshes):
        if lods is not None and i not in lods:
            continue
        sc = bpy.data.scenes.new(TMP_SCENE_PREFIX + "_closeup")
        ob = bpy.data.objects.new("TMP_cu", me)
        sc.collection.objects.link(ob)
        xs = [v.co.x for v in me.vertices]
        ys = [v.co.y for v in me.vertices]
        zs = [v.co.z for v in me.vertices]
        W, D, H = max(xs) - min(xs), max(ys) - min(ys), max(zs) - min(zs)
        c = Vector(((max(xs) + min(xs)) / 2, (max(ys) + min(ys)) / 2, (max(zs) + min(zs)) / 2))
        g = bpy.data.objects.new("TMP_cug", bpy.data.meshes.new("TMP_cug"))
        gz = min(zs) if ground is None else ground
        g.data.from_pydata([(-30, -30, gz), (30, -30, gz), (30, 30, gz), (-30, 30, gz)], [], [(0, 1, 2, 3)])
        g.data.materials.append(MATS.get("Paving_Concrete") or bpy.data.materials.get("Paving_Concrete"))
        sc.collection.objects.link(g)
        cd = bpy.data.cameras.new("TMP_cucam")
        cam = bpy.data.objects.new("TMP_cucam", cd)
        sc.collection.objects.link(cam)
        sc.camera = cam
        sc.world = ensure_preview_world()
        sc.render.engine = "CYCLES"
        enable_gpu(sc)
        sc.cycles.samples = 96
        sc.cycles.use_denoising = True
        sc.render.resolution_x, sc.render.resolution_y = 1400, 900
        sc.render.image_settings.file_format = "PNG"
        try:
            sc.view_settings.view_transform = "AgX"
        except TypeError:
            pass
        size = max(W, H, D)
        for v in views:
            if v == "front":
                cd.type = "ORTHO"
                cd.ortho_scale = max(W * 1.15, H * 1.15 * 1400 / 900)
                cam.location = (c.x, c.y - 30.0, c.z)
                cam.rotation_euler = (math.radians(90), 0.0, 0.0)
            else:
                cd.type = "PERSP"
                cd.lens = 35.0
                sgn = (-1.0, -1.0) if v == "frontleft" else (1.0, 1.0)
                dist = max(2.6, size * 1.35)
                cam.location = (c.x + sgn[0] * dist * 0.7, c.y + sgn[1] * dist * 0.75, max(min(zs), 0.0) + 1.7)
                look_at(cam, c)
            p = os.path.join(d, "%s_lod%d_%s.png" % (name.lower(), i, v))
            sc.render.filepath = p
            bpy.ops.render.render(write_still=True, scene=sc.name)
            out.append(p)
        bpy.data.scenes.remove(sc)
    log("closeups %s: %s" % (name, ", ".join(os.path.basename(p) for p in out)))
    return out


def render_lineup(name, meshes, path):
    """Small QA render of LOD0/1/2 side by side (Cycles, sky HDRI), in its own temp scene."""
    sc = bpy.data.scenes.new(TMP_SCENE_PREFIX + "_lineup")
    xs = 0.0
    dims = []
    for i, me in enumerate(meshes):
        ob = bpy.data.objects.new("TMP_l%d" % i, me)
        sc.collection.objects.link(ob)
        w = max(v.co.x for v in me.vertices) - min(v.co.x for v in me.vertices)
        h = max(v.co.z for v in me.vertices)
        dims.append((w, h))
    W = max(d[0] for d in dims) * 1.25 + 0.2
    H = max(d[1] for d in dims)
    for i, ob in enumerate([o for o in sc.collection.objects]):
        ob.location = ((i - 1) * W, 0.0, 0.0)
    g = bpy.data.objects.new("TMP_ground", bpy.data.meshes.new("TMP_ground"))
    gm = g.data
    gm.from_pydata([(-3 * W, -3 * W, 0), (3 * W, -3 * W, 0), (3 * W, 3 * W, 0), (-3 * W, 3 * W, 0)], [], [(0, 1, 2, 3)])
    gm.materials.append(MATS.get("Paving_Concrete") or bpy.data.materials.get("Paving_Concrete"))
    sc.collection.objects.link(g)
    cam = bpy.data.objects.new("TMP_cam", bpy.data.cameras.new("TMP_cam"))
    sc.collection.objects.link(cam)
    span = max(3 * W, H * 1.7)
    cam.location = (0.0, -span * 1.15, H * 0.55 + span * 0.12)
    look_at(cam, Vector((0, 0, H * 0.45)))
    cam.data.lens = 40
    sc.camera = cam
    sc.world = ensure_preview_world()
    sc.render.engine = "CYCLES"
    enable_gpu(sc)
    sc.cycles.samples = 40
    sc.cycles.use_denoising = True
    sc.render.resolution_x, sc.render.resolution_y = 1500, 600
    sc.render.image_settings.file_format = "JPEG"
    sc.render.filepath = path
    sc.view_settings.view_transform = "AgX" if "AgX" in [i.identifier for i in bpy.types.ColorManagedViewSettings.bl_rna.properties["view_transform"].enum_items] else "Filmic"
    bpy.ops.render.render(write_still=True, scene=sc.name)
    bpy.data.scenes.remove(sc)


# ---------------------------------------------------------------------------
# Planting design (own design): placements of the library models
# ---------------------------------------------------------------------------
def hard_at(x, y):
    """True on paving, paths, water, walls, courts or the building (no trees or shrubs there)."""
    S = SITE_SHAPES
    pin = point_in_poly
    if any(pin(x, y, p) for p in S["building"] + S["pools"] + S["paving_granite"] + S["axis_lanes"] + S["branches"]
           + S["prom_extra"] + S["trad_court"] + S["cont_court"] + S["gate"] + S["gate_complex"]):
        return True
    if math.hypot(x - FOUNTAIN[0], y - FOUNTAIN[1]) < PLAZA_R:
        return True
    if pin(x, y, S["prom_outer"][0]) and not pin(x, y, S["prom_inner"][0]):
        return True
    if pin(x, y, S["path_outer"][0]) and not pin(x, y, S["path_inner"][0]):
        return True
    if abs(y - GATE_Y) < 1.5:
        return True
    return not (SITE_X0 + 0.5 < x < SITE_X1 - 0.5 and SITE_Y0 + 0.5 < y < SITE_Y1 - 0.5)


def in_beds(x, y):
    S = SITE_SHAPES
    if any(point_in_poly(x, y, p) for p in S["beds"]):
        return True
    return any(point_in_poly(x, y, o) and not point_in_poly(x, y, i) for (o, i) in S["parterre_rings"])


def ground_z(x, y):
    off = Z_ARRIVAL_G if (y < GATE_Y and y >= SITE_Y0) else 0.0
    return off + ground_z0(x, y)


def ground_z0(x, y):
    if in_beds(x, y):
        return Z_BED
    if any(point_in_poly(x, y, p) for p in SITE_SHAPES["trad_court"] + SITE_SHAPES["cont_court"]):
        return Z_PAVE + 0.01
    if hard_at(x, y):
        return Z_PAVE
    if is_woodland(x, y):
        return Z_WOOD
    return Z_LAWN


class Planter:
    """Places library instances: spacing per layer (spatial hash), never the same species as the
    nearest canopy neighbour when there is a choice, +-25 % size, random yaw, tint; records
    vegetation.json rows, colliders and a preview object (LOD1, swapped by the review renders)."""

    def __init__(self, lib, instc):
        self.lib, self.instc = lib, instc
        self.grid = {}
        self.rng = random.Random(RNG_SEED + 99)
        self.count = 0

    def _key(self, layer, x, y):
        return (layer, int(math.floor(x / 6.0)), int(math.floor(y / 6.0)))

    def near(self, layer, x, y, rad):
        out = []
        cx, cy = int(math.floor(x / 6.0)), int(math.floor(y / 6.0))
        k = int(rad / 6.0) + 1
        for i in range(cx - k, cx + k + 1):
            for j in range(cy - k, cy + k + 1):
                for (px, py, pr, nm) in self.grid.get((layer, i, j), ()):
                    d = math.hypot(px - x, py - y)
                    if d < rad + pr:
                        out.append((d, nm))
        return out

    def free(self, layer, x, y, r):
        return not self.near(layer, x, y, r)

    def pick(self, choices, x, y, rad=9.0, layer="tree"):
        """Weighted choice avoiding the species of the nearest canopy neighbour."""
        nb = sorted(self.near(layer, x, y, rad))
        avoid = nb[0][1] if nb else None
        opts = [(n, w) for (n, w) in choices if n in self.lib and n != avoid] or [(n, w) for (n, w) in choices if n in self.lib]
        if not opts:
            return None
        t = self.rng.uniform(0, sum(w for _, w in opts))
        for n, w in opts:
            t -= w
            if t <= 0:
                return n
        return opts[-1][0]

    def put(self, name, x, y, z=None, yaw=None, s=None, sep=None, check_hard=None, collider=True, var=0.25,
            tint=None, layer=None):
        if name not in self.lib:
            return False
        spec = VEG_SPECIES[name]
        layer = layer or spec["layer"]
        sep = sep if sep is not None else {"tree": 3.0, "shrub": 0.9, "ground": 0.0, "rock": 1.0, "prop": 0.6,
                                           "hedge": 0.0, "flat": 0.0}[layer]
        if check_hard is None:
            check_hard = layer in ("tree", "shrub", "rock")
        if check_hard:
            rr = max(0.6, sep * 0.5)
            pts = [(x, y)] + [(x + rr * math.cos(a), y + rr * math.sin(a)) for a in (0, 1.57, 3.14, 4.71)]
            if any(hard_at(px, py) for (px, py) in pts):
                return False
        if sep > 0 and not self.free(layer, x, y, sep * 0.5):
            return False
        rng = self.rng
        s = s if s is not None else rng.uniform(1.0 - var, 1.0 + var)
        yaw = yaw if yaw is not None else rng.uniform(0, 2 * math.pi)
        tint = tint if tint is not None else rng.random()
        if z is not None and y < GATE_Y and SITE_Y0 <= y and SITE_X0 <= x <= SITE_X1:
            z += Z_ARRIVAL_G
        z = z if z is not None else ground_z(x, y) - (0.02 if layer in ("tree", "shrub", "ground") else 0.0)
        VEG_INSTANCES.setdefault(name, []).append((x, y, z, yaw, s, tint))
        self.grid.setdefault(self._key(layer, x, y), []).append((x, y, sep * 0.5, name))
        n = len(VEG_INSTANCES[name])
        ob = bpy.data.objects.new("Inst_%s_%04d" % (name, n), self.lib[name][1])
        ob.location = (x, y, z)
        ob.rotation_euler = (0, 0, yaw)
        ob.scale = (s, s, s)
        self.instc.objects.link(ob)
        self.count += 1
        if collider and layer in ("tree", "shrub", "rock", "prop"):
            r = VEG_META[name]["trunk_r"] * s if layer == "tree" else spec.get("collider", 0.5) * s
            CIRCLES.append(("veg-%s-%04d" % (name.lower(), n), x, y, round(r, 2)))
            if name == "Bench":
                TOPY[CIRCLES[-1][0]] = z + 0.87
            elif layer == "rock":
                TOPY[CIRCLES[-1][0]] = z + 0.88 * VEG_META[name]["height"] * s
        return True

    def hedge_run(self, name, x0, y0, x1, y1, z=None):
        """Clipped hedge modules (2 m) end to end along a straight run, one box collider."""
        L = math.hypot(x1 - x0, y1 - y0)
        if L < 0.8 or name not in self.lib:
            return
        n = max(1, int(round(L / 2.0)))
        st = L / n
        yaw = math.atan2(y1 - y0, x1 - x0)
        for k in range(n):
            t = (k + 0.5) / n
            self.put(name, x0 + (x1 - x0) * t, y0 + (y1 - y0) * t, z=z, yaw=yaw + (math.pi if k % 2 else 0.0),
                     s=st / 2.0, collider=False, check_hard=False, tint=0.45 + 0.1 * self.rng.random())
        W = VEG_SPECIES[name]["size"][1] / 2 + 0.05
        zt = (z if z is not None else ground_z0(x0, y0)) + (Z_ARRIVAL_G if y0 < GATE_Y else 0.0) + \
            VEG_SPECIES[name]["size"][2] * st / 2.0
        if abs(x1 - x0) < 1e-3 or abs(y1 - y0) < 1e-3:
            BOXES.append(("hedge-%d" % (len(BOXES) + 1), min(x0, x1) - W, max(x0, x1) + W, min(y0, y1) - W, max(y0, y1) + W))
            TOPY[BOXES[-1][0]] = zt
        else:
            for k in range(n + 1):
                t = k / n
                CIRCLES.append(("hedge-%d-%d" % (len(BOXES), k), x0 + (x1 - x0) * t, y0 + (y1 - y0) * t, round(W + 0.1, 2)))
                TOPY[CIRCLES[-1][0]] = zt

    def hedge_ring(self, name, cx, cy, r, z=None):
        n = max(6, int(round(2 * math.pi * r / 2.0)))
        st = 2 * math.pi * r / n
        for k in range(n):
            a = 2 * math.pi * (k + 0.5) / n
            self.put(name, cx + r * math.cos(a), cy + r * math.sin(a), z=z, yaw=a + math.pi / 2, s=st / 2.0,
                     collider=False, tint=0.45 + 0.1 * self.rng.random())
            CIRCLES.append(("hedge-ring-%d" % (len(CIRCLES) + 1), cx + r * math.cos(a), cy + r * math.sin(a),
                            round(VEG_SPECIES[name]["size"][1] / 2 + 0.15, 2)))

    def row(self, name, x0, y0, x1, y1, pitch, z=None, jitter=0.06, var=0.18):
        L = math.hypot(x1 - x0, y1 - y0)
        n = max(1, int(L / pitch))
        for k in range(n + 1):
            t = k / n if n else 0.5
            self.put(name, x0 + (x1 - x0) * t + self.rng.uniform(-jitter, jitter),
                     y0 + (y1 - y0) * t + self.rng.uniform(-jitter, jitter), z=z, var=var, collider=False,
                     check_hard=False)

    def drift(self, name, cx, cy, n, rad, z=None, var=0.25, minsep=0.5):
        placed = 0
        for _ in range(n * 4):
            if placed >= n:
                break
            a = self.rng.uniform(0, 2 * math.pi)
            d = rad * math.sqrt(self.rng.random())
            x, y = cx + d * math.cos(a), cy + d * math.sin(a)
            if hard_at(x, y) or self.near("ground", x, y, minsep * 0.5):
                continue
            if self.put(name, x, y, z=z, var=var, sep=minsep, check_hard=False, collider=False):
                placed += 1


def poly_samples(poly, n, rng, sep, extra_ok=None):
    xs = [p[0] for p in poly]
    ys = [p[1] for p in poly]
    out = []
    tries = 0
    while len(out) < n and tries < n * 60:
        tries += 1
        x, y = rng.uniform(min(xs), max(xs)), rng.uniform(min(ys), max(ys))
        if not point_in_poly(x, y, poly):
            continue
        if any(math.hypot(x - a, y - b) < sep for (a, b) in out):
            continue
        if extra_ok and not extra_ok(x, y):
            continue
        out.append((x, y))
    return out


def rect_ring_points(off, step, y_lo, phase=0.0):
    """Points along a rectangle inset `off` from the inner-zone edges (site sides/back, wall)."""
    x0, x1 = SITE_X0 + off, SITE_X1 - off
    y0, y1 = y_lo + off, SITE_Y1 - off
    w, h = x1 - x0, y1 - y0
    per = 2 * (w + h)
    s = phase
    while s < per:
        if s < w:
            yield x0 + s, y0
        elif s < w + h:
            yield x1, y0 + (s - w)
        elif s < 2 * w + h:
            yield x1 - (s - w - h), y1
        else:
            yield x0, y1 - (s - 2 * w - h)
        s += step


def plant_design(P):
    rng = P.rng
    fx, fy = FOUNTAIN
    sw = STAIR_HW + CHEEK_W
    S = SITE_SHAPES
    TALL = [("PineTall", 4), ("Pine", 3), ("Broadleaf", 3)]
    MID = [("Searsia", 3), ("Gnarled", 2), ("Pine", 2), ("Broadleaf", 1)]
    SHRUBS = [("SearsiaShrub", 3), ("ConiferShrub", 2)]
    # 1 foot of the building: continuous low clipped hedge, shrubs in front, white flowers in the
    #   front beds either side of the grand stairs
    y = -POD_HY - 1.0
    for sx in (-1, 1):
        a, b = sorted((sx * (POD_HX - 0.6), sx * (sw + 0.8)))
        P.hedge_run("HedgeLow", a, y, b, y, z=Z_BED - 0.02)
        x = a + 4.5
        while x < b - 2.0:
            P.put("SearsiaShrub", x, -POD_HY - 2.15, z=Z_BED - 0.02, sep=1.0, check_hard=False, var=0.15)
            P.drift("FlowerWhite", x + 4.5, -POD_HY - 2.2, 6, 0.75, z=Z_BED - 0.01)
            x += 9.0
        xs = POD_HX + 1.0
        P.hedge_run("HedgeLow", sx * xs, -POD_HY + 0.6, sx * xs, POD_HY - 0.6, z=Z_BED - 0.02)
        yy = -POD_HY + 4.5
        while yy < POD_HY - 2.0:
            P.put("SearsiaShrub", sx * (POD_HX + 2.2), yy, z=Z_BED - 0.02, sep=1.0, check_hard=False, var=0.15)
            yy += 9.0
    P.hedge_run("HedgeLow", -POD_HX + 0.6, POD_HY + 1.0, POD_HX - 0.6, POD_HY + 1.0, z=Z_BED - 0.02)
    x = -POD_HX + 4.5
    while x < POD_HX - 2.0:
        P.put("SearsiaShrub", x, POD_HY + 2.2, z=Z_BED - 0.02, sep=1.0, check_hard=False, var=0.15)
        x += 9.0
    # 3 forecourt edge beds: low hedge with an orange flower row in front
    for sx in (-1, 1):
        a, b = sorted((sx * 24.6, sx * 81.4))
        P.hedge_run("HedgeLow", a, FORECOURT_Y - 3.6, b, FORECOURT_Y - 3.6, z=Z_BED - 0.02)
        P.row("FlowerOrange", a + 0.3, FORECOURT_Y - 5.1, b - 0.3, FORECOURT_Y - 5.1, 1.05, z=Z_BED - 0.01)
    # 4 parterres beside the pool walks: low hedge frame, two flower strips (white, pink, orange,
    #   pink, white rows), rounded shrubs at the inner corners, lawn panel between
    for (x0, y0, x1, y1) in S["parterre_panels"]:
        i0, i1 = x0 + 0.5, x1 - 0.5
        j0, j1 = y0 + 0.5, y1 - 0.5
        for (ax, ay, bx, by) in ((i0, j0, i1, j0), (i0, j1, i1, j1), (i0, j0 + 1.0, i0, j1 - 1.0), (i1, j0 + 1.0, i1, j1 - 1.0)):
            P.hedge_run("HedgeLow", ax, ay, bx, by, z=Z_BED - 0.02)
        inner = x0 if abs(x0) < abs(x1) else x1
        sgn = 1.0 if inner > 0 else -1.0
        for (u0, u1) in (PARTERRE_STRIP,):
            a0 = inner + sgn * u0
            rows = [(0.22, "FlowerWhite", 0.3), (0.55, "FlowerPink", 0.32), (0.87, "FlowerPink", 0.32),
                    (1.25, "FlowerOrange", 0.42), (1.75, "FlowerOrange", 0.42), (2.13, "FlowerPink", 0.32),
                    (2.45, "FlowerPink", 0.32), (2.78, "FlowerWhite", 0.3)]
            for (off, nm, pitch) in rows:
                xr = a0 + sgn * off
                P.row(nm, xr, y0 + 2.6, xr, y1 - 2.6, pitch, z=Z_BED - 0.01, jitter=0.05)
        for (cx_, cy_) in ((x0 + 2.0, y0 + 2.0), (x1 - 2.0, y0 + 2.0), (x0 + 2.0, y1 - 2.0), (x1 - 2.0, y1 - 2.0)):
            P.put("SearsiaShrub", cx_, cy_, z=Z_LAWN - 0.02, sep=1.0, check_hard=False, var=0.1)
    # 5 avenue of tall pines leading the eye along the axis (rows outside the parterres)
    for sx in (-1, 1):
        y = fy + PLAZA_R + 2.0
        while y < FORECOURT_Y - 3.0:
            if not any(a - 2.5 < y < b + 2.5 for (a, b) in CROSS_Y):
                P.put("PineTall", sx * AVENUE_X, y, s=rng.uniform(1.02, 1.12), sep=4.0)
                P.put("Broadleaf", sx * (AVENUE_X + 7.0), y + 5.0, s=rng.uniform(1.0, 1.1), sep=5.0)
            y += 10.0
    # 6 trees along the outer side of the promenade loop (broadleaf with lower searsia between)
    for sx in (-1, 1):
        y = RO_Y0 + 12.0
        while y < RO_Y1 - 8.0:
            P.put("Broadleaf", sx * (RO_X + 4.5), y, var=0.15, sep=6.0)
            P.put("Searsia", sx * (RO_X + 3.6), y + 7.0, var=0.2, sep=4.0)
            y += 14.0
    x = -RO_X + 12.0
    while x < RO_X - 10.0:
        P.put("Broadleaf", x, RO_Y1 + 4.5, var=0.15, sep=6.0)
        P.put("Searsia", x + 7.0, RO_Y1 + 3.6, var=0.2, sep=4.0)
        x += 14.0
    # 7 formal bosquet in grated pits on the forecourt flanks
    for (x, y) in TREE_PITS:
        P.put("Broadleaf", x, y, z=-0.06, var=0.06, sep=3.0, check_hard=False)
        P.put("TreeGrate", x, y, z=Z_PAVE, yaw=0.0, s=1.0, collider=False, check_hard=False)
    # 8 specimen trees at the edges of the open front lawns (the panels themselves stay open)
    for (x, y, nm) in ((52, -140, "Gnarled"), (96, -146, "Pine"), (64, -276, "Gnarled"), (100, -262, "Pine"),
                       (104, -200, "Gnarled"), (84, -150, "SearsiaShrub")):
        for sx in (-1, 1):
            P.put(nm, sx * x, y, var=0.12, sep=4.0)
    # 9 groves: mixed canopy, shrubs beneath, ferns and grasses, a few rocks; glades between
    themes = [TALL, MID, [("Pine", 4), ("Gnarled", 2), ("Searsia", 1)], [("Broadleaf", 3), ("Searsia", 2), ("Gnarled", 2)]]
    for gi, poly in enumerate(S["groves"][:len(GROVES)]):
        gx, gy, gr = GROVES[gi]
        area = math.pi * gr * gr
        th = themes[gi % len(themes)]
        for (x, y) in poly_samples(poly, int(area / 70.0) + 2, rng, 6.0):
            nm = P.pick(th, x, y)
            if nm:
                P.put(nm, x, y, sep=4.5)
        for (x, y) in poly_samples(poly, int(area / 90.0) + 2, rng, 3.0,
                                   extra_ok=lambda x, y: math.hypot(x - gx, y - gy) > gr * 0.55):
            nm = P.pick(SHRUBS, x, y, layer="shrub")
            if nm:
                P.put(nm, x, y)
        for k in range(3):
            a = rng.uniform(0, 2 * math.pi)
            P.drift("Fern", gx + gr * 0.45 * math.cos(a), gy + gr * 0.45 * math.sin(a), 9, 3.0)
        for k in range(2):
            a = rng.uniform(0, 2 * math.pi)
            P.drift("Grass", gx + gr * 0.8 * math.cos(a), gy + gr * 0.8 * math.sin(a), 6, 2.2, minsep=0.8)
        for k in range(rng.randint(1, 3)):
            a = rng.uniform(0, 2 * math.pi)
            P.put(rng.choice(["Boulder", "Boulder", "BoulderLarge"]), gx + gr * 0.75 * math.cos(a),
                  gy + gr * 0.75 * math.sin(a), var=0.3, sep=2.0)
    # 10 layered perimeter belt inside the wall/site edge: tall at the back, medium, shrubs in
    #    front, fern and grass drifts at the front edge
    for (off, step, ch, sep) in ((3.0, 6.5, TALL, 4.2), (11.5, 6.5, TALL, 4.2), (15.5, 6.5, TALL, 4.2), (19.5, 6.0, MID, 3.6)):
        for (x, y) in rect_ring_points(off, step, INNER_Y0, phase=rng.uniform(0, step)):
            x += rng.uniform(-1.0, 1.0)
            y += rng.uniform(-1.0, 1.0)
            if not is_woodland(x, y):
                continue
            nm = P.pick(ch, x, y)
            if nm:
                P.put(nm, x, y, sep=sep)
    for (x, y) in rect_ring_points(23.5, 4.0, INNER_Y0, phase=1.0):
        x += rng.uniform(-1.2, 1.2)
        y += rng.uniform(-1.2, 1.2)
        if is_woodland(x, y):
            nm = P.pick(SHRUBS, x, y, layer="shrub")
            if nm:
                P.put(nm, x, y)
    for i, (x, y) in enumerate(rect_ring_points(25.5, 22.0, INNER_Y0, phase=5.0)):
        if is_woodland(x, y):
            P.drift("Fern" if i % 3 else "Grass", x, y, 8, 2.5)
    # 10b outer tree mass all round, beyond the site edge, and scattered groups further out
    OUT = [("PineTall", 3), ("Pine", 4), ("Broadleaf", 3), ("Searsia", 1), ("Gnarled", 1)]
    for (off, step) in ((5.0, 7.0), (11.5, 7.5), (18.0, 8.0), (25.0, 8.5), (33.0, 9.5), (42.0, 11.0)):
        x0, x1, y0, y1 = SITE_X0 - off, SITE_X1 + off, SITE_Y0 - off, SITE_Y1 + off
        w, h = x1 - x0, y1 - y0
        sp = rng.uniform(0, step)
        while sp < 2 * (w + h):
            if sp < w:
                x, y = x0 + sp, y0
            elif sp < w + h:
                x, y = x1, y0 + sp - w
            elif sp < 2 * w + h:
                x, y = x1 - (sp - w - h), y1
            else:
                x, y = x0, y1 - (sp - 2 * w - h)
            x += rng.uniform(-2.0, 2.0)
            y += rng.uniform(-2.0, 2.0)
            if not (abs(x) < APPROACH_HW + 4.0 and y < SITE_Y0):
                nm = P.pick(OUT, x, y)
                if nm:
                    P.put(nm, x, y, z=surround_z(x, y) - 0.03, sep=4.0, check_hard=False, collider=False)
            sp += step
    for k in range(90):
        a_ = 2 * math.pi * k / 90 + rng.uniform(-0.03, 0.03)
        R_ = rng.uniform(55.0, 260.0)
        cx_ = (SITE_X0 + SITE_X1) / 2 + math.cos(a_) * ((SITE_X1 - SITE_X0) / 2 + R_)
        cy_ = (SITE_Y0 + SITE_Y1) / 2 + math.sin(a_) * ((SITE_Y1 - SITE_Y0) / 2 + R_)
        if abs(cx_) < 60 and cy_ < SITE_Y0:
            continue
        for j in range(rng.randint(4, 8)):
            x, y = cx_ + rng.gauss(0, 7), cy_ + rng.gauss(0, 7)
            nm = P.pick(OUT, x, y)
            if nm:
                P.put(nm, x, y, z=surround_z(x, y) - 0.03, sep=4.5, check_hard=False, collider=False)
    # 11 arrival zone: double avenue along the approach (clear of the gate's sight line), pines
    #    framing the arrival forecourt, layered belts at the outer edges
    for (xo, ph) in ((APPROACH_HW + 5.5, 0.0), (APPROACH_HW + 12.0, 5.0)):
        y = SITE_Y0 + 12.0 + ph
        while y < ARRIVAL[1] - 4.0:
            for sx in (-1, 1):
                P.put("Broadleaf", sx * xo, y, s=rng.uniform(0.98, 1.1), sep=5.0)
            y += 10.0
    for sx in (-1, 1):
        P.hedge_run("HedgeTall", sx * (APPROACH_HW + 1.3), SITE_Y0 + 3.6, sx * (APPROACH_HW + 1.3), ARRIVAL[1] - 1.6,
                    z=Z_BED - 0.02)
        P.hedge_run("HedgeTall", sx * 21.3, GATE_Y + GATE_BACK + 2.2, sx * 21.3, FOUNTAIN[1] - 3.6, z=Z_BED - 0.02)
        P.hedge_run("HedgeTall", sx * (PACK_HX + 1.0), GATE_Y - 33.4, sx * (PACK_HX + 1.0), GATE_Y - 1.2, z=Z_BED - 0.02)
    for (x, y) in ARRIVAL_PITS:
        P.put("Broadleaf", x, y, z=-0.06, s=rng.uniform(0.95, 1.05), sep=3.0, check_hard=False)
        P.put("TreeGrate", x, y, z=Z_PAVE, yaw=0.0, s=1.0, collider=False, check_hard=False)
    # lamp rows along the three approach lines in the arrival forecourt
    y = GATE_Y - GATE_FRONT - 4.0
    while y > ARRIVAL[1] + 3.0:
        for xl in (-12.0, -4.6, 4.6, 12.0):
            P.put("Lamp", xl, y, z=Z_PAVE, s=1.0, check_hard=False)
        y -= 14.0
    for sx in (-1, 1):
        for (x, y) in ((52.0, GATE_Y - 6.0), (58.0, GATE_Y - 16.0), (50.0, ARRIVAL[1] + 4.0)):
            P.put("Pine", sx * x, y, var=0.12, sep=5.0)
    for poly in S["arrival_belts"]:
        for (x, y) in poly_samples(poly, int(abs(signed_area(poly)) / 75.0), rng, 6.0):
            nm = P.pick(TALL + MID, x, y)
            if nm:
                P.put(nm, x, y, sep=4.5)
    # 12 traditional garden: dark pine backdrop behind the retaining wall, pines and shrubs on the
    #    flanks, periwinkle and fern ground cover along the court edges, two benches facing the
    #    pagodas, two discreet lamps at the entrance
    t = TRAD
    bx0 = t["cx"] + t["hx"] + 1.6
    for (dx, dy, nm) in ((3.5, -10.0, "Pine"), (6.5, -3.0, "PineTall"), (3.0, 3.5, "Pine"), (7.0, 10.0, "Pine"),
                         (9.5, -14.0, "PineTall"), (9.0, 15.0, "Pine")):
        P.put(nm, bx0 + dx, t["cy"] + dy, var=0.12, sep=4.0, check_hard=False)
    for k in range(7):
        P.put(rng.choice(["ConiferShrub", "SearsiaShrub"]), bx0 + 0.6, t["cy"] - t["hy"] + 1.5 + k * 3.3, sep=1.5,
              check_hard=False)
    for k in range(9):
        P.put("Pine" if k % 3 else "PineTall", bx0 + 5.0 + (k % 2) * 3.0, t["cy"] - 16.0 + k * 4.0, var=0.15, sep=3.0,
              check_hard=False)
        P.put("SearsiaShrub" if k % 2 else "ConiferShrub", bx0 + 2.6, t["cy"] - 14.0 + k * 3.5, sep=1.4,
              check_hard=False)
    for sy in (-1, 1):
        ys = t["cy"] + sy * (t["hy"] + 4.0)
        for k, dx in enumerate((-10.0, -2.0, 7.0)):
            P.put("Pine" if k != 1 else "PineTall", t["cx"] + dx, ys + sy * rng.uniform(0.0, 1.5), var=0.12, sep=4.0,
                  check_hard=False)
        P.row("FlowerPink", t["cx"] - t["hx"] - 0.5, t["cy"] + sy * (t["hy"] + 1.3), t["cx"] + t["hx"] + 0.5,
              t["cy"] + sy * (t["hy"] + 1.3), 0.4, z=Z_WOOD - 0.01, jitter=0.12)
        P.drift("Fern", t["cx"] + 2.0, t["cy"] + sy * (t["hy"] + 2.5), 14, 4.0)
    P.row("Fern", bx0 + 0.1, t["cy"] - t["hy"], bx0 + 0.1, t["cy"] + t["hy"], 1.2, z=Z_WOOD - 0.01, jitter=0.2)
    for sy in (-1, 1):
        P.put("Bench", t["cx"] - 9.0, t["cy"] + sy * 4.2, z=Z_PAVE + 0.01, yaw=math.pi / 2, s=1.0, check_hard=False)
        P.put("Lamp", t["cx"] - t["hx"] + 0.8, t["cy"] + sy * 6.2, z=Z_PAVE + 0.01, s=1.0, check_hard=False)
    # 13 contemporary garden: pine-and-rock composition in fine gravel, drifts of ornamental
    #    grass, a granite seating terrace with benches facing it
    c = CONT
    for (dx, dy, nm, sc) in ((4.0, -4.0, "BoulderLarge", 1.25), (10.0, 8.0, "BoulderLarge", 1.0), (7.0, -10.0, "BoulderLarge", 0.8),
                             (2.5, 2.0, "Boulder", 1.1), (12.5, -2.0, "Boulder", 0.9), (9.0, 1.5, "Boulder", 0.7),
                             (5.5, 9.5, "Boulder", 0.8), (13.0, -9.5, "Boulder", 1.0), (0.5, -9.0, "Boulder", 0.6)):
        P.put(nm, c["cx"] + dx, c["cy"] + dy, z=Z_PAVE + 0.01, s=sc, sep=1.0, check_hard=False)
    for (dx, dy, nm) in ((2.0, 6.5, "Pine"), (11.0, -6.5, "Pine"), (13.5, 10.5, "ConiferShrub"), (-1.0, -11.0, "ConiferShrub"),
                         (6.0, 11.5, "SearsiaShrub"), (14.0, 3.0, "ConiferShrub"), (8.0, -12.0, "SearsiaShrub")):
        P.put(nm, c["cx"] + dx, c["cy"] + dy, z=Z_PAVE, var=0.12, sep=1.5, check_hard=False)
    for k in range(9):
        a = -1.2 + k * 0.33
        P.drift("Grass", c["cx"] + 7.0 + 6.0 * math.cos(a), c["cy"] + 6.0 * math.sin(a), 6, 1.3, z=Z_PAVE, minsep=0.7)
    for sy in (-1, 1):
        P.put("Bench", c["cx"] - c["hx"] + 10.5, c["cy"] + sy * 3.2, z=Z_PAVE, yaw=math.pi / 2, s=1.0, check_hard=False)
        P.put("Lamp", c["cx"] - c["hx"] + 0.8, c["cy"] + sy * 5.3, z=Z_PAVE, s=1.0, check_hard=False)
    for k in range(4):
        P.put(rng.choice(["Pine", "PineTall"]), c["cx"] - 10.0 + k * 7.0, c["cy"] + c["hy"] + 3.5, var=0.12, sep=4.0,
              check_hard=False)
    # 14 seating and lamps: fountain plaza, pool walks, forecourt, promenade, ring path, arrival
    for k, adeg in enumerate((0, 45, 135, 180, 225, 315)):
        a = math.radians(adeg)
        P.put("Bench", fx + 16.0 * math.cos(a), fy + 16.0 * math.sin(a), z=Z_PAVE, yaw=a - math.pi / 2, s=1.0,
              check_hard=False)
    for k in (0, 3, 4, 7):
        a = math.radians(22.5 + 45 * k)
        P.put("Lamp", fx + 19.0 * math.cos(a), fy + 19.0 * math.sin(a), z=Z_PAVE, s=1.0, check_hard=False)
    for sx in (-1, 1):
        for (y0, y1) in POOL_SEGS:
            ym = (y0 + y1) / 2
            for dy in (-7.0, 7.0):
                P.put("Bench", sx * (WALK_X1 - 0.55), ym + dy, z=Z_PAVE, yaw=-sx * math.pi / 2, s=1.0, check_hard=False)
            for yl in (y0 + 1.5, ym, y1 - 1.5):
                P.put("Lamp", sx * (WALK_X1 - 0.4), yl, z=Z_PAVE, s=1.0, check_hard=False)
    for x in (24.0, 48.0, 72.0, 96.0):
        for sx in (-1, 1):
            P.put("Lamp", sx * x, FORECOURT_Y + 1.0, z=Z_PAVE, s=1.0, check_hard=False)
    # promenade: lamps every ~30 m at its inner edge
    prom_pts = []
    xi0, xi1, yi0, yi1 = -RI_X - 0.5, RI_X + 0.5, RI_Y0 - 0.5, RI_Y1 + 0.5
    w, h = xi1 - xi0, yi1 - yi0
    s_ = 6.0
    while s_ < 2 * (w + h):
        if s_ < w:
            p = (xi0 + s_, yi0)
        elif s_ < w + h:
            p = (xi1, yi0 + s_ - w)
        elif s_ < 2 * w + h:
            p = (xi1 - (s_ - w - h), yi1)
        else:
            p = (xi0, yi1 - (s_ - 2 * w - h))
        prom_pts.append(p)
        s_ += 30.0
    for i, (x, y) in enumerate(prom_pts):
        if abs(x) < 26 and y < -200:
            continue
        P.put("Lamp", x, y, z=Z_PAVE, s=1.0, check_hard=False)
    # ring path seating niches on the side runs: bench on the woodland edge facing the path, lamp
    for sx in (-1, 1):
        for y in (-240.0, -150.0, -80.0, 10.0, 80.0):
            x = sx * 196.4
            P.put("Bench", x, y, z=Z_WOOD, yaw=sx * math.pi / 2, s=1.0, check_hard=False)
            P.put("Lamp", x, y + 2.2, z=Z_WOOD, s=1.0, check_hard=False)
    # arrival: lamps along the approach and the forecourt sides, benches facing the gate
    y = SITE_Y0 + 10.0
    while y < ARRIVAL[3] - 8.0:
        for sx in (-1, 1):
            xl = sx * (APPROACH_HW - 0.8) if y < ARRIVAL[1] else sx * (ARRIVAL[2] - 0.8)
            P.put("Lamp", xl, y, z=Z_PAVE, s=1.0, check_hard=False)
        y += 20.0
    for sx in (-1, 1):
        for y in (ARRIVAL[1] + 16.0, ARRIVAL[1] + 30.0):
            P.put("Bench", sx * (ARRIVAL[2] - 1.6), y, z=Z_PAVE, yaw=-sx * math.pi / 2, s=1.0, check_hard=False)


def build_vegetation(coll):
    """Library objects VegLib_* (exported, one per LOD), placements (VEG_INSTANCES ->
    vegetation.json), preview instances (not exported) and colliders."""
    root = bpy.context.scene.collection
    libc = tag(bpy.data.collections.new(COLL_VEGLIB))
    instc = tag(bpy.data.collections.new(COLL_VEGINST))
    root.children.link(libc)
    root.children.link(instc)
    lib = {}
    missing = []
    for name, spec in VEG_SPECIES.items():
        meshes = load_species(name)
        if meshes is None:
            missing.append(name)
            continue
        lib[name] = meshes
        VEG_META[name] = {"height": round(float(meshes[0].get("height", 1.0)), 3),
                          "trunk_r": round(float(meshes[0].get("trunk_r", 0.3)), 3),
                          "tris": [len(m.loop_triangles) for m in meshes], "file": spec["file"],
                          "lod": list(spec.get("lod", LOD_DISTANCES))[:len(meshes) - 1]}
        for me in meshes:
            ob = bpy.data.objects.new(me.name, me)
            libc.objects.link(ob)
            ob.hide_render = True
    if missing:
        log("WARNING library species missing (run --stage veglib --species ...):", missing)
    RESULTS["veg_missing"] = missing
    # one copy of each shared material (several caches append duplicates of the same asset)
    for meshes in lib.values():
        for me in meshes:
            for i, m in enumerate(me.materials):
                if m and "." in m.name and m.name.rsplit(".", 1)[1].isdigit():
                    base = bpy.data.materials.get(m.name.rsplit(".", 1)[0])
                    if base is not None and base is not m:
                        me.materials[i] = base
    VEG_INSTANCES.clear()
    P = Planter(lib, instc)
    plant_design(P)
    log("instances", {k: len(v) for k, v in VEG_INSTANCES.items()}, "total", P.count)
    bpy.context.scene["na_veg"] = json.dumps({"instances": VEG_INSTANCES, "meta": VEG_META})
    return []


# ---------------------------------------------------------------------------


# Ambient occlusion bake (building) -> glTF occlusion texture on texCoord 1
# ---------------------------------------------------------------------------
def enable_gpu(scene):
    """Cycles on the GPU for THIS headless process only (preferences are never saved)."""
    if not HEADLESS:
        return None
    try:
        prefs = bpy.context.preferences
        prefs.use_preferences_save = False
        cp = prefs.addons["cycles"].preferences
        for t in ("OPTIX", "CUDA"):
            try:
                cp.compute_device_type = t
            except TypeError:
                continue
            cp.get_devices()
            ok = False
            for d in cp.devices:
                d.use = (d.type == t)
                ok = ok or d.use
            if ok:
                scene.cycles.device = "GPU"
                return t
    except Exception as e:
        log("GPU setup failed, using CPU:", e)
    scene.cycles.device = "CPU"
    return None


def bake_building_ao():
    # Large surfaces only: window frames and lattice bars are tens of thousands of tiny pieces
    # that would swamp the atlas, so they keep plain materials (no baked occlusion).
    skip = ("Window_Frames", "Lattice_Bronze", "Interior_Shell")
    objs = [o for o in bpy.data.collections[COLL_BUILDING].objects if o.type == "MESH" and o.name not in skip]
    scene = bpy.context.scene
    vl = bpy.context.view_layer
    for o in objs:
        uvs = o.data.uv_layers
        if "UV_AO" not in uvs:
            uvs.new(name="UV_AO")
        uvs["UVMap"].active_render = True
        uvs.active = uvs["UV_AO"]
    for o in vl.objects:
        o.select_set(False)
    for o in objs:
        o.select_set(True)
    vl.objects.active = objs[0]
    t0 = time.time()
    # multi-object edit mode: smart project + pack puts every building object into one atlas
    bpy.ops.object.mode_set(mode="EDIT")
    bpy.ops.mesh.select_all(action="SELECT")
    bpy.ops.uv.smart_project(angle_limit=math.radians(60.0), island_margin=0.001, area_weight=0.0,
                             correct_aspect=True, scale_to_bounds=False)
    try:
        bpy.ops.uv.pack_islands(margin=0.001, rotate=True)
    except TypeError:
        bpy.ops.uv.pack_islands(margin=0.001)
    bpy.ops.object.mode_set(mode="OBJECT")
    log("lightmap UVs in %.1fs" % (time.time() - t0))
    img = bpy.data.images.get("NA_BuildingAO")
    if img is not None:
        bpy.data.images.remove(img)
    img = tag(bpy.data.images.new("NA_BuildingAO", AO_SIZE, AO_SIZE, alpha=False, float_buffer=False))
    img.colorspace_settings.name = "Non-Color"
    mats = {m for o in objs for m in o.data.materials if m}
    nodes = {}
    for m in mats:
        n = m.node_tree.nodes.new("ShaderNodeTexImage")
        n.image = img
        n["na_bake"] = 1
        m.node_tree.nodes.active = n
        nodes[m] = n
    old_engine = scene.render.engine
    try:
        scene.render.engine = "CYCLES"
    except TypeError as e:
        raise RuntimeError("Cycles not available for the AO bake: %s" % e)
    cy = scene.cycles
    old = (cy.samples, getattr(cy, "use_denoising", False))
    cy.samples = 48
    dev = enable_gpu(scene)
    world = scene.world
    old_dist = world.light_settings.distance if world else None
    if world:
        world.light_settings.distance = 6.0
    t0 = time.time()
    try:
        bpy.ops.object.bake(type="AO", uv_layer="UV_AO", margin=4, use_clear=True, target="IMAGE_TEXTURES",
                            use_selected_to_active=False)
    except RuntimeError as e:
        if dev:
            log("GPU bake failed (%s), retrying on the CPU" % e)
            scene.cycles.device = "CPU"
            bpy.ops.object.bake(type="AO", uv_layer="UV_AO", margin=4, use_clear=True, target="IMAGE_TEXTURES",
                                use_selected_to_active=False)
        else:
            raise
    log("AO bake (%s, %dpx) in %.1fs" % (dev or "CPU", AO_SIZE, time.time() - t0))
    cy.samples = old[0]
    if world and old_dist is not None:
        world.light_settings.distance = old_dist
    scene.render.engine = old_engine
    # gentle blur against sampling noise, then save
    import numpy as np
    px = np.empty(AO_SIZE * AO_SIZE * 4, dtype=np.float32)
    img.pixels.foreach_get(px)
    a = px.reshape(AO_SIZE, AO_SIZE, 4)[..., 0]
    b = (a + np.roll(a, 1, 0) + np.roll(a, -1, 0) + np.roll(a, 1, 1) + np.roll(a, -1, 1)) / 5.0
    b = np.clip(0.25 + 0.75 * b, 0.0, 1.0)
    out = np.ones((AO_SIZE, AO_SIZE, 4), dtype=np.float32)
    out[..., 0] = out[..., 1] = out[..., 2] = b
    img.pixels.foreach_set(out.ravel())
    img.filepath_raw = AO_IMAGE
    img.file_format = "PNG"
    img.save()
    for m, n in nodes.items():
        m.node_tree.nodes.remove(n)
    aoimg = load_image(AO_IMAGE, True)
    aoimg.reload()
    # occlusion only on materials used by baked meshes alone (a material shared with an unbaked
    # mesh, e.g. brushed steel on drains and door handles, would sample the atlas with wrong UVs)
    baked = set(objs)
    shared = {m for o in bpy.data.objects if o.type == "MESH" and o not in baked for m in o.data.materials if m}
    for m in mats:
        if m in shared:
            for n in [n for n in m.node_tree.nodes if n.get("na_ao")]:
                m.node_tree.nodes.remove(n)
            continue
        set_occlusion(m, aoimg, uv_map="UV_AO")
    for o in objs:
        o.data.uv_layers.active = o.data.uv_layers["UVMap"]
        o.select_set(False)
    return True


# ---------------------------------------------------------------------------
# Sun, colliders, assets
# ---------------------------------------------------------------------------
def hdri_sun(path):
    """Brightest region of the HDRI. Returns (u, v_from_top) fractions."""
    import numpy as np
    img = bpy.data.images.load(path, check_existing=True)
    w, h = img.size
    px = np.empty(w * h * 4, dtype=np.float32)
    img.pixels.foreach_get(px)
    px = px.reshape(h, w, 4)
    lum = px[..., 0] * 0.2126 + px[..., 1] * 0.7152 + px[..., 2] * 0.0722
    thr = np.percentile(lum, 99.99)
    ys, xs = np.nonzero(lum >= thr)
    wts = lum[ys, xs]
    # circular mean for u
    ang = (xs + 0.5) / w * 2 * math.pi
    u = (math.atan2(float((np.sin(ang) * wts).sum()), float((np.cos(ang) * wts).sum())) / (2 * math.pi)) % 1.0
    v_bottom = float(((ys + 0.5) / h * wts).sum() / wts.sum())
    return u, 1.0 - v_bottom


WANT_SUN_XZ = (-0.55, 0.80)    # three.js: sun toward the front-left of the building (front = +Z)


def sun_and_rotation():
    u, vt = hdri_sun(SKY_HDR)
    el = (0.5 - vt) * math.pi
    theta_s = (u - 0.5) * 2 * math.pi           # three.js equirectUv: u = atan2(z, x)/2pi + 0.5
    theta_d = math.atan2(WANT_SUN_XZ[1], WANT_SUN_XZ[0])
    rho = theta_s - theta_d                     # rotating the sky by rho about +Y moves theta -> theta - rho
    x, z = math.cos(theta_d) * math.cos(el), math.sin(theta_d) * math.cos(el)
    y = math.sin(el)
    az = math.degrees(math.atan2(-x, z)) % 360.0
    return {
        "azimuthDeg": r2(az), "elevationDeg": r2(math.degrees(el)),
        "direction": [round(x, 4), round(y, 4), round(z, 4)],
        "hdriPixel": {"u": round(u, 4), "vFromTop": round(vt, 4)},
        "convention": ("three.js world after applying skyRotationDeg. azimuthDeg: 0 = toward +Z, increasing "
                       "clockwise seen from above (90 = toward -X). direction = unit vector toward the sun "
                       "= (-sin(az)cos(el), sin(el), cos(az)cos(el))."),
    }, {
        "skyRotationDeg": r2(math.degrees(rho) % 360.0),
        "skyRotationNote": ("Apply as scene.backgroundRotation.y = scene.environmentRotation.y = "
                            "skyRotationDeg * PI/180 (three.js r162+; positive = counter-clockwise seen from "
                            "above). Derived with three.js equirectUv u = atan2(dir.z, dir.x)/(2PI) + 0.5 from "
                            "the HDRI's brightest pixel (hdriPixel)."),
    }


def three_rect(minx, maxx, miny, maxy):
    return {"minX": r2(minx), "maxX": r2(maxx), "minZ": r2(-maxy), "maxZ": r2(-miny)}


def save_state():
    bpy.context.scene["na_state"] = json.dumps({"BOUNDS": BOUNDS, "CIRCLES": CIRCLES, "BOXES": BOXES,
                                                "LAWN_POLYS": LAWN_POLYS, "TOPY": TOPY})


def load_state():
    s = bpy.context.scene.get("na_state")
    if not s:
        return
    d = json.loads(s)
    if not BOUNDS:
        BOUNDS.update({k: tuple(v) for k, v in d["BOUNDS"].items()})
    if not CIRCLES:
        CIRCLES.extend(tuple(c) for c in d["CIRCLES"])
    if not BOXES:
        BOXES.extend(tuple(b) for b in d["BOXES"])
    if not LAWN_POLYS:
        LAWN_POLYS.extend((n, [tuple(p) for p in o], [[tuple(p) for p in h] for h in hs]) for (n, o, hs) in d["LAWN_POLYS"])
    for k, v in d.get("TOPY", {}).items():
        TOPY.setdefault(k, v)


def world_verts(objs):
    out = []
    for o in objs:
        if o.type != "MESH":
            continue
        mw = o.matrix_world
        out.extend(mw @ v.co for v in o.data.vertices)
    return out


def pct(vals, p):
    vals = sorted(vals)
    if not vals:
        return 0.0
    return vals[min(len(vals) - 1, max(0, int(p * (len(vals) - 1))))]


def flight_volumes():
    """Solid boxes for a flying avatar (three.js world coordinates after all placements)."""
    vols = []

    def add(name, x0, x1, y0, y1, z0, z1):            # Blender box -> three box
        vols.append({"name": name, "minX": r2(x0), "maxX": r2(x1), "minY": r2(z0), "maxY": r2(z1),
                     "minZ": r2(-y1), "maxZ": r2(-y0)})

    add("assembly-podium", -POD_HX, POD_HX, -POD_HY, POD_HY, 0.0, POD_TOP)
    add("assembly-body", -BODY_HX, BODY_HX, -BODY_HY, BODY_HY, POD_TOP, COL_TOP)
    add("assembly-roof-slab", -SLAB_HX - 0.32, SLAB_HX + 0.32, -SLAB_HY - 0.32, SLAB_HY + 0.32, COL_TOP - 1.0, SLAB_TOP)
    add("assembly-attic", -ATTIC_HALF - 0.25, ATTIC_HALF + 0.25, -ATTIC_HALF - 0.25, ATTIC_HALF + 0.25, ROOF_DECK, ATTIC_TOP)
    # drum: a cross of two boxes whose corners stay within ~1 m of the cylinder
    r = DRUM_R0
    a, b = r - 1.0, math.sqrt(max(0.0, (r + 1.0) ** 2 - (r - 1.0) ** 2))
    add("assembly-drum-x", -a, a, -b, b, ATTIC_TOP, DRUM_TOP)
    add("assembly-drum-y", -b, b, -a, a, ATTIC_TOP, DRUM_TOP)
    # dome: stacked square boxes from the real dome surface (radius at the top of each band)
    dome = bpy.data.objects.get("Dome_Copper")
    vs = world_verts([dome]) if dome else []
    zmax = max((v.z for v in vs), default=DOME_BASE + DOME_H)
    bands = [DOME_BASE, DOME_BASE + 0.33 * DOME_H, DOME_BASE + 0.62 * DOME_H, DOME_BASE + 0.84 * DOME_H, zmax - 0.6]
    for i in range(len(bands) - 1):
        z0, z1 = bands[i], bands[i + 1]
        ring = [math.hypot(v.x, v.y) for v in vs if abs(v.z - z1) < 0.6]
        rt = max(ring) if ring else DOME_R * math.sqrt(max(0.0, 1 - ((z1 - DOME_BASE) / DOME_H) ** 2))
        h = (rt + 1.0) / math.sqrt(2.0)
        add("assembly-dome-%d" % (i + 1), -h, h, -h, h, z0, z1)
    # gate: stone base split around the three passages, arch heads over them, wings, pavilion
    gate = [o for o in bpy.data.collections[COLL_GATE].all_objects if o.type == "MESH"] \
        if bpy.data.collections.get(COLL_GATE) else []
    main = [o for o in gate if o.name.startswith("SM_GHM_Gwanghwamun") and "Doors" not in o.name]
    gv = world_verts(main)
    if gv:
        zb = Z_ARRIVAL
        base_top = zb + 8.66
        core = [v for v in gv if abs(v.x) < 22.0 and v.z < base_top - 0.2]
        bx = pct([abs(v.x) for v in core], 0.995)
        y0, y1 = pct([v.y for v in core], 0.003), pct([v.y for v in core], 0.997)
        pas = [(-10.255, -6.005), (-2.505, 2.495), (6.005, 10.255)]
        gc = os.path.join(GATE_DIR, "gate-colliders.json")
        if os.path.isfile(gc):
            with open(gc, encoding="utf-8") as f:
                pas = [(p["xMin"], p["xMax"]) for p in json.load(f).get("passages", [])] or pas
        edges = [-bx] + [v for p in pas for v in p] + [bx]
        for k in range(0, len(edges), 2):
            add("gate-base-%d" % (k // 2 + 1), edges[k], edges[k + 1], y0, y1, zb, base_top)
        door_top = max((v.z for o in gate if "Doors" in o.name for v in world_verts([o])), default=zb + 7.25)
        add("gate-base-over-passages", pas[0][0], pas[-1][1], y0, y1, door_top + 0.1, base_top)
        wing = [v for v in gv if 22.0 < abs(v.x) < GATE_WINGS_X + 0.5]
        if wing:
            wy0, wy1 = pct([v.y for v in wing], 0.02), pct([v.y for v in wing], 0.98)
            wz = pct([v.z for v in wing], 0.98)
            wx = pct([abs(v.x) for v in wing], 0.999)
            for sx in (-1, 1):
                xa, xb = sorted((sx * bx, sx * wx))
                add("gate-wing-%s" % ("west" if sx < 0 else "east"), xa, xb, wy0, wy1, zb, wz)
        pav = [v for v in gv if v.z > base_top + 0.05]
        if pav:
            lo = [v for v in pav if v.z < base_top + 6.0]
            hi = [v for v in pav if v.z >= base_top + 6.0]
            for nm, grp, z0_, z1_ in (("gate-pavilion-lower", lo, base_top, base_top + 6.0),
                                      ("gate-pavilion-upper", hi, base_top + 6.0, max(v.z for v in pav))):
                if grp:
                    add(nm, pct([v.x for v in grp], 0.01), pct([v.x for v in grp], 0.99),
                        pct([v.y for v in grp], 0.01), pct([v.y for v in grp], 0.99), z0_, z1_)
    # heritage pieces standing taller than a person
    hc = bpy.data.collections.get(COLL_HERITAGE)
    if hc:
        for root in [o for o in hc.objects if o.parent is None and o.name.startswith(("Heritage_Pagoda", "Heritage_Haetae"))]:
            kids = [c for c in root.children_recursive if c.type == "MESH"]
            v = world_verts(kids)
            if v:
                add(root.name.lower().replace("_", "-"), min(p.x for p in v), max(p.x for p in v), min(p.y for p in v),
                    max(p.y for p in v), min(p.z for p in v), max(p.z for p in v))
    return vols


def render_volumes(vols):
    """Top-down and front PNGs of the flight volumes drawn over the scene."""
    c = tag(bpy.data.collections.new("NA_VolumesViz"))
    bpy.context.scene.collection.children.link(c)
    m = new_material("Volume_Viz")
    b = bsdf_of(m)
    sock(b, "Base Color").default_value = (1.0, 0.2, 0.05, 1.0)
    sock(b, "Emission Color").default_value = (1.0, 0.25, 0.05, 1.0)
    sock(b, "Emission Strength").default_value = 0.6
    sock(b, "Alpha").default_value = 0.38
    try:
        m.surface_render_method = "BLENDED"
    except (AttributeError, TypeError):
        pass
    MATS["Volume_Viz"] = m
    mb = MB("Volumes_Viz")
    for v in vols:
        mb.box("Volume_Viz", v["minX"], v["maxX"], -v["maxZ"], -v["minZ"], v["minY"], v["maxY"])
    mb.finish(c)
    colls = (COLL_BUILDING, COLL_SITE, COLL_HERITAGE, COLL_GATE, "NA_VolumesViz")
    render_thumbnail(os.path.join(WORK_DIR, "review", "volumes_top.png"), cam_pos=(0.0, -205.0, 1650.0),
                     target=(0.0, -204.0, 0.0), lens=55.0, samples=48, res=(1600, 1000), colls=colls)
    render_thumbnail(os.path.join(WORK_DIR, "review", "volumes_front.png"), cam_pos=(-260.0, -620.0, 60.0),
                     target=(0.0, -150.0, 20.0), lens=40.0, samples=48, res=(1600, 1000), colls=colls)
    remove_collection(c)


def write_colliders(path):
    load_state()
    pod = BOUNDS["podium"]
    st = BOUNDS["front-stairs"]
    bb = world_bbox([o for o in bpy.data.collections[COLL_BUILDING].objects if o.type == "MESH"])
    sun, rot = sun_and_rotation()
    lawns = []
    for (name, outer, holes) in LAWN_POLYS:
        def conv(loop):
            pts = [[r2(x), r2(-y)] for (x, y) in loop]
            area = 0.5 * sum(pts[i][0] * pts[(i + 1) % len(pts)][1] - pts[(i + 1) % len(pts)][0] * pts[i][1]
                             for i in range(len(pts)))
            return pts if area > 0 else pts[::-1]
        entry = {"name": name, "polygon": conv(outer)}
        if holes:
            entry["holes"] = [conv(h)[::-1] for h in holes]
        lawns.append(entry)
    data = {
        "units": "m",
        "coords": "three.js: y up, building front faces +z",
        "ground": three_rect(*BOUNDS["ground"][:4]),
        "groundHeights": {"paving": Z_PAVE, "lawn": Z_LAWN, "bed": Z_BED, "woodland": Z_WOOD, "water": Z_WATER,
                          "note": "walking surfaces differ by at most 0.1 m; treat as flat y = 0. Every water surface "
                                  "(Water_*) is at y = %.2f (one reflection plane)" % Z_WATER},
        "platforms": [dict(name="podium", **three_rect(*pod[:4]), y=r2(POD_TOP)),
                      dict(name="arrival-terrace", **three_rect(SITE_X0, SITE_X1, SITE_Y0, GATE_Y - 0.45), y=r2(Z_ARRIVAL_G),
                           note="outer forecourt, approach and belts at the gate pack's rim level (gate-local 0.869); "
                                "the gate heightfield (placed at y=-1.517) carries the walker through the passages "
                                "onto the inner grounds at y=0")],
        "ramps": [{"name": "front-stairs", "minX": r2(st[0]), "maxX": r2(st[1]), "zBottom": r2(-st[2]),
                   "zTop": r2(-st[3]), "yBottom": 0.0, "yTop": r2(POD_TOP)}],
        "boxes": [dict(name="main-body", **three_rect(*BOUNDS["main-body"][:4]))]
                 + [dict(name=n, **three_rect(a, b, c, d), **({"topY": r2(TOPY[n])} if n in TOPY else {}))
                    for (n, a, b, c, d) in BOXES],
        "circles": [dict({"name": n, "x": r2(x), "z": r2(-y), "r": r2(r)}, **({"topY": r2(TOPY[n])} if n in TOPY else {}))
                    for (n, x, y, r) in CIRCLES],
        "topYNote": "topY on LOW objects only: block below it, the avatar may land and stand on top; entries without "
                    "topY block at any height; boxes named water-* are pool/basin interiors (topY = water level)",
        "lawns": lawns,
        "lawnPolygonOrder": "counter-clockwise in the (x, z) plane: shoelace sum(x_i*z_(i+1) - x_(i+1)*z_i) > 0; holes clockwise",
        "spawn": {"x": r2(SPAWN[0]), "y": r2(SPAWN_Y), "z": r2(-SPAWN[1]), "faceYaw": r2(math.pi),
                  "viewBackM": r2(SPAWN_VIEW[0]), "viewRiseM": r2(SPAWN_VIEW[1]),
                  "faceYawNote": "rotation.y for a character modelled facing +z; pi = facing the building (-z)"},
        "sun": sun,
        "fountainJets": [{"name": o.name, "x": r2(o.location.x), "y": r2(o.location.z), "z": r2(-o.location.y),
                          "heightM": r2(o.get("jet_height_m", 2.0))}
                         for o in bpy.data.collections[COLL_SITE].objects if o.name.startswith("Fountain_Jet_")],
        "buildingBounds": {"min": [r2(bb[0]), r2(bb[4]), r2(-bb[3])], "max": [r2(bb[1]), r2(bb[5]), r2(-bb[2])]},
    }
    data.update(rot)
    data["volumes"] = flight_volumes()
    data["volumesNote"] = "solid boxes for a flying avatar; the colonnade zone and the gate passages stay open"
    # the Gwanghwamun gate: its own walking heightfield, placed with the same transform as the GLBs
    gpos = [0.0, round(Z_ARRIVAL, 3), round(-GATE_Y, 3)]
    gc = os.path.join(GATE_DIR, "gate-colliders.json")
    if os.path.isfile(gc):
        with open(gc, encoding="utf-8") as f:
            g = json.load(f)
        hfs = []
        for h in g.get("heightfields", []):
            if h.get("variant") != "doors-open":
                continue
            h = dict(h)
            h["position"] = gpos
            h["yawDeg"] = 0
            hfs.append(h)
            src = os.path.join(GATE_DIR, h["file"])
            if os.path.isfile(src):
                import shutil
                shutil.copyfile(src, os.path.join(OUTPUT_DIR, h["file"]))
        data["heightfields"] = hfs
        data["gatePassages"] = {"position": gpos, "yawDeg": 0, "passages": g.get("passages", [])}
    with open(path, "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1)
    g = {}
    if os.path.isfile(gc):
        with open(gc, encoding="utf-8") as f:
            g = json.load(f)
    with open(os.path.join(OUTPUT_DIR, "scenery.json"), "w", encoding="utf-8") as f:
        g1 = {"position": gpos, "yawDeg": 0}
        doors = g.get("doors")
        if doors:
            g1["doors"] = doors
        RESULTS["scenery_doors"] = bool(doors)
        json.dump({"placements": {"scenery-gate-1.glb": g1,
                                  "scenery-gate-2.glb": {"position": gpos, "yawDeg": 0}},
                   "optional": {"scenery-heritage.glb": {"position": [0.0, 0.0, 0.0], "yawDeg": 0,
                                                         "note": "heritage pieces at their final positions"}}},
                  f, indent=1)
    return data


def write_assets_md(path):
    refs = []
    man = os.path.join(REFERENCE_DIR, "manifest.json")
    if os.path.isfile(man):
        try:
            refs = json.load(open(man, encoding="utf-8"))
        except Exception:
            refs = []
    rows = [
        ("granite_tile_03", "texture", "4k", "facade granite, central axis paving (recoloured pale grey)"),
        ("corrugated_iron_02", "texture", "4k", "dome copper (recoloured verdigris)"),
        ("granite_tile_04", "texture", "2k", "podium, stairs, warm grey paving, dark granite kerbs/bands, dressed stone"),
        ("granite_wall", "texture", "2k", "podium retaining walls, boundary wall ashlar"),
        ("concrete_tiles_02", "texture", "2k", "promenade, ring path and branch paths (concrete pavers)"),
        ("leafy_grass", "texture", "2k", "lawn and surrounding meadow (toned greener)"),
        ("farm_soil", "texture", "2k", "planting-bed soil"),
        ("forrest_ground_01", "texture", "1k", "woodland floor under groves and belts (toned darker)"),
        ("gravel_floor_02", "texture", "1k", "fine gravel of the two garden courts"),
        ("kloofendal_43d_clear_puresky", "HDRI", "2k HDR + 8k JPG", "sky_2k.hdr, sky_bg_8k.jpg, render lighting"),
        ("pine_tree_01", "model", "2k (bark 1k)", "Pine, PineTall"),
        ("pine_sapling_small", "model", "1k", "ConiferShrub"),
        ("tree_small_02", "model", "2k (branches 1k)", "Broadleaf"),
        ("island_tree_02", "model", "2k (bark 1k)", "Gnarled"),
        ("searsia_burchellii", "model", "2k (bark 1k)", "Searsia, SearsiaShrub, BoxShrub (low hedges)"),
        ("flower_ursinia", "model", "1k", "FlowerOrange"),
        ("flower_heliophila", "model", "1k", "FlowerWhite"),
        ("periwinkle_plant", "model", "1k", "FlowerPink (ground cover)"),
        ("fern_02", "model", "1k", "Fern"),
        ("grass_medium_02", "model", "1k", "Grass (ornamental grass clumps)"),
        ("boulder_01", "model", "1k", "Boulder"),
        ("namaqualand_boulder_04", "model", "1k", "BoulderLarge"),
        ("street_lamp_01", "model", "2k", "Lamp"),
        ("modular_street_seating", "model", "1k", "Bench (assembled from the kit's parts)"),
    ]
    lines = ["# Third-party assets", "",
             "## Shipped in national-assembly.glb / vegetation-*.glb / sky files - Poly Haven, CC0 1.0", "",
             "| Poly Haven id | Type | Resolution | Used for |", "|---|---|---|---|"]
    lines += ["| %s | %s | %s | %s |" % r for r in rows]
    lines += ["", "Source pages: https://polyhaven.com/a/<id>. Licence: CC0 1.0 (public domain).", "",
              "Generated by the build script (no third-party content): all stonework (fountain basin, reflecting "
              "pool, boundary wall, plinths, foundations, kerbs, bands, slot drains, tree pits), the cast-iron tree "
              "grate, the Taegukgi flag texture (drawn from the official construction rules), the plain Assembly "
              "flag, baked building ambient occlusion, derived (recoloured) textures.", "",
              "## Owner-supplied heritage content (NOT Poly Haven; publication licence to be confirmed by the owner)", "",
              "- scenery-heritage.glb: Heritage_Haetae_A/B, Heritage_Pagoda_East/West, Heritage_Lantern_Wonwonsa, "
              "Heritage_Lantern_TR1429_*, Heritage_Sundial, Heritage_Animal_* - exported by another agent from the "
              "owner's Unreal heritage content; placed here, not modified.",
              "- scenery-gate-1.glb / scenery-gate-2.glb (Gwanghwamun) - supplied as is; this script only decides the "
              "placement (scenery.json) and never re-exports them.", "",
              "## Reference photos (looked at only; NOT shipped, NOT used as textures) - Wikimedia Commons", ""]
    for r in refs:
        lines.append("- %s - %s" % (r.get("title", ""), r.get("page", "")))
    lines.append("")
    with open(path, "w", encoding="utf-8") as f:
        f.write("\n".join(lines))


