def lod_swap(cam_loc):
    """Give every preview instance the LOD the web viewer would show from this camera."""
    swapped = []
    ic = bpy.data.collections.get(COLL_VEGINST)
    if not ic:
        return swapped
    libm = {}
    for ob in ic.objects:
        nm = ob.name[5:].rsplit("_", 1)[0]
        spec = VEG_SPECIES.get(nm)
        if not spec:
            continue
        if nm not in libm:
            libm[nm] = [m for m in (bpy.data.meshes.get("VegLib_%s_LOD%d" % (nm, i)) for i in range(4)) if m]
        if not libm[nm]:
            continue
        d = (ob.location - Vector(cam_loc)).length
        lo = list(spec.get("lod", LOD_DISTANCES))[:len(libm[nm]) - 1]
        i = sum(1 for v in lo if d >= v)
        hide = spec.get("maxd") is not None and d > spec["maxd"]
        if ob.hide_render != hide:
            swapped.append((ob, ob.data))
            ob.hide_render = hide
        if ob.data is not libm[nm][i]:
            swapped.append((ob, ob.data))
            ob.data = libm[nm][i]
    return swapped


def render_thumbnail(path, cam_pos=(175.0, -265.0, 40.0), target=(0.0, -22.0, 24.0), lens=30.0, samples=160,
                     res=(1920, 1200), engine="CYCLES", colls=None):
    sc = bpy.data.scenes.new(TMP_SCENE_PREFIX + "Thumb")
    made = []
    swapped = []
    try:
        for cname in (colls or (COLL_BUILDING, COLL_SITE, COLL_VEG, COLL_VEGINST, COLL_HERITAGE, COLL_GATE)):
            if bpy.data.collections.get(cname):
                sc.collection.children.link(bpy.data.collections[cname])
        swapped = lod_swap(cam_pos)
        cd = tag(bpy.data.cameras.new("NA_ThumbCam"))
        cd.lens = lens
        cd.clip_start = 0.5
        cd.clip_end = 4000.0
        cam = bpy.data.objects.new("NA_ThumbCam", cd)
        sc.collection.objects.link(cam)
        made += [cam, cd]
        cam.location = cam_pos
        look_at(cam, target)
        sc.camera = cam
        world = tag(bpy.data.worlds.new("NA_ThumbWorld"))
        made.append(world)
        nt = world.node_tree
        for n in list(nt.nodes):
            nt.nodes.remove(n)
        out = nt.nodes.new("ShaderNodeOutputWorld")
        bg = nt.nodes.new("ShaderNodeBackground")
        env = nt.nodes.new("ShaderNodeTexEnvironment")
        mp = nt.nodes.new("ShaderNodeMapping")
        tc = nt.nodes.new("ShaderNodeTexCoord")
        env.image = bpy.data.images.load(SKY_HDR, check_existing=True)
        # Blender equirect: u = 0.5 - atan2(d.y, -d.x)/2pi. Rotate so the sun sits front-left (-X, -Y).
        u, vt = hdri_sun(SKY_HDR)
        phi = (0.5 - u) * 2 * math.pi
        sun_az_b = math.atan2(math.sin(phi), -math.cos(phi))
        want_b = math.atan2(-WANT_SUN_XZ[1], WANT_SUN_XZ[0])
        sock(mp, "Rotation").default_value = (0.0, 0.0, sun_az_b - want_b)
        nt.links.new(sock(tc, "Generated", True), sock(mp, "Vector"))
        nt.links.new(sock(mp, "Vector", True), sock(env, "Vector"))
        nt.links.new(sock(env, "Color", True), sock(bg, "Color"))
        sock(bg, "Strength").default_value = 1.0
        nt.links.new(sock(bg, "Background", True), sock(out, "Surface"))
        sc.world = world
        try:
            if engine != "CYCLES":
                raise TypeError("eevee requested")
            sc.render.engine = "CYCLES"
            sc.cycles.samples = samples
            sc.cycles.use_denoising = True
            sc.cycles.max_bounces = 6
            dev = enable_gpu(sc)
            log("render device:", dev or "CPU")
        except (TypeError, AttributeError):
            sc.render.engine = "BLENDER_EEVEE"
            sc.eevee.taa_render_samples = samples
            sc.eevee.use_shadows = True
            try:
                sc.eevee.use_raytracing = True
            except AttributeError:
                pass
        sc.render.resolution_x, sc.render.resolution_y = res
        sc.render.resolution_percentage = 100
        try:
            sc.view_settings.view_transform = "AgX"
            for lk in ("AgX - Medium High Contrast", "Medium High Contrast"):
                try:
                    sc.view_settings.look = lk
                    break
                except TypeError:
                    pass
        except TypeError:
            pass
        isf = sc.render.image_settings
        try:
            isf.media_type = "IMAGE"
        except (AttributeError, TypeError):
            pass
        if path.lower().endswith(".png"):
            isf.file_format = "PNG"
            isf.color_depth = "8"
            isf.compression = 40
        else:
            isf.file_format = "JPEG"
            isf.quality = 92
        t0 = time.time()
        bpy.ops.render.render(scene=sc.name)
        rr = next(i for i in bpy.data.images if i.type == "RENDER_RESULT")
        rr.save_render(path, scene=sc)
        log("thumbnail %.1fs -> %s" % (time.time() - t0, path))
    finally:
        for (ob, me) in swapped:
            ob.data = me
            ob.hide_render = False
        bpy.data.scenes.remove(sc)
        for d in made:
            try:
                if isinstance(d, bpy.types.Object):
                    bpy.data.objects.remove(d, do_unlink=True)
                elif isinstance(d, bpy.types.Camera):
                    bpy.data.cameras.remove(d)
                elif isinstance(d, bpy.types.World):
                    bpy.data.worlds.remove(d)
            except ReferenceError:
                pass


