# Export / verification
# ---------------------------------------------------------------------------
def export_glb(path, objs):
    vl = bpy.context.view_layer
    for o in vl.objects:
        o.select_set(False)
    for o in objs:
        o.select_set(True)
    vl.objects.active = objs[0]
    props = {p.identifier for p in bpy.ops.export_scene.gltf.get_rna_type().properties}
    kw = dict(filepath=path, check_existing=False, export_format="GLB", use_selection=True, export_yup=True,
              export_apply=True, export_animations=False, export_cameras=False, export_lights=False,
              export_extras=False, export_morph=False, export_skins=False, export_draco_mesh_compression_enable=False,
              export_use_gltfpack=False, export_materials="EXPORT", export_normals=True, export_texcoords=True,
              export_tangents=False, export_vertex_color="MATERIAL", export_attributes=False, will_save_settings=False,
              export_image_format=GLB_IMAGE_FORMAT, export_image_quality=GLB_IMAGE_QUALITY,
              export_jpeg_quality=GLB_IMAGE_QUALITY, export_image_add_webp=False)
    kw = {k: v for k, v in kw.items() if k in props}
    bpy.ops.export_scene.gltf(**kw)
    for o in objs:
        o.select_set(False)
    return os.path.getsize(path)


def inspect_glb(path):
    with open(path, "rb") as f:
        data = f.read()
    clen = struct.unpack_from("<I", data, 12)[0]
    js = json.loads(data[20:20 + clen].decode("utf-8"))
    tris = 0
    for mesh in js.get("meshes", []):
        for prim in mesh["primitives"]:
            if prim.get("mode", 4) == 4:
                acc = prim["indices"] if "indices" in prim else prim["attributes"]["POSITION"]
                tris += js["accessors"][acc]["count"] // 3
    node_tris = 0
    mesh_tris = []
    for mesh in js.get("meshes", []):
        t = 0
        for prim in mesh["primitives"]:
            acc = prim["indices"] if "indices" in prim else prim["attributes"]["POSITION"]
            t += js["accessors"][acc]["count"] // 3
        mesh_tris.append(t)
    for n in js.get("nodes", []):
        if "mesh" in n:
            node_tris += mesh_tris[n["mesh"]]
    imgs = js.get("images", [])
    bv = js.get("bufferViews", [])
    mats = []
    for m in js.get("materials", []):
        pbr = m.get("pbrMetallicRoughness", {})
        ent = {"name": m.get("name")}
        for key, src in (("base", pbr.get("baseColorTexture")), ("mr", pbr.get("metallicRoughnessTexture")),
                         ("normal", m.get("normalTexture")), ("occlusion", m.get("occlusionTexture"))):
            if src:
                img = js["textures"][src["index"]].get("source")
                if img is None:
                    ext = js["textures"][src["index"]].get("extensions", {})
                    img = next(iter(ext.values())).get("source") if ext else None
                ent[key] = {"image": img, "texCoord": src.get("texCoord", 0),
                            "bytes": bv[imgs[img]["bufferView"]]["byteLength"] if img is not None else None}
        ent["alphaMode"] = m.get("alphaMode", "OPAQUE")
        ent["doubleSided"] = m.get("doubleSided", False)
        mats.append(ent)
    return {"bytes": len(data), "triangles_unique_meshes": tris, "triangles_in_scene": node_tris,
            "nodes": len(js.get("nodes", [])), "meshes": len(js.get("meshes", [])),
            "node_names": [n.get("name") for n in js.get("nodes", [])][:400],
            "images": [(i.get("name"), i.get("mimeType"), bv[i["bufferView"]]["byteLength"]) for i in imgs],
            "materials": mats, "extensionsUsed": js.get("extensionsUsed", []),
            "extensionsRequired": js.get("extensionsRequired", [])}


def upstream_images(sock_in):
    found, stack, seen = [], [l.from_node for l in sock_in.links], set()
    while stack:
        n = stack.pop()
        if n in seen:
            continue
        seen.add(n)
        if n.type == "TEX_IMAGE" and n.image:
            found.append(n.image)
        for s in n.inputs:
            stack.extend(l.from_node for l in s.links)
    return found


def verify_glb(path):
    """Run in a fresh headless process (private empty profile): import the GLB into the empty
    default scene and report what a loader sees. Nothing is saved."""
    before = {a: set(getattr(bpy.data, a)) for a in ("objects", "materials")}
    rep = {}
    if True:
        bpy.ops.import_scene.gltf(filepath=path)
        objs = [o for o in bpy.data.objects if o not in before["objects"]]
        tris = 0
        for o in objs:
            if o.type == "MESH":
                o.data.calc_loop_triangles()
                tris += len(o.data.loop_triangles)
        mats = {}
        for m in (m for m in bpy.data.materials if m not in before["materials"]):
            if not m.node_tree:
                continue
            b = next((n for n in m.node_tree.nodes if n.type == "BSDF_PRINCIPLED"), None)
            if b is None:
                continue
            ent = {}
            for key, ident in (("base", "Base Color"), ("rough", "Roughness"), ("normal", "Normal")):
                ent[key] = ["%dx%d" % tuple(i.size) for i in upstream_images(sock(b, ident))]
            occ = None
            for n in m.node_tree.nodes:
                if n.type == "GROUP" and n.node_tree and n.node_tree.name.lower().startswith("gltf"):
                    if "Occlusion" in n.inputs:
                        occ = ["%dx%d" % tuple(i.size) for i in upstream_images(n.inputs["Occlusion"])]
            ent["occlusion"] = occ
            mats[m.name] = ent
        meshes = {o.data for o in objs if o.type == "MESH"}
        rep = {"objects": len(objs), "mesh_objects": sum(1 for o in objs if o.type == "MESH"),
               "unique_meshes": len(meshes), "triangles_in_scene": tris,
               "bbox_blender": [r2(v) for v in world_bbox([o for o in objs if o.type == "MESH"])],
               "uv_layers": sorted({u.name for me in meshes for u in me.uv_layers}),
               "colour_attributes": sorted({c.name for me in meshes for c in me.color_attributes}),
               "named": sorted(o.name for o in objs if o.name.split("_")[0] in ("Flag", "Water", "Fountain", "Pool", "Bed",
                                                                              "Paving", "Glass", "Dome"))[:80],
               "materials": mats,
               "nodes": {o.name: len(o.data.loop_triangles) for o in objs
                         if o.type == "MESH" and o.name.startswith(("VegLib_", "Heritage"))},
               "empties": sorted(o.name for o in objs if o.type == "EMPTY")[:80],
               "images": sorted({"%s %dx%d" % (i.name, i.size[0], i.size[1]) for i in bpy.data.images
                                  if i.size[0] > 0})}
    return rep


def stats(coll_name):
    rows, total = [], 0
    c = bpy.data.collections.get(coll_name)
    if not c:
        return rows, 0
    seen = set()
    for o in c.objects:
        if o.type != "MESH":
            continue
        o.data.calc_loop_triangles()
        n = len(o.data.loop_triangles)
        total += n
        if o.data.name not in seen:
            seen.add(o.data.name)
            rows.append("%s tris=%d mats=%s" % (o.name, n, [m.name for m in o.data.materials if m]))
    return rows, total


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
def purge_orphans():
    """Remove data blocks this script owns that nothing uses any more."""
    for _ in range(3):
        for datas in (bpy.data.meshes, bpy.data.materials, bpy.data.images, bpy.data.node_groups):
            for d in list(datas):
                if d.users == 0 and (d.get(OWN_TAG) or d.name.startswith(("NA_", "TMP_", "Tree_", "VEG_"))
                                     or any(k in d.name for k in ("pine_tree_01", "tree_small_02", "jacaranda_tree"))):
                    datas.remove(d)


def strip_suffixes(ids):
    for d in ids:
        if d is None or "." not in d.name:
            continue
        base = d.name.rsplit(".", 1)[0]
        if d.name.rsplit(".", 1)[1].isdigit() and base not in bpy.data.materials:
            d.name = base


def ensure_preview_world():
    """Scene world = the sky HDRI, rotated like the thumbnail (for viewport / look checks)."""
    w = bpy.data.worlds.get("NA_SkyWorld")
    if w is None:
        w = tag(bpy.data.worlds.new("NA_SkyWorld"))
        nt = w.node_tree
        for n in list(nt.nodes):
            nt.nodes.remove(n)
        out = nt.nodes.new("ShaderNodeOutputWorld")
        bg = nt.nodes.new("ShaderNodeBackground")
        env = nt.nodes.new("ShaderNodeTexEnvironment")
        mp = nt.nodes.new("ShaderNodeMapping")
        tc = nt.nodes.new("ShaderNodeTexCoord")
        env.image = bpy.data.images.load(SKY_HDR, check_existing=True)
        sock(mp, "Rotation").default_value = (0.0, 0.0, blender_sky_rotation())
        nt.links.new(sock(tc, "Generated", True), sock(mp, "Vector"))
        nt.links.new(sock(mp, "Vector", True), sock(env, "Vector"))
        nt.links.new(sock(env, "Color", True), sock(bg, "Color"))
        nt.links.new(sock(bg, "Background", True), sock(out, "Surface"))
    bpy.context.scene.world = w
    return w


def blender_sky_rotation():
    """Z rotation for Blender's environment mapping that puts the HDRI sun at WANT_SUN_XZ."""
    u, vt = hdri_sun(SKY_HDR)
    phi = (0.5 - u) * 2 * math.pi           # Blender equirect: u = 0.5 - atan2(d.y, -d.x)/2pi
    sun_az_b = math.atan2(math.sin(phi), -math.cos(phi))
    want_b = math.atan2(-WANT_SUN_XZ[1], WANT_SUN_XZ[0])
    return sun_az_b - want_b


def checkpoint(stage, compress=True):
    """Save the scene after a stage (temp file + atomic replace, no .blend1 backups)."""
    tmp = BLEND_PATH + ".tmp.blend"
    bpy.ops.wm.save_as_mainfile(filepath=tmp, copy=True, check_existing=False, compress=compress)
    os.replace(tmp, BLEND_PATH)
    for p in (BLEND_PATH + "1", tmp + "1"):
        if os.path.exists(p):
            os.remove(p)
    log("checkpoint saved after", stage)


def write_results(stage):
    os.makedirs(WORK_DIR, exist_ok=True)
    with open(os.path.join(WORK_DIR, "results_%s.json" % stage), "w", encoding="utf-8") as f:
        json.dump(RESULTS, f, indent=1, default=str)


def main():
    os.makedirs(TEXTURE_DIR, exist_ok=True)
    t_all = time.time()
    if "build" in STAGES:
        check_inputs()
        if HEADLESS:
            # fresh process with the default scene: drop the default cube, light and camera
            for n in ("Cube", "Light", "Camera"):
                ob = bpy.data.objects.get(n)
                if ob:
                    bpy.data.objects.remove(ob, do_unlink=True)
        cleanup(keep_vegetation=False)
        BOUNDS.clear()
        CIRCLES.clear()
        BOXES.clear()
        LAWN_POLYS.clear()
        TOPY.clear()
        t0 = time.time()
        derive_textures()
        log("textures derived in %.1fs" % (time.time() - t0))
        build_materials()
        ensure_preview_world()
        root = bpy.context.scene.collection
        cb = tag(bpy.data.collections.new(COLL_BUILDING))
        cs = tag(bpy.data.collections.new(COLL_SITE))
        root.children.link(cb)
        root.children.link(cs)
        t0 = time.time()
        build_building(cb)
        log("building in %.1fs" % (time.time() - t0))
        t0 = time.time()
        build_flagpoles(cs)
        build_site(cs)
        build_fountain(cs)
        build_pools(cs)
        build_walls(cs)
        lower_arrival(build_bollards(cs))   # bollards stand on the arrival terrace
        build_heritage_bases(cs)
        log("site in %.1fs" % (time.time() - t0))
        place_heritage()
        place_gate()
        build_gate_fill(cs)
        tc = bpy.data.collections.get("NA_Tmp")
        if tc:
            remove_collection(tc)
        for cname in (COLL_BUILDING, COLL_SITE):
            rows, total = stats(cname)
            log(cname, "triangles:", total)
            for r in rows:
                log("   ", r)
        save_state()
        checkpoint("build")
    if "veglib" in STAGES:
        # one species / prop per headless process: build, cache, QA lineup render
        if not MATS:
            build_materials()
        os.makedirs(os.path.join(WORK_DIR, "veglib"), exist_ok=True)
        for name in CLI.get("--species", ",".join(VEG_SPECIES)).split(","):
            meshes = build_species(name)
            render_lineup(name, meshes[:3], os.path.join(WORK_DIR, "veglib", name + ".jpg"))
            kind = VEG_SPECIES[name]["kind"]
            if kind == "bench":
                render_closeups(name, meshes, ("frontleft", "backright", "front"))
            elif kind in ("prop", "grate", "rock"):
                render_closeups(name, meshes, ("frontleft",), lods=(0,), ground=0.0 if kind == "rock" else None)
    if "vegetation" in STAGES:
        load_state()
        SITE_SHAPES.clear()
        SITE_SHAPES.update(site_shapes())
        CIRCLES[:] = [c for c in CIRCLES if not c[0].startswith(("tree-", "veg-", "hedge-", "shrub-"))]
        BOXES[:] = [b for b in BOXES if not b[0].startswith("hedge-")]
        for k in [k for k in TOPY if k.startswith(("veg-", "hedge-"))]:
            del TOPY[k]
        for cn in (COLL_VEG, COLL_VEGLIB, COLL_VEGINST):
            c = bpy.data.collections.get(cn)
            if c:
                remove_collection(c)
        purge_orphans()
        for m in bpy.data.materials:
            if m.get(OWN_TAG):
                MATS[m.name] = m
        cv = tag(bpy.data.collections.new(COLL_VEG))
        bpy.context.scene.collection.children.link(cv)
        t0 = time.time()
        build_vegetation(cv)
        strip_suffixes([m for m in bpy.data.materials if m.users and m.get(OWN_TAG)])
        purge_orphans()
        tc = bpy.data.collections.get("NA_Tmp")
        if tc:
            remove_collection(tc)
        rows, total = stats(COLL_VEG)
        log("vegetation in %.1fs, scene triangles %d" % (time.time() - t0, total))
        for r in rows:
            log("   ", r)
        save_state()
        checkpoint("vegetation")
    if "bake" in STAGES:
        try:
            RESULTS["ao"] = bake_building_ao()
            checkpoint("bake")
        except Exception as e:
            RESULTS["ao"] = "FAILED: %r" % (e,)
            log("AO bake failed:", e)
    if "colliders" in STAGES:
        RESULTS["colliders"] = write_colliders(os.path.join(OUTPUT_DIR, "colliders.json"))
        render_volumes(RESULTS["colliders"].get("volumes", []))
        write_assets_md(os.path.join(OUTPUT_DIR, "ASSETS.md"))
        log("colliders: %d circles, %d boxes, %d lawns" % (len(CIRCLES), len(BOXES), len(LAWN_POLYS)))
    if "review" in STAGES:
        os.makedirs(os.path.join(WORK_DIR, "review"), exist_ok=True)
        names = CLI.get("--views", ",".join(REVIEW_VIEWS)).split(",")
        if "heritage" in names:
            names.remove("heritage")
            hcoll = bpy.data.collections.get(COLL_HERITAGE)
            for o in (hcoll.objects if hcoll else []):
                if o.type != "MESH":
                    continue
                bb = world_bbox([o])
                c = Vector(((bb[0] + bb[1]) / 2, (bb[2] + bb[3]) / 2, (bb[4] + bb[5]) / 2))
                size = max(bb[1] - bb[0], bb[3] - bb[2], bb[5] - bb[4])
                d = max(3.0, size * 1.6)
                REVIEW_VIEWS["heritage_" + o.name] = ((c.x - 0.6 * d, c.y - 0.8 * d, bb[4] + 1.7), tuple(c), 30.0)
                names.append("heritage_" + o.name)
        doors = [o for o in bpy.data.objects if "Gwanghwamun_Doors" in o.name]
        glass = bpy.data.materials.get("Glass_Dark")
        for nm in names:
            pos, tgt, lens = REVIEW_VIEWS[nm]
            for o in doors:
                o.hide_render = (nm == "under_arch")      # the visitor's view once the leaves have opened
            xray = None
            if nm.startswith("facade_") and glass is not None:
                # worst case for the check: the glazing drawn half see-through (as a transmissive viewer
                # material would), so whatever lies behind it shows in the render
                gnt = glass.node_tree
                gout = next(n for n in gnt.nodes if n.type == "OUTPUT_MATERIAL" and n.is_active_output)
                src = gout.inputs["Surface"].links[0].from_socket
                tr = gnt.nodes.new("ShaderNodeBsdfTransparent")
                mix = gnt.nodes.new("ShaderNodeMixShader")
                mix.inputs["Fac"].default_value = 0.6
                gnt.links.new(src, mix.inputs[1])
                gnt.links.new(tr.outputs[0], mix.inputs[2])
                gnt.links.new(mix.outputs[0], gout.inputs["Surface"])
                xray = (gnt, gout, src, tr, mix)
            try:
                render_thumbnail(os.path.join(WORK_DIR, "review", nm + ".png"), cam_pos=pos, target=tgt, lens=lens,
                                 samples=int(CLI.get("--samples", 96)), res=(1600, 1000), engine="CYCLES")
            finally:
                if xray:
                    gnt, gout, src, tr, mix = xray
                    gnt.links.new(src, gout.inputs["Surface"])
                    gnt.nodes.remove(tr)
                    gnt.nodes.remove(mix)
        for o in doors:
            o.hide_render = False
    if "thumbnail" in STAGES:
        render_thumbnail(os.path.join(OUTPUT_DIR, "thumbnail.jpg"), cam_pos=(118.0, -262.0, 24.0), target=(0.0, -70.0, 20.0),
                         lens=30.0, samples=160)
    glb_b = os.path.join(OUTPUT_DIR, "national-assembly.glb")
    glb_h = os.path.join(OUTPUT_DIR, "scenery-heritage.glb")
    veg_files = lambda: sorted({m["file"] for m in VEG_META.values()})
    only = set((CLI.get("--only") or "building,vegetation,heritage").split(","))
    only_veg = "building" not in only and "heritage" not in only
    if "export" in STAGES and "building" in only:
        b_objs = list(bpy.data.collections[COLL_BUILDING].objects) + list(bpy.data.collections[COLL_SITE].objects)
        log("national-assembly.glb bytes:", export_glb(glb_b, b_objs))
        RESULTS["national-assembly.glb"] = inspect_glb(glb_b)
    if "export" in STAGES:
        exported = export_vegetation() if "vegetation" in only else []
        for p in exported:
            RESULTS[os.path.basename(p)] = inspect_glb(p)
        hc = bpy.data.collections.get(COLL_HERITAGE)
        if hc and hc.objects and "heritage" in only:
            log("scenery-heritage.glb bytes:", export_glb(glb_h, list(hc.objects)))
            RESULTS["scenery-heritage.glb"] = inspect_glb(glb_h)
        for old in ("vegetation.glb", "scenery-statues.glb"):
            p = os.path.join(OUTPUT_DIR, old)
            if os.path.isfile(p):
                os.remove(p)
    if "verify" in STAGES:
        files = ([glb_b] if "building" in only else []) + ([glb_h] if "heritage" in only else []) + \
            (sorted(os.path.join(OUTPUT_DIR, f) for f in os.listdir(OUTPUT_DIR)
                    if f.startswith("vegetation-") and f.endswith(".glb")) if "vegetation" in only else [])
        for p in files:
            if os.path.isfile(p):
                for o in list(bpy.data.objects):
                    bpy.data.objects.remove(o, do_unlink=True)
                RESULTS["verify " + os.path.basename(p)] = verify_glb(p)
    write_results("_".join(sorted(STAGES)))
    log("total %.1fs" % (time.time() - t_all))
    return RESULTS


def export_vegetation():
    """vegetation-N.glb: the library nodes VegLib_<Name>_LOD0..2 (..3 for impostor species) grouped
    by file (each species' LODs and textures self-contained), plus vegetation.json with every
    placement. Distances, draw range, shadow range and wind come from VEG_SPECIES at export time."""
    d = json.loads(bpy.context.scene.get("na_veg", "{}") or "{}")
    VEG_INSTANCES.clear()
    VEG_INSTANCES.update(d.get("instances", {}))
    VEG_META.clear()
    VEG_META.update(d.get("meta", {}))
    libc = bpy.data.collections.get(COLL_VEGLIB)
    out = []
    files = sorted({m["file"] for m in VEG_META.values()})
    for k in files:
        names = [n for n, m in VEG_META.items() if m["file"] == k]
        objs = [libc.objects.get("VegLib_%s_LOD%d" % (n, i)) for n in names for i in range(4)]
        objs = [o for o in objs if o is not None]
        if not objs:
            continue
        for o in objs:
            o.location = (0.0, 0.0, 0.0)
            o.rotation_euler = (0.0, 0.0, 0.0)
            o.scale = (1.0, 1.0, 1.0)
        p = os.path.join(OUTPUT_DIR, "vegetation-%d.glb" % k)
        log(os.path.basename(p), "bytes:", export_glb(p, objs))
        out.append(p)
    r3 = lambda v: round(float(v), 3)
    data = {"units": "m", "coords": "three.js: y up, building front faces +z",
            "note": "instances: [x, y, z, yawRad, scale, tint]; yaw is rotation.y; tint in 0..1 for per-instance colour "
                    "variation; LOD i is drawn from lodDistancesM[i-1] on (LOD0 below lodDistancesM[0]); "
                    "maxDistanceM (optional): not drawn beyond it; castsShadowWithinM: suggested shadow-casting "
                    "range; wind (optional, 0..1, missing = 1): multiplier on the foliage wind",
            "species": {}, "instances": {}}
    for n, m in VEG_META.items():
        spec = VEG_SPECIES.get(n, {})
        nl = len(m["tris"])
        sd = {"file": "vegetation-%d.glb" % m["file"],
              "lods": ["VegLib_%s_LOD%d" % (n, i) for i in range(nl)],
              "lodDistancesM": [r3(v) for v in list(spec.get("lod", m.get("lod", LOD_DISTANCES)))[:nl - 1]],
              "heightM": r3(m["height"]), "trunkRadiusM": r3(m["trunk_r"]),
              "triangles": list(m["tris"])}
        if spec.get("maxd") is not None:
            sd["maxDistanceM"] = r3(spec["maxd"])
        if spec.get("shadow") is not None:
            sd["castsShadowWithinM"] = r3(spec["shadow"])
        if spec.get("wind") is not None:
            sd["wind"] = r3(spec["wind"])
        if nl == 4:
            sd["impostor"] = ("LOD3 = textured box (10 triangles), alpha-clip, double-sided" if spec.get("kind") == "hedge"
                              else "LOD3 = 3 crossed cards through the trunk axis; each half-card is two single-sided "
                                   "faces back to back (5 mm apart) with crown normals (24 triangles), alpha-clip; "
                                   "keep the material single-sided (forcing DoubleSide is harmless but not needed)")
        data["species"][n] = sd
        data["instances"][n] = [[r3(x), r3(z), r3(-y), r3(yaw), r3(s), r3(t)]
                                for (x, y, z, yaw, s, t) in VEG_INSTANCES.get(n, [])]
    with open(os.path.join(OUTPUT_DIR, "vegetation.json"), "w", encoding="utf-8") as f:
        json.dump(data, f, separators=(",", ":"))
    return out


NA_RESULTS = main()
